function isFlagOn(key) {
  try {
    return localStorage.getItem(key) === "1";
  } catch (e) {
    return false;
  }
}

function setFlag(key, on) {
  try {
    if (on) localStorage.setItem(key, "1");
    else localStorage.removeItem(key);
  } catch (e) {}
}

// ---- Usage tracking helpers (supabase/usage-stats-2.sql) -------------------
// The page-view logger in App sets window.__mgbActor ({email, role, page})
// so these can fire from anywhere — TopBar, StaffGuide, Tour — without
// threading props. Everything here is fire-and-forget and never throws.

// Which tab of a hub the hash points at: "#/work/close" while on the work
// page → "close"; a client's "#/client/<id>/files" → "files". Null when the
// hash is for some other page (mid-navigation) or has no tab part.
function MGB_currentTab(page) {
  try {
    const parts = window.location.hash
      .replace(/^#\/?/, "")
      .split("?")[0]
      .split("/")
      .filter(Boolean);
    if (!parts.length || !page) return null;
    if (parts[0] === "client") return parts[2] && parts[2] === page ? parts[3] || null : null;
    if (parts[0] !== page) return null;
    return parts[1] || null;
  } catch (e) {
    return null;
  }
}

// "installed" (the home-screen app), "mobile" (a phone-width browser) or
// "desktop". Usage Stats splits views by this.
function MGB_deviceKind() {
  try {
    if (
      (window.matchMedia && window.matchMedia("(display-mode: standalone)").matches) ||
      window.navigator.standalone === true
    )
      return "installed";
    return window.matchMedia && window.matchMedia("(max-width: 760px)").matches ? "mobile" : "desktop";
  } catch (e) {
    return "unknown";
  }
}

// Counts something someone did rather than a page they opened. `name` is the
// bucket Usage Stats groups by ("palette-open", "guide-miss", ...), `detail`
// the specifics; stored as "name:detail" in usage_events.detail.
function MGB_track(name, detail) {
  try {
    const supabase = window.mgbSupabase;
    const actor = window.__mgbActor;
    if (!supabase || !actor || !name) return;
    const d = detail ? String(detail).slice(0, 200) : "";
    supabase
      .from("usage_events")
      .insert({
        actor_email: actor.email,
        actor_role: actor.role,
        client_id: null,
        page: actor.page || "unknown",
        kind: "action",
        detail: d ? name + ":" + d : name,
        device: MGB_deviceKind(),
      })
      .then(({ error }) => {
        if (error && isFlagOn("mygoodbooks_ff_verbose_logging_v1"))
          console.warn("Couldn't log action:", error.message);
      })
      .catch(() => {});
  } catch (e) {}
}
window.MGB_track = MGB_track;

// Errors the app hits in someone's browser, for the "Recent errors" card on
// Developer tools. Capped per page load so a render loop can't flood the
// table; resource-load failures (no message) are ignored.
let MGB_errorsReported = 0;
function MGB_reportError(message, extra) {
  try {
    if (MGB_errorsReported >= 5) return;
    const supabase = window.mgbSupabase;
    if (!supabase) return;
    const actor = window.__mgbActor || {};
    MGB_errorsReported += 1;
    supabase
      .from("client_errors")
      .insert({
        actor_email: actor.email || null,
        actor_role: actor.role || null,
        page: actor.page || null,
        message: String(message || "Unknown error").slice(0, 500),
        stack: extra && extra.stack ? String(extra.stack).slice(0, 4000) : null,
        source: extra && extra.source ? String(extra.source).slice(0, 300) : null,
        app_version: window.MGB_VERSION ? window.MGB_VERSION.label : null,
        user_agent: (navigator.userAgent || "").slice(0, 300),
        device: MGB_deviceKind(),
      })
      .then(() => {})
      .catch(() => {});
  } catch (e) {}
}
window.addEventListener("error", (e) => {
  if (!e || !e.message) return;
  MGB_reportError(e.message, {
    stack: e.error && e.error.stack,
    source: (e.filename || "") + ":" + (e.lineno || 0),
  });
});
window.addEventListener("unhandledrejection", (e) => {
  const r = e && e.reason;
  MGB_reportError(r && r.message ? r.message : String(r), {
    stack: r && r.stack,
    source: "unhandledrejection",
  });
});

// The billing gate. Deliberately outside <DailyClose />, which has no billing
// logic of its own — same split we will need once this is a real route loader
// checking a subscription record instead of a field on the mock client.
// §166: `allowDevOverride` is false for a client-portal session.
//
// The "Force premium plan" flag is a dev/QA aid, set from Staff Access's
// Developer Tools card — a staff-only page. But it lives in localStorage, and
// localStorage is one console line away for whoever is sitting at the browser,
// so ORing it in unconditionally meant any signed-in client could grant
// themselves the premium tabs by setting a key whose name is right there in
// the source. Gating it on the session keeps the tool working exactly as
// intended for staff (its only real user) and closes the self-grant.
//
// This is a client-side gate on a client-side entitlement, so it is a fix for
// the honest-user case, not a security boundary — the premium tabs still read
// their data through the same RLS as everything else. A real entitlement check
// belongs on the server whenever premium starts being billed for.
function hasPremiumPlan(client, allowDevOverride = true) {
  // Staff "Preview plan" (see getPreviewPlan) wins over the real plan.
  const preview = allowDevOverride ? getPreviewPlan(client.id) : null;
  if (preview) return preview === "premium";
  return (
    client.plan === "premium" ||
    (allowDevOverride && isFlagOn(FEATURE_FLAGS[0].key))
  );
}

// Two plans: Basic (free) and Pro (owner decision 2026-09-30, which took the
// middle Plus plan off "for now"). The stored values stay
// basic/standard/premium so the database never had to migrate them; these
// are the only names a person ever sees. Rename a plan here and nowhere else.
// "standard" (the retired Plus plan) keeps its definitions below so it can
// come back, but PLAN_ORDER leaves it out, so nothing a person can pick or
// see offers it, and planLabel / planSyncInfo / planShownKey treat it (or
// any unknown value) as Basic.
const PLAN_ORDER = ["basic", "premium"];
const PLAN_LABELS = { basic: "Basic", standard: "Plus", premium: "Pro" };
// The plan key a person sees: "premium" stays Pro, anything else reads Basic.
const planShownKey = (plan) => (plan === "premium" ? "premium" : "basic");
const planLabel = (plan) => PLAN_LABELS[planShownKey(plan)];
// Prices, on top of the milestone (bookkeeping) fee. Owner decision
// 2026-09-30: Basic is free with one login included, extra logins $20/mo
// each; Pro is $100/mo plus $20/mo for every login. A client who moves down
// to Basic keeps paying $20 per extra login, or those logins are removed.
// (standard is the retired Plus plan's old price, kept for now, never shown.)
const PLAN_PRICING = {
  basic: { base: 0, perLogin: 20, includedLogins: 1 },
  standard: { base: 25, perLogin: 9, includedLogins: 0 },
  premium: { base: 100, perLogin: 20, includedLogins: 0 },
};
const planMonthlyTotal = (plan, logins) => {
  const p = PLAN_PRICING[plan] || PLAN_PRICING.basic;
  return p.base + p.perLogin * Math.max(0, logins - p.includedLogins);
};
// "Free" for $0, otherwise "$100". Used wherever a plan price is shown.
const planPriceLabel = (amount) => (amount ? `$${amount}` : "Free");
const planLoginLabel = (plan) => {
  const p = PLAN_PRICING[planShownKey(plan)];
  return p.includedLogins
    ? `1 login included · extra logins $${p.perLogin}/mo each`
    : `+ $${p.perLogin}/mo per login`;
};

// How often each plan's numbers refresh from QuickBooks. The schedule itself
// runs server-side in the qbo-sync edge function (isDueForPlan: Basic on the
// 15th, Pro every 15 minutes, 30 while API usage is throttled; its branch
// for the retired Plus plan is unused now); keep the two in step. This is
// the ONLY place freshness copy comes from: use syncCadenceLabel /
// syncPillLabel below, never hand-written "live" text.
const PLAN_SYNC = {
  basic: {
    label: "Monthly sync, on the 15th",
    short: "monthly",
    pill: "Synced monthly",
    cadence: "Synced from QuickBooks monthly, on the 15th",
    syncNow: false,
  },
  standard: {
    label: "Weekly sync",
    short: "weekly",
    pill: "Synced weekly",
    cadence: "Synced from QuickBooks weekly",
    syncNow: false,
  },
  premium: {
    label: "Synced every 15 minutes, plus Sync now",
    short: "every 15 min",
    pill: "Every 15 min",
    cadence: "Synced from QuickBooks every 15 minutes",
    syncNow: true,
  },
};
function planSyncInfo(plan) {
  return PLAN_SYNC[planShownKey(plan)];
}
// "Synced from QuickBooks monthly, on the 15th" etc. For subtitles and
// explanations.
function syncCadenceLabel(plan) {
  return planSyncInfo(plan).cadence;
}
// The header / top bar pill: "Every 15 min · synced 5m ago",
// "Synced monthly · synced 2d ago", or "... · QuickBooks" before a first sync.
function syncPillLabel(plan, lastSyncedAt) {
  const ago = relTime(lastSyncedAt);
  return `${planSyncInfo(plan).pill} · ${ago ? "synced " + ago : "QuickBooks"}`;
}

// Payroll is an add-on for any plan.
// Internal only: the staff Client overview uses it to estimate the monthly
// bill. Owner 2026-10-08: payroll pricing is never shown to clients or
// published; the client sees "message your account manager" instead.
const PAYROLL_PRICING = { base: 49, perEmployee: 6 };

// Basic is barebones: statements, documents and a way to reach the
// bookkeeper. Everything else is hidden rather than shown locked.
// Payroll is an add-on for any plan, so Basic shows it too once they have it.
// "dashboard" is Home since the 2026-10-08 client redesign (every plan lands
// there): Basic gets the Needs-you list and org card, and one locked card
// where the financial snapshot would be.
const BASIC_TAB_KEYS = new Set(["dashboard", "messages", "reports", "documents", "payroll"]);

function isBasicPlan(client, allowDevOverride = true) {
  const preview = allowDevOverride ? getPreviewPlan(client.id) : null;
  if (preview) return preview === "basic";
  return (
    client.plan === "basic" &&
    !(allowDevOverride && isFlagOn(FEATURE_FLAGS[0].key))
  );
}

// The plan in effect, after the staff-only "Force Pro plan" test flag.
function effectivePlan(client, allowDevOverride = true) {
  if (hasPremiumPlan(client, allowDevOverride)) return "premium";
  return isBasicPlan(client, allowDevOverride) ? "basic" : "standard";
}

// Resolves what a given person may see: the org-level baseline the bookkeeper
// set for the whole client, narrowed by that individual's own access record.
// overrideUser: a real, signed-in client_users row (Phase 2 — see
// ClientAuthGate), already resolved by the caller rather than looked up by
// id out of client.users mock data. Same shape as a client.users entry
// (access/tabs/categories/funds/premiumThrottled), so every check below
// that already reads generically off "user" needs no changes for it.
function resolveAccess(client, viewAsUserId, orgHiddenKeys, overrideUser) {
  // Premium tabs drop out entirely for clients not on the plan, before any
  // per-user scoping runs — an unsubscribed org has no one who can see them.
  const basic = isBasicPlan(client, !overrideUser);
  const entitled = ALL_TAB_KEYS.filter(
    (k) =>
      (!PREMIUM_TAB_KEYS.has(k) || hasPremiumPlan(client, !overrideUser)) &&
      (!basic || BASIC_TAB_KEYS.has(k)) &&
      // No Payroll tab at all unless staff turned on the payroll add-on for
      // this client (Add/Edit client), owner request 2026-10-05.
      (k !== "payroll" || !!client.payrollAddOn),
  );
  const orgAllowed = entitled.filter(
    (k) => k === ALWAYS_VISIBLE_KEY || !orgHiddenKeys.has(k),
  );

  const user = overrideUser
    ? overrideUser
    : viewAsUserId && viewAsUserId !== BOOKKEEPER_VIEW
      ? (client.users || []).find((u) => u.id === viewAsUserId)
      : null;

  // The lead account (MyGoodBooks, via Manage Access) can throttle premium
  // features for one of the client's own people even though the client
  // itself is on Premium — e.g. a board member who shouldn't see the Pro
  // tools everyone else at the org gets. Purely per-user: it never changes
  // what the client is billed for. Every hasPremiumPlan(client) check that
  // decides whether to render the upgraded/Pro version of a page should use
  // this instead once a specific person (not "preview as MyGoodBooks") is
  // the one looking.
  const premiumForUser =
    hasPremiumPlan(client, !overrideUser) && !(user && user.premiumThrottled);

  // Per-person access isn't part of Basic: on Basic everyone sees the whole
  // (already small) Basic set.
  if (!user || user.access === "full" || basic) {
    return {
      user,
      tabs: new Set(orgAllowed),
      categories: null,
      funds: null,
      isCategoryScoped: false,
      isFullAccess: true,
      premiumForUser,
      plan: effectivePlan(client, !overrideUser),
    };
  }

  const isCategoryScoped = Boolean(user.categories);
  const userTabs = user.tabs || orgAllowed;
  const tabs = orgAllowed.filter(
    (k) =>
      k === ALWAYS_VISIBLE_KEY ||
      (userTabs.includes(k) && !(isCategoryScoped && ORG_WIDE_TABS.has(k))),
  );

  return {
    user,
    tabs: new Set(tabs),
    categories: isCategoryScoped ? new Set(user.categories) : null,
    // A category-scoped person only ever sees funds explicitly listed for
    // them — no list means none, not "every fund" (unlike categories/tabs,
    // where an empty list falls back to the org default). Getting this
    // backwards is exactly how a ministry-area-scoped user ends up seeing
    // the org-wide fund total on their own dashboard, which the whole point
    // of scoping them says they shouldn't. A non-category-scoped restricted
    // user (tabs-only) isn't affected — they're on the unscoped dashboard,
    // where org-wide figures are expected.
    funds: user.funds
      ? new Set(user.funds)
      : isCategoryScoped
        ? new Set()
        : null,
    isCategoryScoped,
    isFullAccess: false,
    premiumForUser,
    plan: effectivePlan(client, !overrideUser),
  };
}

// Narrows the client's records to just what this person is allowed to see.
// Presentation-layer only — see the Phase 5 note in the access modal.
function scopeClientData(client, access) {
  const cats = access.categories;
  const funds = access.funds;

  // Documents are gated by the bookkeeper-set visibility flag, independent of
  // category scoping — a tab-scoped user with no category limits still only
  // sees the org-wide ones. Anything unmarked defaults to org-wide.
  const documents = access.isFullAccess
    ? client.documents
    : client.documents.filter((d) => d.visibility !== "full");

  if (!cats && !funds) return { ...client, documents };

  // A category-scoped (ministry) person gets none of the organization-wide
  // figures: the monthly income/expense history, open receivables and
  // payables. Their tabs are already hidden (ORG_WIDE_TABS), but these
  // arrays also feed the Budget page's trend chart, the alerts and the
  // What-If model. Emptying them here closes every such path at once;
  // orgWideHidden lets a page say why instead of "no data yet".
  const orgWide = cats
    ? { monthly: [], receivables: [], payables: [], orgWideHidden: true }
    : {};

  return {
    ...client,
    ...orgWide,
    documents,
    budget: cats
      ? client.budget.filter((b) => cats.has(b.category))
      : client.budget,
    bankAccounts: client.bankAccounts.map((a) => ({
      ...a,
      transactions: cats
        ? a.transactions.filter((t) => cats.has(t.category))
        : a.transactions,
    })),
    // A category-limited user can't read bank rows in qbo_accounts (RLS), so
    // their visible transactions arrive here instead of under bankAccounts
    // (mapQboToClient). No account names or balances, just the rows.
    unattachedTransactions: cats
      ? (client.unattachedTransactions || []).filter((t) => cats.has(t.category))
      : client.unattachedTransactions,
    funds: funds ? client.funds.filter((f) => funds.has(f.name)) : client.funds,
    contributions: funds
      ? client.contributions.filter((c) => funds.has(c.fund))
      : client.contributions,
    // QuickBooks giving is one organization-wide total, so a category- or
    // fund-scoped person doesn't get it (the page says why).
    givingQbo: null,
    givingQboHidden: !!client.givingQbo,
  };
}

// Applies a client's custom drag order (if any) to a section's items. Any
// item not mentioned in the stored order (e.g. a tab added after the client
// last customized their order) falls back to the end, in its default spot.
function orderedSectionItems(section, tabOrder, clientId) {
  const customOrder = tabOrder[clientId] && tabOrder[clientId][section.label];
  if (!customOrder) return section.items;
  const byKey = Object.fromEntries(section.items.map((i) => [i.key, i]));
  const ordered = customOrder.filter((k) => byKey[k]).map((k) => byKey[k]);
  const missing = section.items.filter((i) => !customOrder.includes(i.key));
  return [...ordered, ...missing];
}

function Sidebar({
  clients,
  selectedClientId,
  onSelectClient,
  client,
  viewAsUserId,
  onSelectViewAs,
  access,
  page,
  onSelectPage,
  visibleKeys,
  tabOrder,
  onOpenSettingsPage,
  hasPendingAccessRequests,
  pendingRequestsByClient,
  badges,
  mobileOpen,
  onCloseMobile,
  staffUser,
  onSignOut,
  staffMessagesUnread,
  myTasksDue,
  impersonating,
  hasTempAdminAccess,
  tempAdminAccessExpiresAt,
  statusOverrides,
  collapsed,
  onToggleCollapse,
  isStaffSession,
  previewPlan,
  onPreviewPlan,
}) {
  const today = todayLocal();
  // The milestone that heads the sidebar (same numbers as the header badge).
  const sidebarMsIds =
    client && !NON_CLIENT_PAGES.has(page) ? [client.id] : [];
  const { byId: sidebarMsById } = useMilestones(sidebarMsIds);
  const sidebarMs = client ? sidebarMsById[client.id] : null;
  const viewingAsStaff = isStaffSession && viewAsUserId === BOOKKEEPER_VIEW;
  const milestoneHeading = (() => {
    const cur = sidebarMs && sidebarMs.current;
    const clickable = !(access && access.isCategoryScoped);
    if (cur && !(viewingAsStaff && sidebarMs.unconfirmed)) {
      return { text: cur.churchPlant ? cur.name : `${cur.roman} · ${cur.name}`, roman: cur.roman, clickable };
    }
    return { text: viewingAsStaff ? "Set milestone" : "Milestone", roman: cur ? cur.roman : null, clickable };
  })();
  const showsAdminPages =
    staffUser &&
    (staffUser.role === "admin" || hasTempAdminAccess) &&
    !impersonating;
  // Must match App's `isPreviewingUser` guard: a viewAsUserId that no longer
  // resolves to a user (stale id, user removed) falls back to the bookkeeper
  // view rather than dereferencing a missing access.user below.
  //
  // §166: gated on isStaffSession. `viewAsUserId` starts at BOOKKEEPER_VIEW
  // for EVERY session, so without this a signed-in client-portal user read as
  // the bookkeeper and got the staff branches below — the client switcher and
  // the staff menu — plus the staff-only controls on Documents and Messages.
  // It was inert only because the `clients` roster policy is staff-only,
  // which leaves a client's CLIENTS empty and bounces them earlier; that is
  // one policy away from being real, so the flag is now explicit rather than
  // leaning on a table's RLS to stand in for an authorization check.
  const isBookkeeper =
    isStaffSession && (viewAsUserId === BOOKKEEPER_VIEW || !access.user);

  // Home/Team Chat/My Tasks/My Time/admin pages/Sign out used to be a
  // permanently-visible stack of buttons — often the single biggest
  // contributor to the staff sidebar running longer than the screen. They
  // now live in a click-to-open menu under the staffer's own name instead,
  // same one-click depth as before, just tucked away until wanted.
  const [staffMenuOpen, setStaffMenuOpen] = useState(false);
  const staffMenuRef = useRef(null);
  // Mobile drawer (same query as the off-canvas sidebar in styles.css): the
  // staff tabs sit inline in the drawer instead of behind the name dropdown.
  const drawerQuery =
    "(max-width: 760px) and (hover: none), (max-width: 760px) and (pointer: coarse)";
  const [inDrawer, setInDrawer] = useState(
    () =>
      typeof window.matchMedia === "function" &&
      window.matchMedia(drawerQuery).matches,
  );
  useEffect(() => {
    if (typeof window.matchMedia !== "function") return;
    const mq = window.matchMedia(drawerQuery);
    const onChange = () => setInDrawer(mq.matches);
    onChange();
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);
  const staffMenuShown = staffMenuOpen || inDrawer;
  useEffect(() => {
    if (!staffMenuOpen) return;
    const onDocClick = (e) => {
      if (staffMenuRef.current && !staffMenuRef.current.contains(e.target))
        setStaffMenuOpen(false);
    };
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, [staffMenuOpen]);

  // §143: collapsed-sidebar hover labels. A native `title` attribute has
  // a built-in OS delay (and no styling control) — too slow to scan a
  // whole icon column quickly, which is the exact complaint this
  // replaces. Rendered via a portal straight into document.body rather
  // than as a normally-positioned absolute child, specifically so it
  // can't fall into the same trap §142's own writeup flags for this
  // sidebar: `.nav`'s `overflow-y: auto` implicitly clips `overflow-x`
  // too (the same CSS auto-pairing rule that broke the reverted
  // split-rail sidebar's tooltips, HANDOFF7.md's note on §125). A portal
  // node isn't a descendant of `.nav` in the DOM at all, so that clipping
  // ancestor can't touch it regardless of position/transform quirks.
  const [hoverTip, setHoverTip] = useState(null); // { text, rect } | null
  function showTip(e, text) {
    // §157: `collapsed` is a stored preference, not "is the sidebar
    // actually rendering collapsed right now" — §154 made the CSS ignore
    // it below 761px (phones get the full labeled drawer instead), but
    // this check never learned that, so a tap on a phone (which fires
    // onFocus, same as a real hover would) still opened a tooltip whose
    // label was already visible right next to it. Worse on touch: there's
    // no mouseleave to dismiss it, so it stuck on screen until something
    // else happened to blur it. window.innerWidth is checked fresh on
    // every call rather than cached, since it's only read on an actual
    // hover/focus event, not on every render.
    if (!collapsed || !text || window.innerWidth < 761) return;
    setHoverTip({ text, rect: e.currentTarget.getBoundingClientRect() });
  }
  function hideTip() {
    setHoverTip(null);
  }
  // §158: the phone-width check in showTip above stops this from firing on
  // a phone, but a real touch tablet (761-1024px, pointer: coarse) still
  // legitimately gets the collapsed sidebar by design (§154) — so a tap
  // opens a tooltip the same way a mouse hover would for a desktop user,
  // and touch has no mouseleave to close it afterward. Tapping the SAME
  // already-focused nav icon again (the exact reported case — tap
  // "Budget vs. Actual" to navigate there, tooltip stays stuck over the
  // page that loads underneath) doesn't even re-fire onFocus, since focus
  // never left that element, so a "was this tap outside the sidebar"
  // check wouldn't have caught it either. Simplest correct rule: any
  // tap/click anywhere — sidebar included — dismisses the current tip.
  // The listener fires on mousedown/touchstart, before the focus event a
  // *different* icon's own onFocus handler would use to show its own new
  // tip, so tapping icon B while icon A's tip is showing still correctly
  // ends up displaying B's tip, not stuck on A's. Only attached while
  // hoverTip is actually set, not a permanent listener on every render.
  useEffect(() => {
    if (!hoverTip) return;
    const onTap = () => setHoverTip(null);
    document.addEventListener("touchstart", onTap, { passive: true });
    document.addEventListener("mousedown", onTap);
    return () => {
      document.removeEventListener("touchstart", onTap);
      document.removeEventListener("mousedown", onTap);
    };
  }, [hoverTip]);
  useEffect(() => {
    if (!collapsed) setHoverTip(null);
  }, [collapsed]);

  return (
    <aside
      className={
        "sidebar" +
        (mobileOpen ? " open" : "") +
        (collapsed ? " sidebar-collapsed" : "")
      }
    >
      <div className="brand">
        <a
          className="brand-link"
          href="https://mygoodbooks.org"
          target="_blank"
          rel="noopener noreferrer"
        >
          {/* Gold logo in a gold box, same as the staff rail and sign-in. */}
          <span className="staff-rail-mark brand-logo-box" aria-hidden="true" />
          <div className="brand-text">
            <span className="brand-name">My<span className="brand-name-good">Good</span>Books</span>
            <span className="brand-sub">Client Portal</span>
          </div>
        </a>
        <button
          className="sidebar-close"
          onClick={onCloseMobile}
          aria-label="Close menu"
        >
          ✕
        </button>
      </div>

      <div className="brand-tagline">
        <span className="brand-tagline-line">Do good work.</span>
        <span className="brand-tagline-line">Leave the bookkeeping to us.</span>
      </div>

      {/* Milestone pill (moved here from the page header, 2026-09-30): the
          open client's milestone, above the client name / switcher. Hidden
          on staff pages, for category-scoped users, and when collapsed. */}
      {client && !NON_CLIENT_PAGES.has(page) && !(access && access.isCategoryScoped) && !collapsed && (
        <div className="sidebar-ms-row">
          <MilestoneBadge
            client={client}
            staff={viewingAsStaff}
            onOpen={() => {
              onSelectPage("milestone");
              if (onCloseMobile) onCloseMobile();
            }}
          />
        </div>
      )}

      {isBookkeeper ? (
        <React.Fragment>
          {/* Staff Access isn't about any client — showing a client picker
              there (and whichever client happened to be last selected) is
              exactly the confusing "why is a client's sidebar showing, I
              didn't pick one" report. Home drops it too, now that it has its
              own "Your clients" card (search + status at a glance) — a
              second, redundant way to do the same jump wasn't worth the
              sidebar space, and a dropdown is a worse version of that card
              on mobile besides. */}
          {(!NON_CLIENT_PAGES.has(page) || inDrawer) && (
            // components/staff/ClientSwitcher.jsx. §169's per-client
            // portal request count now rides on each row as a small pill.
            // The phone drawer shows it on staff pages too ("Choose a
            // client"), since desktop's staff sidebar picker isn't there.
            <CS_ClientSwitcher
              clients={clients}
              currentClient={NON_CLIENT_PAGES.has(page) ? null : client}
              onPick={(id) => {
                if (id !== selectedClientId) onSelectClient(id);
                else if (NON_CLIENT_PAGES.has(page)) onSelectPage("client-overview");
                onCloseMobile();
              }}
              staffUser={staffUser}
              statusOverrides={statusOverrides}
              pendingRequestsByClient={pendingRequestsByClient}
              compact={collapsed && !inDrawer}
              inline={inDrawer}
              onExpand={onToggleCollapse}
              canRequest={!impersonating}
            />
          )}

          {staffUser && (
            <div
              className={"staff-user-menu" + (inDrawer ? " inline" : "")}
              ref={staffMenuRef}
            >
              <button
                type="button"
                className="staff-user-chip"
                onClick={() => {
                  if (!inDrawer) setStaffMenuOpen((open) => !open);
                }}
                aria-expanded={inDrawer ? undefined : staffMenuOpen}
                aria-haspopup={inDrawer ? undefined : "true"}
                aria-label={collapsed ? staffUser.name : undefined}
                onMouseEnter={(e) => showTip(e, staffUser.name)}
                onMouseLeave={hideTip}
                onFocus={(e) => showTip(e, staffUser.name)}
                onBlur={hideTip}
              >
                <span className="staff-user-avatar">
                  {staffUser.name
                    .split(" ")
                    .map((p) => p[0])
                    .slice(0, 2)
                    .join("")}
                </span>
                <span className="staff-user-chip-text">
                  <span className="staff-user-chip-name">{staffUser.name}</span>
                  <span className="staff-user-chip-role">{staffUser.role}</span>
                </span>
                {staffMessagesUnread && !staffMenuShown && (
                  <span className="nav-badge-dot" aria-label="Unread" />
                )}
                {!staffMenuShown && !collapsed && !impersonating && (
                  <MyTasksDueCount due={myTasksDue} />
                )}
                {!inDrawer && (
                  <ChevronDownIcon
                    className={
                      "staff-user-chip-chev" + (staffMenuOpen ? " open" : "")
                    }
                  />
                )}
              </button>

              {staffMenuShown && (
                <div
                  className="staff-user-dropdown"
                  role={inDrawer ? undefined : "menu"}
                >
                  {/* The same five places as the desktop rail (StaffRail /
                      components/staff/StaffNav.jsx), with the same
                      data-tour names so the staff tour can point at them
                      in the phone drawer. Help, Feedback and the tour live
                      in the top bar's "?" menu; the admin pages under
                      Settings > Firm settings. */}
                  {(typeof NAV_visiblePlaces === "function"
                    ? NAV_visiblePlaces({
                        role: staffUser.role,
                        isAdmin: showsAdminPages,
                        impersonating: !!impersonating,
                      })
                    : []
                  ).map((p) => (
                    <button
                      key={p.key}
                      type="button"
                      role="menuitem"
                      className={"staff-user-menu-item" + (page === p.key ? " active" : "")}
                      data-tour={"staff-nav-" + p.key}
                      aria-current={page === p.key ? "page" : undefined}
                      onClick={() => {
                        onSelectPage(p.key);
                        onCloseMobile();
                        setStaffMenuOpen(false);
                      }}
                    >
                      {p.icon ? p.icon() : null}
                      {p.label}
                      {p.key === "today" && typeof CS_ApprovalsDot === "function" && <CS_ApprovalsDot />}
                      {p.key === "inbox" && staffMessagesUnread && (
                        <span
                          className="nav-badge-dot"
                          aria-label="Unread"
                          style={{ marginLeft: "auto" }}
                        />
                      )}
                      {p.key === "work" && <MyTasksDueCount due={myTasksDue} />}
                      {p.key === "team" && typeof TR_NavBadge === "function" && <TR_NavBadge expanded />}
                      {p.key === "team" &&
                        showsAdminPages &&
                        staffUser.role === "admin" &&
                        typeof FB_NavBadge === "function" && <FB_NavBadge expanded />}
                    </button>
                  ))}

                  <div className="staff-user-menu-divider" />
                  <button
                    type="button"
                    role="menuitem"
                    className={"staff-user-menu-item" + (page === "settings" ? " active" : "")}
                    data-tour="staff-nav-settings"
                    onClick={() => {
                      onSelectPage("settings");
                      onCloseMobile();
                      setStaffMenuOpen(false);
                    }}
                  >
                    <ST_GearIcon />
                    Settings
                  </button>
                  <button
                    type="button"
                    role="menuitem"
                    className="staff-user-menu-item"
                    onClick={() => {
                      setStaffMenuOpen(false);
                      onSignOut();
                    }}
                  >
                    <SignOutIcon />
                    Sign out
                  </button>
                </div>
              )}
            </div>
          )}

          {hasTempAdminAccess &&
            staffUser &&
            staffUser.role !== "admin" &&
            !impersonating && (
              <div className="staff-temp-access-banner" title="Read-only">
                Temporary access — expires{" "}
                {formatTempAccessExpiry(tempAdminAccessExpiresAt)}
              </div>
            )}

          {!NON_CLIENT_PAGES.has(page) && (
            <React.Fragment>
              <div className="client-picker-label tb-preview-as">Preview as</div>
              <select
                className="client-select tb-preview-as"
                value={viewAsUserId}
                onChange={(e) => onSelectViewAs(e.target.value)}
              >
                {/* Real name/email for the signed-in staffer replaces the old
                    shared "MyGoodBooks (full access)" sentinel label — the
                    underlying value stays BOOKKEEPER_VIEW so resolveAccess() and
                    everything downstream is untouched. */}
                <option value={BOOKKEEPER_VIEW}>
                  {staffUser
                    ? `${staffUser.name} (full access)`
                    : "MyGoodBooks (full access)"}
                </option>
                {(client.users || []).map((u) => (
                  <option key={u.id} value={u.id}>
                    {u.name} — {u.role}
                  </option>
                ))}
              </select>
              {/* Staff-only: see this client's pages as if on another plan,
                  in this browser only. Nothing the client pays changes. */}
              <div className="client-picker-label tb-preview-as">Preview plan</div>
              <select
                className={"client-select tb-preview-as" + (previewPlan ? " preview-plan-on" : "")}
                value={previewPlan || ""}
                onChange={(e) => onPreviewPlan(e.target.value || null)}
              >
                <option value="">
                  Actual plan ({planLabel(client.plan)})
                </option>
                {PLAN_ORDER.map((p) => (
                  <option key={p} value={p}>
                    Preview as {PLAN_LABELS[p]}
                  </option>
                ))}
              </select>
            </React.Fragment>
          )}
        </React.Fragment>
      ) : (
        <div className="signed-in-as">
          <div className="signed-in-avatar">
            {access.user.name
              .split(" ")
              .map((p) => p[0])
              .slice(0, 2)
              .join("")}
          </div>
          <div className="signed-in-text">
            <span className="signed-in-name">{access.user.name}</span>
            <span className="signed-in-role">{access.user.role}</span>
          </div>
        </div>
      )}

      {NON_CLIENT_PAGES.has(page) ? null : (
        <nav className="nav" onScroll={hideTip}>
          {/* Calm step 2: the sidebar reads as two groups. The first
              rendered non-Enterprise section gets a small heading reusing
              the existing "Finances" section label — presentation only, no
              change to NAV_SECTIONS, ordering or visibility. */}
          {/* The five places (CLIENT_PLACES). A tabbed place (Finances)
              opens its last-used visible tab; the tab row renders in the
              top bar (App). The milestone and plan moved to Home's org
              card and Settings › Plan. */}
          <div className="nav-section">
            <div className="nav-section-items" id="nav-section-places">
              {CLIENT_PLACES.map((place) => {
                const pages = place.tabs
                  ? place.tabs.filter((k) => visibleKeys.has(k))
                  : visibleKeys.has(place.page)
                    ? [place.page]
                    : [];
                if (pages.length === 0) return null;
                const active = CLIENT_PLACE_OF_PAGE[page] === place.key;
                const hasBadge = pages.some((k) => badges[k]);
                return (
                  <button
                    key={place.key}
                    data-tour={"nav-" + place.key}
                    className={"nav-item" + (active ? " active" : "")}
                    onClick={() => {
                      onSelectPage(place.tabs ? CLIENT_lastTab(place.key, pages) : place.page);
                      onCloseMobile();
                    }}
                    aria-label={collapsed ? place.label : undefined}
                    aria-current={active ? "page" : undefined}
                  >
                    {place.icon}
                    <span className="nav-item-label">{place.label}</span>
                    <span className="nav-item-caption" aria-hidden="true">{place.label}</span>
                    {hasBadge && <span className="nav-badge-dot" aria-label="Unread"></span>}
                  </button>
                );
              })}
            </div>
          </div>
        </nav>
      )}

      {/* Settings (components/settings/Settings.jsx), owner request
          2026-09-30. On a client's pages the gear opens client Settings: a
          client's profile, notifications, plan, theme and sign-out; for staff
          in the bookkeeper view, the Client settings tab (Manage access +
          Client details, which used to be two links here) and Plan. The
          theme toggle and the client Sign out button moved into it. Staff
          reach their own Settings from the user menu above. */}
      {!NON_CLIENT_PAGES.has(page) && (
        <div className="sidebar-settings-row">
          <button
            type="button"
            data-tour="settings"
            className={
              "sidebar-settings-btn" +
              (page === "client-settings" ? " active" : "") +
              (isBookkeeper && hasPendingAccessRequests ? " pending-alert" : "")
            }
            onClick={() => {
              onOpenSettingsPage();
              onCloseMobile();
            }}
            aria-current={page === "client-settings" ? "page" : undefined}
            aria-label={
              isBookkeeper && hasPendingAccessRequests
                ? "Settings — new access request pending"
                : collapsed
                  ? "Settings"
                  : undefined
            }
            onMouseLeave={hideTip}
            onBlur={hideTip}
          >
            <ST_GearIcon width="18" height="18" />
            <span className="sidebar-settings-label">Settings</span>
            <span className="nav-item-caption" aria-hidden="true">Settings</span>
          </button>
        </div>
      )}

      <button
        className="sidebar-collapse-toggle"
        onClick={onToggleCollapse}
        aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
        onMouseEnter={(e) => showTip(e, collapsed ? "Expand" : "Collapse")}
        onMouseLeave={hideTip}
        onFocus={(e) => showTip(e, collapsed ? "Expand" : "Collapse")}
        onBlur={hideTip}
      >
        <ChevronDownIcon className="sidebar-collapse-toggle-icon" />
        {!collapsed && <span>Collapse</span>}
      </button>

      {hoverTip &&
        ReactDOM.createPortal(
          <div
            className="icon-hover-tip"
            style={{
              top: hoverTip.rect.top + hoverTip.rect.height / 2,
              left: hoverTip.rect.right + 10,
            }}
          >
            {hoverTip.text}
          </div>,
          document.body,
        )}
    </aside>
  );
}

// Staff sidebar (owner request 2026-09-27). Staff pages get it in place of
// the client sidebar (icons only when collapsed); a client's pages get it as
// an icon strip beside the client sidebar. Hidden while previewing as one of
// the client's people (see App). Desktop only; the phone drawer keeps the
// staff links in the menu under the staffer's name (see Sidebar).
function StaffRail({
  staffUser,
  page,
  onSelectPage,
  expanded,
  onToggleCollapse,
  staffMessagesUnread,
  myTasksDue,
  impersonating,
  showsAdminPages,
  onSignOut,
  hideMark,
}) {
  const [tip, setTip] = useState(null);
  const showTip = (e, text) => {
    if (expanded) return;
    setTip({ text, rect: e.currentTarget.getBoundingClientRect() });
  };
  const hideTip = () => setTip(null);
  useEffect(() => {
    if (expanded) setTip(null);
  }, [expanded]);
  const onClientPage = !NON_CLIENT_PAGES.has(page);
  // Client pages with the client sidebar collapsed beside the rail: two
  // icon columns side by side. Their headers differ (logo box vs. avatar /
  // milestone pill), so nudge whichever icon list starts higher down until
  // the first rows line up. Since the staff nav redesign (2026-10-08) the
  // client sidebar is hidden on desktop while staff are on a client's pages
  // (html.staff-client-tabs), so this is a no-op whenever the sidebar isn't
  // laid out (offsetParent === null) and only still matters if both columns
  // are ever shown together again.
  const railRef = useRef(null);
  React.useLayoutEffect(() => {
    const rail = railRef.current;
    const shell = rail && rail.parentElement;
    if (!shell) return;
    const railNav = rail.querySelector(".staff-rail-nav");
    let raf = 0;
    const firstTop = (nav, sel) => {
      const el = nav && nav.querySelector(sel);
      if (!el) return null;
      return el.getBoundingClientRect().top + nav.scrollTop - (parseFloat(nav.style.marginTop) || 0);
    };
    const setPad = (nav, px) => {
      const v = px > 0.5 ? Math.round(px) + "px" : "";
      if (nav && nav.style.marginTop !== v) nav.style.marginTop = v;
    };
    const run = () => {
      const sb = shell.querySelector(":scope > .sidebar");
      const sbNav = sb && sb.querySelector(".nav");
      const on =
        !expanded &&
        onClientPage &&
        sb &&
        sb.offsetParent !== null &&
        sb.classList.contains("sidebar-collapsed");
      const a = on ? firstTop(railNav, ".staff-rail-item") : null;
      const b = on ? firstTop(sbNav, ".nav-item") : null;
      if (a == null || b == null) {
        setPad(railNav, 0);
        setPad(sbNav, 0);
        return;
      }
      setPad(railNav, b - a);
      setPad(sbNav, a - b);
    };
    const align = () => {
      clearTimeout(raf);
      raf = setTimeout(run, 16);
    };
    run();
    const ro = new ResizeObserver(align);
    ro.observe(rail);
    const sb = shell.querySelector(":scope > .sidebar");
    if (sb) Array.from(sb.children).forEach((ch) => ro.observe(ch));
    const mo = new MutationObserver(align);
    mo.observe(shell, { childList: true, subtree: true, attributes: true, attributeFilter: ["class"] });
    window.addEventListener("resize", align);
    return () => {
      clearTimeout(raf);
      ro.disconnect();
      mo.disconnect();
      window.removeEventListener("resize", align);
    };
  }, [expanded, onClientPage]);
  // The five places (components/staff/StaffNav.jsx): Today, Inbox, Work,
  // Clients, Team — the same list on staff pages and a client's pages, so
  // the rail never changes shape under someone. Inbox, Work and Team step
  // aside while an admin is in "View as" (see NAV_PLACES). What each place
  // adds to its row: Today the client-access approvals dot (admins), Inbox
  // the unread dot, Work the tasks-due count, Team the review / feedback
  // badges. Help, Feedback and the tour live in the top bar's "?" menu;
  // Task templates, Client roster, Emails, Usage stats, Audit log and
  // Developer tools under Settings > Firm settings (owner request
  // 2026-09-30).
  const places =
    typeof NAV_visiblePlaces === "function"
      ? NAV_visiblePlaces({ role: staffUser.role, isAdmin: showsAdminPages, impersonating: !!impersonating })
      : [];
  const items = places.map((p) => {
    const it = { key: p.key, label: p.label, short: p.label, icon: p.icon ? p.icon() : null };
    if (p.key === "today" && typeof CS_ApprovalsDot === "function") {
      it.extra = <CS_ApprovalsDot className="nav-badge-dot staff-rail-dot" />;
    } else if (p.key === "inbox") {
      it.dot = staffMessagesUnread;
    } else if (p.key === "work") {
      it.due = true;
    } else if (p.key === "team") {
      it.extra = (
        <>
          {typeof TR_NavBadge === "function" && <TR_NavBadge expanded={expanded} />}
          {showsAdminPages && staffUser.role === "admin" && typeof FB_NavBadge === "function" && (
            <FB_NavBadge expanded={expanded} />
          )}
        </>
      );
    }
    return it;
  });
  const initials = (staffUser.name || "")
    .split(" ")
    .map((p) => p[0])
    .slice(0, 2)
    .join("");
  const renderItem = (it) => {
    const active = it.active != null ? it.active : page === it.key;
    return (
      <button
        key={it.key}
        type="button"
        className={"staff-rail-item" + (active ? " active" : "")}
        data-tour={"staff-nav-" + it.key}
        onClick={() => {
          hideTip();
          onSelectPage(it.key);
        }}
        aria-label={expanded ? undefined : it.label}
        aria-current={active ? "page" : undefined}
        onMouseEnter={(e) => it.short && showTip(e, it.label)}
        onMouseLeave={hideTip}
        onFocus={(e) => it.short && showTip(e, it.label)}
        onBlur={hideTip}
      >
        {it.icon}
        {expanded ? (
          <span className="staff-rail-label">{it.label}</span>
        ) : (
          <span className="staff-rail-caption" aria-hidden="true">{it.short || it.label}</span>
        )}
        {it.dot && <span className="nav-badge-dot staff-rail-dot" aria-label="Unread" />}
        {it.extra}
        {it.due && expanded && <MyTasksDueCount due={myTasksDue} />}
        {it.due && !expanded && myTasksDue && myTasksDue.due > 0 && (
          <span className="nav-badge-dot staff-rail-dot" aria-label={`${myTasksDue.due} tasks due`} />
        )}
      </button>
    );
  };
  return (
    <aside
      ref={railRef}
      className={"staff-rail" + (expanded ? " expanded" : "")}
      aria-label="Staff navigation"
    >
      <div className="staff-rail-brand">
        {expanded ? (
          <span className="staff-rail-brand-row">
            {/* Same logo box + wordmark as the client sidebar's brand. */}
            <span className="staff-rail-mark brand-logo-box" aria-hidden="true" />
            <span className="brand-text">
              <span className="brand-name">My<span className="brand-name-good">Good</span>Books</span>
              <span className="brand-sub">Staff</span>
            </span>
          </span>
        ) : hideMark ? null : (
          <span className="staff-rail-mark" role="img" aria-label="MyGoodBooks" />
        )}
      </div>
      {/* Picking a client happens on the Clients page and in the top bar's
          client picker, so the rail itself lists only places. */}
      <nav className="staff-rail-nav" data-tour="staff-nav">
        {items.map(renderItem)}
      </nav>
      <div className="staff-rail-foot">
        {/* Theme moved to Settings > Appearance (and the top bar's avatar
            menu), 2026-09-30. */}
        <button
          type="button"
          className={"staff-rail-item" + (page === "settings" ? " active" : "")}
          data-tour="staff-nav-settings"
          onClick={() => onSelectPage("settings")}
          aria-label={expanded ? undefined : "Settings"}
          aria-current={page === "settings" ? "page" : undefined}
          onMouseEnter={(e) => showTip(e, "Settings")}
          onMouseLeave={hideTip}
          onFocus={(e) => showTip(e, "Settings")}
          onBlur={hideTip}
        >
          <ST_GearIcon width="18" height="18" />
          {expanded ? (
            <span className="staff-rail-label">Settings</span>
          ) : (
            <span className="staff-rail-caption" aria-hidden="true">Settings</span>
          )}
        </button>
        <div
          className="staff-rail-user"
          onMouseEnter={(e) => showTip(e, `${staffUser.name} · ${staffUser.role}`)}
          onMouseLeave={hideTip}
        >
          <span className="staff-user-avatar">{initials}</span>
          {expanded && (
            <span className="staff-user-chip-text">
              <span className="staff-user-chip-name">{staffUser.name}</span>
              <span className="staff-user-chip-role">{staffUser.role}</span>
            </span>
          )}
        </div>
        <button
          type="button"
          className="staff-rail-item"
          onClick={onSignOut}
          aria-label={expanded ? undefined : "Sign out"}
          onMouseEnter={(e) => showTip(e, "Sign out")}
          onMouseLeave={hideTip}
          onFocus={(e) => showTip(e, "Sign out")}
          onBlur={hideTip}
        >
          <SignOutIcon />
          {expanded ? (
            <span className="staff-rail-label">Sign out</span>
          ) : (
            <span className="staff-rail-caption" aria-hidden="true">Sign out</span>
          )}
        </button>
        {/* On client pages too: the rail is the only sidebar there now. */}
        {onToggleCollapse && (
          <button
            type="button"
            className="sidebar-collapse-toggle staff-rail-collapse"
            onClick={onToggleCollapse}
            aria-label={expanded ? "Collapse sidebar" : "Expand sidebar"}
            onMouseEnter={(e) => showTip(e, "Expand")}
            onMouseLeave={hideTip}
          >
            <ChevronDownIcon className="sidebar-collapse-toggle-icon" />
            {expanded && <span>Collapse</span>}
          </button>
        )}
      </div>
      {tip &&
        ReactDOM.createPortal(
          <div
            className="icon-hover-tip"
            style={{
              top: tip.rect.top + tip.rect.height / 2,
              left: tip.rect.right + 10,
            }}
          >
            {tip.text}
          </div>,
          document.body,
        )}
    </aside>
  );
}

