// ----------------------------------------------------------------------------
// Fund Accounting Pro — adds two views next to the same fund balances and
// contributions Giving & Funds already shows: Fund Activity (transfers
// between funds) and Pledges (committed vs. received). Same
// Fund Balances/Contributions views as standard, so this stays a strict
// superset — see HANDOFF7 §54/§55 on that bar. Fund balance trend over time
// (the fund-accounting equivalent of Budget's Spending Trend) isn't included
// here: unlike a bank or budget trend, it would need each fund's balance
// sampled monthly, which this mock dataset doesn't carry — only a snapshot
// balance plus this period's contributions/transfers — so it stayed out
// rather than fabricating six months of numbers.
// ----------------------------------------------------------------------------

// QuickBooks mode (`qbo`): a QuickBooks-connected Pro client gets this same
// page fed from the sync. Fund balances are the accounts picked in Client
// details -> QuickBooks -> Fund accounts (client.funds, mapQboToClient.js);
// giving is client.givingQbo. Contributions and Tax Documents both use full
// calendar years of giving by donor (qbo_donor_gifts, pulled by qbo-sync;
// QG_useDonorGifts in components/client/QboGiving.jsx), with the QuickBooks
// customer / payer as the donor (sub-customers "Parent:Child" rolled up into
// the parent) and one year picker, this year or last, shared by both views.
// QuickBooks has no pledges or fund
// transfers, so the Pledges view is left out and Fund Activity lists each
// fund's balance. Nothing here writes to QuickBooks.
function FundAccountingProPage({ client, qbo, plan, isStaff }) {
  const rawClient = client;
  const gq = qbo ? client.givingQbo || null : null;
  const fundTransfers = client.fundTransfers || [];
  const pledges = client.pledges || [];
  const totalGiving = client.contributions.reduce((s, c) => s + c.amount, 0);
  const restrictedTotal = client.funds
    .filter((f) => f.restricted)
    .reduce((s, f) => s + f.balance, 0);
  const unrestrictedTotal = client.funds
    .filter((f) => !f.restricted)
    .reduce((s, f) => s + f.balance, 0);
  // Open = something still to come in. Fulfilled pledges stay in the table
  // (marked Fulfilled) but aren't "active" and don't count as outstanding.
  const openPledges = pledges
    .filter((p) => p.committed - p.received > 0.005)
    .sort((a, b) => (a.dueDate < b.dueDate ? -1 : a.dueDate > b.dueDate ? 1 : 0));
  const pledgesOutstanding = openPledges.reduce(
    (s, p) => s + (p.committed - p.received),
    0,
  );
  const [view, setView] = useState("funds");
  const showToast = useToast();
  const today = todayLocal();
  const yearStart = today.slice(0, 4) + "-01-01";

  // Tax year. QuickBooks clients pick this year or last (full calendar
  // years come from qbo_donor_gifts); the sample data is this year only.
  // The same year drives the QuickBooks Contributions table.
  const thisYear = today.slice(0, 4);
  const [qboTaxYear, setQboTaxYear] = useState(thisYear);
  const taxYear = qbo ? qboTaxYear : thisYear;
  const useDonorGifts =
    typeof QG_useDonorGifts === "function" ? QG_useDonorGifts : () => null;
  const donorYear = useDonorGifts(
    qbo && (view === "tax-documents" || view === "contributions") ? client.id : null,
    taxYear,
  );
  const donorGroups = useMemo(
    () =>
      qbo && donorYear && typeof QG_groupDonorGifts === "function"
        ? QG_groupDonorGifts(donorYear.rows, gq ? gq.accounts : [])
        : null,
    [qbo, donorYear, gq],
  );
  const qboContributions = useMemo(
    () =>
      qbo && donorYear && typeof QG_donorGiftContributions === "function"
        ? QG_donorGiftContributions(donorYear.rows, gq ? gq.accounts : [])
        : [],
    [qbo, donorYear, gq],
  );
  const givingAccountCount = gq && gq.accounts ? gq.accounts.length : 0;
  const hiddenDonorCount = donorGroups && donorGroups.hiddenDonors ? donorGroups.hiddenDonors.length : 0;
  // Loading / error / not-pulled-yet message for a full-year QuickBooks view,
  // or null when the rows are ready. Shared by Contributions and Tax Documents.
  const donorYearStatus = !qbo
    ? null
    : donorYear && donorYear.loading && !donorYear.rows.length
      ? `Loading ${taxYear} giving from QuickBooks…`
      : donorYear && donorYear.error
        ? `Couldn’t load ${taxYear} giving: ${donorYear.error}`
        : !givingAccountCount
          ? "No income accounts count as giving yet. Staff can pick them in Client details → QuickBooks → Giving accounts."
          : donorYear && !donorYear.pulled
            ? `${taxYear}’s giving hasn’t come in from QuickBooks yet. It arrives with the next sync.`
            : null;
  const yearPicker = qbo ? (
    <select
      className="rb-select"
      aria-label="Year"
      value={qboTaxYear}
      onChange={(e) => setQboTaxYear(e.target.value)}
      style={{ width: "auto" }}
    >
      <option value={thisYear}>{thisYear}</option>
      <option value={String(Number(thisYear) - 1)}>{Number(thisYear) - 1}</option>
    </select>
  ) : null;

  const handleDownloadStatement = (donor) => {
    let filename;
    if (qbo) {
      const d = donorGroups && donorGroups.donors.find((x) => x.donor === donor);
      const through =
        taxYear < thisYear
          ? `December 31, ${taxYear}`
          : fmtDate(
              donorYear && donorYear.pulledAt
                ? String(donorYear.pulledAt).slice(0, 10)
                : today,
            );
      filename = buildGivingStatementPdf(
        client,
        donor,
        `January 1 – ${through}${taxYear < thisYear ? "" : `, ${taxYear}`}`,
        d ? d.gifts : [],
      );
    } else {
      filename = buildGivingStatementPdf(client, donor, null);
    }
    showToast(`Downloaded "${filename}"`);
  };

  // Tax Documents: one row per named donor (never "Anonymous" — there's no
  // one to send a receipt to, and a YTD total shouldn't be attributable to
  // a single anonymous contact), with their YTD total and the email on file
  // from client.donors, if any.
  const donorRoster = useMemo(() => {
    const emailByDonor = Object.fromEntries(
      (client.donors || []).map((d) => [d.name, d.email]),
    );
    if (qbo) {
      return (donorGroups ? donorGroups.donors : []).map((d) => ({
        donor: d.donor,
        total: d.total,
        giftCount: d.giftCount,
        email: emailByDonor[d.donor] || null,
      }));
    }
    const totals = {};
    client.contributions.forEach((c) => {
      if (c.donor === "Anonymous") return;
      // Year to date means this calendar year only, Jan 1 through today,
      // the same range the downloaded statement covers.
      if (!c.date || c.date < yearStart || c.date > today) return;
      if (!totals[c.donor])
        totals[c.donor] = { donor: c.donor, total: 0, giftCount: 0 };
      totals[c.donor].total += c.amount;
      totals[c.donor].giftCount += 1;
    });
    return Object.values(totals)
      .map((d) => ({ ...d, email: emailByDonor[d.donor] || null }))
      .sort((a, b) => b.total - a.total);
  }, [qbo, donorGroups, client.contributions, client.donors, yearStart, today]);

  // Which donors already got this year's statement, so nobody sends twice by
  // accident. Per browser (localStorage), like the send itself is a mock;
  // when real sending lands this should move to a table so staff and the
  // client see the same record. Kept per tax year.
  const [sentAt, setSentAt] = useState(() => loadTaxDocsSent(client.id, taxYear));
  const [confirmResend, setConfirmResend] = useState(null); // { donors: [...] }
  useEffect(() => {
    setSentAt(loadTaxDocsSent(client.id, taxYear));
  }, [client.id, taxYear]);

  const markSent = (donors) => {
    const now = new Date().toISOString();
    setSentAt((prev) => {
      const next = { ...prev };
      donors.forEach((d) => {
        next[d] = now;
      });
      saveTaxDocsSent(client.id, taxYear, next);
      return next;
    });
  };

  // No real send path exists, and this used to toast "sent" without sending
  // anything. Now it's honest: the person downloads each statement, emails
  // it themselves, and marks it sent here so nobody sends twice. (A mailto:
  // draft can't carry the PDF, so it isn't offered.)
  const sendStatements = (rows) => {
    markSent(rows.map((d) => d.donor));
    showToast(
      rows.length === 1
        ? `Marked ${rows[0].donor}'s statement as sent.`
        : `Marked ${rows.length} statements as sent.`,
    );
  };

  const handleSendStatement = (d) => {
    if (sentAt[d.donor]) setConfirmResend({ rows: [d] });
    else sendStatements([d]);
  };

  // Marking sent doesn't need an email on file (a statement can be handed
  // over or posted), so every named donor counts.
  const withEmail = donorRoster;
  const unsent = withEmail.filter((d) => !sentAt[d.donor]);

  // Send All only sends to donors who haven't had one yet; once everyone
  // has, it asks before sending the whole batch again.
  const handleSendAll = () => {
    if (!withEmail.length) return;
    if (unsent.length) sendStatements(unsent);
    else setConfirmResend({ rows: withEmail });
  };

  return (
    <div>
      <MockBanner text="Giving records, fund balances, transfers, and pledges shown here are fabricated for this prototype." client={client} />

      {qbo && (
        <p className="card-subtitle" style={{ margin: "0 0 12px" }}>
          From QuickBooks ·{" "}
          {typeof QG_syncLine === "function"
            ? QG_syncLine(rawClient, plan)
            : "as of last sync"}
        </p>
      )}

      <div className="kpi-grid">
        {qbo ? (
          <button
            className="card kpi-card kpi-card-clickable"
            onClick={() => setView("giving")}
          >
            <span className="kpi-label">Giving Year to Date</span>
            <span className="kpi-value">{fmtMoney(gq ? gq.ytd : 0)}</span>
            <span className="kpi-sub neutral">
              {gq && gq.accounts.length
                ? `${fmtMoney(gq.thisMonth)} so far this month`
                : "No giving accounts yet"}
            </span>
          </button>
        ) : (
        <button
          className="card kpi-card kpi-card-clickable"
          onClick={() => setView("contributions")}
        >
          <span className="kpi-label">Recent Giving</span>
          <span className="kpi-value">{fmtMoney(totalGiving)}</span>
          <span className="kpi-sub neutral">
            {client.contributions.length} gifts
          </span>
        </button>
        )}
        <button
          className="card kpi-card kpi-card-clickable"
          onClick={() => setView("funds")}
        >
          <span className="kpi-label">Unrestricted Funds</span>
          <span className="kpi-value">{fmtMoney(unrestrictedTotal)}</span>
          <span className="kpi-sub positive">
            {qbo && !client.funds.length
              ? "No funds set up yet"
              : "Available for general use"}
          </span>
        </button>
        <button
          className="card kpi-card kpi-card-clickable"
          onClick={() => setView("funds")}
        >
          <span className="kpi-label">Restricted Funds</span>
          <span className="kpi-value">{fmtMoney(restrictedTotal)}</span>
          <span className="kpi-sub neutral">
            Designated for specific purposes
          </span>
        </button>
        {qbo ? (
          <button
            className="card kpi-card kpi-card-clickable"
            onClick={() => setView("giving")}
          >
            <span className="kpi-label">Giving · Last 12 Months</span>
            <span className="kpi-value">{fmtMoney(gq ? gq.last12 : 0)}</span>
            <span className="kpi-sub neutral">
              {gq && gq.monthlyAverage !== null
                ? `About ${fmtMoney(gq.monthlyAverage)} a month`
                : "—"}
            </span>
          </button>
        ) : (
        <button
          className="card kpi-card kpi-card-clickable"
          onClick={() => setView("pledges")}
        >
          <span className="kpi-label">Pledges Outstanding</span>
          <span className="kpi-value">{fmtMoney(pledgesOutstanding)}</span>
          <span className="kpi-sub neutral">
            {openPledges.length} open pledge{openPledges.length !== 1 ? "s" : ""}
          </span>
        </button>
        )}
      </div>

      <div className="view-toggle" style={{ marginBottom: 20 }}>
        <button
          type="button"
          className={"view-toggle-btn" + (view === "funds" ? " active" : "")}
          onClick={() => setView("funds")}
        >
          Fund Balances
        </button>
        {qbo && (
          <button
            type="button"
            className={"view-toggle-btn" + (view === "giving" ? " active" : "")}
            onClick={() => setView("giving")}
          >
            Giving
          </button>
        )}
        <button
          type="button"
          className={
            "view-toggle-btn" + (view === "contributions" ? " active" : "")
          }
          onClick={() => setView("contributions")}
        >
          Contributions
        </button>
        <button
          type="button"
          className={"view-toggle-btn" + (view === "activity" ? " active" : "")}
          onClick={() => setView("activity")}
        >
          Fund Activity
        </button>
        {!qbo && (
          <button
            type="button"
            className={"view-toggle-btn" + (view === "pledges" ? " active" : "")}
            onClick={() => setView("pledges")}
          >
            Pledges
          </button>
        )}
        <button
          type="button"
          className={
            "view-toggle-btn" + (view === "tax-documents" ? " active" : "")
          }
          onClick={() => setView("tax-documents")}
        >
          Tax Documents
        </button>
      </div>

      {view === "funds" &&
        (qbo && typeof QG_FundsSection === "function" ? (
          <QG_FundsSection client={client} isStaff={isStaff} />
        ) : (
          <FundBalancesCard client={client} />
        ))}
      {view === "giving" &&
        qbo &&
        (gq && gq.accounts.length && typeof QG_GivingTrend === "function" ? (
          <QG_GivingTrend g={gq} />
        ) : (
          <div className="card">
            <h3 className="card-title">Giving</h3>
            <p className="card-subtitle" style={{ margin: 0 }}>
              No giving accounts found in QuickBooks yet.{" "}
              {isStaff
                ? "Pick which income accounts count as giving in Client details → QuickBooks."
                : "Your bookkeeper can choose which income accounts count as giving."}
            </p>
          </div>
        ))}
      {view === "contributions" && !qbo && <ContributionsCard client={client} />}
      {view === "contributions" && qbo && (
        <ContributionsCard
          client={client}
          title={`${taxYear} Contributions`}
          contributions={donorYearStatus ? [] : qboContributions}
          emptyText={
            donorYearStatus ||
            `No gifts posted to the giving accounts in QuickBooks in ${taxYear}.`
          }
          actions={yearPicker}
          subtitle={`Every gift posted to the giving accounts in QuickBooks, ${
            taxYear < thisYear ? "January 1 – December 31" : "January 1 to date"
          }, newest first · ${
            donorYear && donorYear.pulledAt
              ? `as of last sync, ${relTime(donorYear.pulledAt)}`
              : "waiting for the first full-year sync"
          }. The donor is the QuickBooks customer or payer, with a sub-customer listed under its parent. Refunds show as negative amounts.`}
        />
      )}

      {view === "activity" && qbo && (
        <div className="card">
          <h3 className="card-title">Fund Activity</h3>
          <p className="card-subtitle">
            Each fund&rsquo;s balance in QuickBooks as of last sync. Transfers
            between funds aren&rsquo;t synced from QuickBooks, so they
            aren&rsquo;t listed here.
          </p>
          <div className="table-scroll">
            <table className="tx-table tx-table-labeled">
              <thead>
                <tr>
                  <th>Fund</th>
                  <th>Type</th>
                  <th className="num">Balance</th>
                </tr>
              </thead>
              <tbody>
                {client.funds.length === 0 ? (
                  <EmptyRow colSpan={3}>
                    Funds appear here once your bookkeeper sets them up.
                  </EmptyRow>
                ) : (
                  client.funds.map((f) => (
                    <tr key={f.name}>
                      <td data-primary="">
                        <span className="category-tag">{f.name}</span>
                      </td>
                      <td data-label="Type">
                        <span className={"pill " + (f.restricted ? "restricted" : "unrestricted")}>
                          {f.restricted ? "Restricted" : "Unrestricted"}
                        </span>
                      </td>
                      <td className="num tx-amount" data-label="Balance">
                        {fmtMoney(f.balance, { cents: true })}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {view === "activity" && !qbo && (
        <div className="card">
          <h3 className="card-title">Fund Activity</h3>
          <p className="card-subtitle">
            Transfers between funds, with the reason for each move
          </p>
          <div className="table-scroll">
            <table className="tx-table tx-table-labeled">
              <thead>
                <tr>
                  <th>Date</th>
                  <th>From</th>
                  <th>To</th>
                  <th>Reason</th>
                  <th className="num">Amount</th>
                </tr>
              </thead>
              <tbody>
                {fundTransfers.length === 0 ? (
                  <EmptyRow colSpan={5}>No fund transfers recorded.</EmptyRow>
                ) : (
                  fundTransfers.map((t, i) => (
                    <tr key={i}>
                      <td data-label="Date">{fmtDate(t.date)}</td>
                      <td data-label="From">
                        <span className="category-tag">{t.fromFund}</span>
                      </td>
                      <td data-label="To">
                        <span className="category-tag">{t.toFund}</span>
                      </td>
                      <td data-primary="">{t.reason}</td>
                      <td className="num tx-amount" data-label="Amount">
                        {fmtMoney(t.amount, { cents: true })}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {view === "pledges" && !qbo && (
        <div className="card">
          <h3 className="card-title">Pledges</h3>
          <p className="card-subtitle">
            Committed vs. received, by donor and fund
            {pledges.length > 0 && openPledges.length === 0
              ? " · every pledge is fulfilled"
              : ""}
          </p>
          <div className="table-scroll">
            <table className="tx-table tx-table-labeled">
              <thead>
                <tr>
                  <th>Donor</th>
                  <th>Fund</th>
                  <th>Due</th>
                  <th className="num">Committed</th>
                  <th className="num">Received</th>
                  <th className="num">Remaining</th>
                  <th>Status</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {pledges.length === 0 ? (
                  <EmptyRow colSpan={8}>No pledges recorded yet.</EmptyRow>
                ) : (
                  // Open pledges first (soonest due), fulfilled ones after.
                  [...openPledges, ...pledges.filter((p) => !openPledges.includes(p))].map((p, i) => {
                    const remaining = p.committed - p.received;
                    const isOverdue =
                      remaining > 0.005 && daysUntil(p.dueDate, today) < 0;
                    const status =
                      remaining <= 0.005
                        ? "Fulfilled"
                        : isOverdue
                          ? "Overdue"
                          : "In progress";
                    const pillClass =
                      remaining <= 0.005
                        ? "good"
                        : isOverdue
                          ? "bad"
                          : "neutral";
                    return (
                      <tr key={i}>
                        <td data-primary="">{p.donor}</td>
                        <td data-label="Fund">
                          <span className="category-tag">{p.fund}</span>
                        </td>
                        <td data-label="Due">{fmtDate(p.dueDate)}</td>
                        <td className="num" data-label="Committed">
                          {fmtMoney(p.committed, { cents: true })}
                        </td>
                        <td className="num" data-label="Received">
                          {fmtMoney(p.received, { cents: true })}
                        </td>
                        <td className="num" data-label="Remaining">
                          {fmtMoney(remaining, { cents: true })}
                        </td>
                        <td data-label="Status">
                          <span className={"pill " + pillClass}>{status}</span>
                        </td>
                        <td>
                          <button
                            className="btn-secondary"
                            onClick={() => handleDownloadStatement(p.donor)}
                          >
                            Giving Statement
                          </button>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {view === "tax-documents" && (
        <div className="card">
          <div className="page-header" style={{ marginBottom: 4 }}>
            <div>
              <h3 className="card-title">Tax Documents</h3>
              <p className="card-subtitle" style={{ margin: 0 }}>
                {qbo
                  ? `${taxYear} giving by donor from QuickBooks, ${
                      taxYear < thisYear ? "January 1 – December 31" : "January 1 to date"
                    } · ${
                      donorYear && donorYear.pulledAt
                        ? `as of last sync, ${relTime(donorYear.pulledAt)}`
                        : "waiting for the first full-year sync"
                    }`
                  : `${taxYear} giving statements (January 1 through today) donors can use for their taxes`}
              </p>
            </div>
            <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
            {yearPicker}
            <button
              className={unsent.length || !withEmail.length ? "btn-primary" : "btn-secondary"}
              disabled={!withEmail.length}
              onClick={handleSendAll}
            >
              {!withEmail.length || unsent.length === withEmail.length
                ? "Mark All Sent"
                : unsent.length
                  ? `Mark ${unsent.length} not yet sent`
                  : "All marked sent"}
            </button>
            </div>
          </div>
          <div className="table-scroll">
            <table className="tx-table tx-table-labeled">
              <thead>
                <tr>
                  <th>Donor</th>
                  <th>Email on File</th>
                  <th>Status</th>
                  <th className="num">Gifts</th>
                  <th className="num">{qbo ? `${taxYear} Total` : "YTD Total"}</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {donorYearStatus ? (
                  <EmptyRow colSpan={6}>{donorYearStatus}</EmptyRow>
                ) : qbo && donorRoster.length === 0 && !(donorGroups && donorGroups.anonymous.giftCount) ? (
                  <EmptyRow colSpan={6}>
                    {hiddenDonorCount
                      ? `No donors with a positive ${taxYear} total in QuickBooks.`
                      : `No gifts posted to the giving accounts in QuickBooks in ${taxYear}.`}
                  </EmptyRow>
                ) : !qbo && donorRoster.length === 0 ? (
                  <EmptyRow colSpan={6}>
                    {client.contributions.some(
                      (c) => c.date >= yearStart && c.date <= today,
                    )
                      ? `No named donors to send statements to: every gift in ${taxYear} so far is anonymous.`
                      : `No gifts recorded in ${taxYear} yet.`}
                  </EmptyRow>
                ) : (
                  donorRoster.map((d) => (
                    <tr key={d.donor}>
                      <td data-primary="">{d.donor}</td>
                      <td data-label="Email on File">
                        {d.email || (
                          <span style={{ color: "var(--text-muted)" }}>
                            No email on file
                          </span>
                        )}
                      </td>
                      <td data-label="Status">
                        {sentAt[d.donor] ? (
                          <span
                            className="tax-sent-pill"
                            title={`Sent ${fmtDateTime(sentAt[d.donor])}`}
                          >
                            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                              <path d="M5 12.5l4.5 4.5L19 7.5" />
                            </svg>
                            Sent {fmtDate(sentAt[d.donor].slice(0, 10))}
                          </span>
                        ) : (
                          <span style={{ color: "var(--text-muted)" }}>
                            Not sent
                          </span>
                        )}
                      </td>
                      <td className="num" data-label="Gifts">
                        {d.giftCount}
                      </td>
                      <td className="num tx-amount" data-label={qbo ? `${taxYear} Total` : "YTD Total"}>
                        {fmtMoney(d.total, { cents: true })}
                      </td>
                      <td
                        style={{
                          display: "flex",
                          gap: 8,
                          justifyContent: "flex-end",
                        }}
                      >
                        <button
                          className="btn-secondary"
                          onClick={() => handleDownloadStatement(d.donor)}
                        >
                          Download
                        </button>
                        <button
                          className="btn-secondary"
                          title="Record that you've sent this donor their statement"
                          onClick={() => handleSendStatement(d)}
                        >
                          {sentAt[d.donor] ? "Mark sent again" : "Mark sent"}
                        </button>
                      </td>
                    </tr>
                  ))
                )}
                {qbo &&
                  donorYear &&
                  !donorYear.error &&
                  donorYear.pulled &&
                  donorGroups &&
                  donorGroups.anonymous.giftCount > 0 && (
                    <tr key="__anonymous">
                      <td data-primary="">Anonymous / no donor in QuickBooks</td>
                      <td data-label="Email on File">
                        <span style={{ color: "var(--text-muted)" }}>—</span>
                      </td>
                      <td data-label="Status">
                        <span style={{ color: "var(--text-muted)" }}>
                          Can&rsquo;t go on a statement
                        </span>
                      </td>
                      <td className="num" data-label="Gifts">
                        {donorGroups.anonymous.giftCount}
                      </td>
                      <td className="num tx-amount" data-label={`${taxYear} Total`}>
                        {fmtMoney(donorGroups.anonymous.total, { cents: true })}
                      </td>
                      <td></td>
                    </tr>
                  )}
              </tbody>
            </table>
          </div>
          <p className="card-subtitle" style={{ margin: "12px 0 0" }}>
            {qbo
              ? `Donors are the customer or payer names on gifts posted to the giving accounts in QuickBooks, for the whole calendar year as of the last sync. Sub-customers are combined under their parent customer, and each gift on the statement notes the sub-customer. Gifts with no name (bank deposits usually have none) are grouped under Anonymous and can't go on a statement; to include them, record the donor as the customer in QuickBooks. ${
                  hiddenDonorCount
                    ? `${hiddenDonorCount} donor${hiddenDonorCount === 1 ? "" : "s"} with a $0 or negative total ${hiddenDonorCount === 1 ? "is" : "are"} hidden. `
                    : ""
                }`
              : ""}
            Statements aren&rsquo;t emailed from here yet. Download each one,
            send it to the donor yourself, then mark it sent so nobody sends
            it twice. Sent status is remembered on this device only.
          </p>
        </div>
      )}

      {confirmResend && (
        <ConfirmModal
          title={
            confirmResend.rows.length === 1
              ? "Mark this statement sent again?"
              : `Mark all ${confirmResend.rows.length} statements sent again?`
          }
          body={
            confirmResend.rows.length === 1
              ? `${confirmResend.rows[0].donor}'s ${taxYear} giving statement was already marked sent on ${fmtDate(sentAt[confirmResend.rows[0].donor].slice(0, 10))}.`
              : `Every donor's ${taxYear} giving statement is already marked sent.`
          }
          confirmLabel="Mark sent again"
          onCancel={() => setConfirmResend(null)}
          onConfirm={() => {
            sendStatements(confirmResend.rows);
            setConfirmResend(null);
          }}
        />
      )}
    </div>
  );
}

// ----------------------------------------------------------------------------
// Cash Flow page
// ----------------------------------------------------------------------------

// One open-items table (receivables or payables) with its own search, sort,
// overdue flag and paging. QuickBooks clients can have hundreds of open bills,
// so the table shows RP_PAGE rows and a "Show more" button.
const RP_PAGE = 25;
function RP_OpenItemsTable({ kind, items, today }) {
  const [q, setQ] = useState("");
  const [sort, setSort] = useState("due");
  const [shown, setShown] = useState(RP_PAGE);
  const isPay = kind === "payables";
  const nameOf = (x) => (isPay ? x.vendor || "" : x.description || "");
  const rows = useMemo(() => {
    const needle = q.trim().toLowerCase();
    const list = (items || []).filter(
      (x) =>
        !needle ||
        [nameOf(x), x.description, x.docNumber].some((s) => s && String(s).toLowerCase().includes(needle)),
    );
    const by = {
      due: (a, b) => (a.dueDate < b.dueDate ? -1 : a.dueDate > b.dueDate ? 1 : 0),
      amount: (a, b) => (b.amount || 0) - (a.amount || 0),
      name: (a, b) => nameOf(a).localeCompare(nameOf(b)),
    }[sort];
    return list.slice().sort(by);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items, q, sort]);
  useEffect(() => setShown(RP_PAGE), [q, sort]);
  const label = isPay ? "payables" : "receivables";
  return (
    <>
      {(items || []).length > 5 && (
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", margin: "4px 0 10px" }}>
          <input
            type="search"
            className="rb-select"
            placeholder={isPay ? "Search vendors or bill #" : "Search customers or invoice #"}
            aria-label={"Search " + label}
            value={q}
            onChange={(e) => setQ(e.target.value)}
            style={{ minWidth: 0, width: 220, maxWidth: "100%" }}
          />
          <select
            className="rb-select"
            aria-label={"Sort " + label}
            value={sort}
            onChange={(e) => setSort(e.target.value)}
            style={{ width: "auto" }}
          >
            <option value="due">Due date</option>
            <option value="amount">Largest first</option>
            <option value="name">{isPay ? "Vendor" : "Name"} A–Z</option>
          </select>
        </div>
      )}
      <div className="table-scroll">
        <table className="tx-table tx-table-labeled">
          <thead>
            <tr>
              <th>{isPay ? "Vendor" : "Description"}</th>
              <th>Due</th>
              <th className="num">Amount</th>
            </tr>
          </thead>
          <tbody>
            {(items || []).length === 0 && (
              <EmptyRow colSpan={3}>Nothing outstanding — you&rsquo;re all caught up.</EmptyRow>
            )}
            {(items || []).length > 0 && rows.length === 0 && (
              <EmptyRow colSpan={3}>Nothing matches &ldquo;{q}&rdquo;.</EmptyRow>
            )}
            {rows.slice(0, shown).map((x, i) => {
              const late = daysUntil(x.dueDate, today);
              const overdue = late < 0;
              const meta = isPay ? x.description : x.docNumber ? "Invoice #" + x.docNumber : null;
              return (
                <tr key={x.id || kind + ":" + i}>
                  <td data-primary="">
                    {nameOf(x)}
                    {meta && <div className="tx-meta">{meta}</div>}
                  </td>
                  <td data-label="Due">
                    {fmtDate(x.dueDate)}
                    {overdue && (
                      <div className="tx-meta negative" style={{ fontWeight: 600 }}>
                        Overdue {-late} day{late === -1 ? "" : "s"}
                      </div>
                    )}
                  </td>
                  <td className={"num tx-amount " + (isPay ? "negative" : "positive")} data-label="Amount">
                    {isPay ? "-" : ""}
                    {fmtMoney(x.amount, { cents: true })}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
      {rows.length > shown && (
        <div style={{ marginTop: 10 }}>
          <button type="button" className="btn-secondary" onClick={() => setShown((n) => n + RP_PAGE)}>
            Show more ({rows.length - shown} left)
          </button>
        </div>
      )}
    </>
  );
}

function ReceivablesPayablesPage({ client }) {
  const totalReceivable = client.receivables.reduce((s, r) => s + r.amount, 0);
  const totalPayable = client.payables.reduce((s, p) => s + p.amount, 0);
  const { flashCardId, jumpToCard } = useCardFlash();
  const today = todayLocal();
  const isQbo = client.dataSource === "quickbooks";
  const overdueOf = (list) => list.filter((x) => daysUntil(x.dueDate, today) < 0);
  const arOverdue = overdueOf(client.receivables);
  const apOverdue = overdueOf(client.payables);
  const net = totalReceivable - totalPayable;

  return (
    <div className="cashflow-page">
      <MockBanner text="These balances are hardcoded for the prototype. Real amounts will come from QuickBooks in Phase 2."client={client} />

      <div className="kpi-grid">
        <button
          className="card kpi-card kpi-card-clickable"
          onClick={() => jumpToCard("rp-receivables-card", "receivables")}
        >
          <span className="kpi-label">Money Owed To You</span>
          <span className="kpi-value">{fmtMoney(totalReceivable)}</span>
          <span className="kpi-sub positive">
            {client.receivables.length} open item
            {client.receivables.length !== 1 ? "s" : ""}
            {arOverdue.length > 0 && ` · ${arOverdue.length} overdue`}
          </span>
        </button>
        <button
          className="card kpi-card kpi-card-clickable"
          onClick={() => jumpToCard("rp-payables-card", "payables")}
        >
          <span className="kpi-label">Money You Owe</span>
          <span className="kpi-value">{fmtMoney(totalPayable)}</span>
          <span className="kpi-sub negative">
            {client.payables.length} open item
            {client.payables.length !== 1 ? "s" : ""}
            {apOverdue.length > 0 && ` · ${apOverdue.length} overdue`}
          </span>
        </button>
        {/* Not a balance-sheet "net position": just open receivables less
            open payables, so it says exactly that. */}
        <div className="card kpi-card">
          <span className="kpi-label">Owed To You, Less What You Owe</span>
          <span className="kpi-value">{fmtMoney(net)}</span>
          <span className="kpi-sub neutral">open receivables minus open payables (not cash)</span>
        </div>
      </div>

      <div className="content-masonry">
        <div
          className={
            "card " + (flashCardId === "receivables" ? "card-flash" : "")
          }
          id="rp-receivables-card"
        >
          <h3 className="card-title">Receivables</h3>
          <p className="card-subtitle">
            {isQbo
              ? "Open invoices from QuickBooks"
              : "Open invoices and other money owed to you"}
          </p>
          <RP_OpenItemsTable kind="receivables" items={client.receivables} today={today} />
        </div>

        <div
          className={"card " + (flashCardId === "payables" ? "card-flash" : "")}
          id="rp-payables-card"
        >
          <h3 className="card-title">Payables</h3>
          <p className="card-subtitle">
            {isQbo ? "Unpaid bills in QuickBooks" : "Unpaid bills going out"}
          </p>
          <RP_OpenItemsTable kind="payables" items={client.payables} today={today} />
        </div>
      </div>
    </div>
  );
}

// ----------------------------------------------------------------------------
// Payroll page — a paid add-on (client.payrollAddOn / client.payroll), not a
// premium-plan upgrade. Deliberately not in PREMIUM_UPGRADE_TAB_KEYS or
// gated by hasPremiumPlan: a Standard client can buy it just as easily as a
// Premium one. Real pay runs are processed in Gusto; this page only reads
// what Gusto reports, so there's no "run payroll" action anywhere here.
// ----------------------------------------------------------------------------

const PAYROLL_STATUS_META = {
  active: { label: "Active", cls: "positive" },
  onboarding: { label: "Onboarding", cls: "neutral" },
};

const PAYROLL_DEPOSIT_STATUS_META = {
  upcoming: { label: "Upcoming", cls: "neutral" },
  filed: { label: "Filed", cls: "positive" },
};

// What the add-on includes. Clients without it have no Payroll tab
// (resolveAccess, 2026-10-05); they ask for it from the Payroll card on
// Settings → Plan (PayrollAddOnCard), and staff turn it on in Client roster.
const PAYROLL_ADDON_FEATURES = [
  {
    title: "Every employee in one place",
    text: "Pay type, status and direct-deposit enrollment for each person, synced from Gusto.",
  },
  {
    title: "Tax deposits tracked",
    text: "Federal 941, state withholding and FUTA, with amounts and due dates, so nothing sneaks up on you.",
  },
  {
    title: "Part of your books",
    text: "Payroll cost rolls into Budget vs. Actual and Reports, and a Payroll year-to-date report joins the others.",
  },
  {
    title: "Works on any plan",
    text: "Add it to Basic or Pro. Message your account manager for pricing and details.",
  },
];

// Fallback if PayrollPage is ever reached without the add-on.
function PayrollAddOnPage({ client, clientPortalUser }) {
  return (
    <div className="payroll-addon">
      <PayrollAddOnCard client={client} clientPortalUser={clientPortalUser} />
      <div className="report-grid">
        {PAYROLL_ADDON_FEATURES.map((f) => (
          <div className="card" key={f.title}>
            <h3 className="card-title">{f.title}</h3>
            <p className="card-subtitle" style={{ marginBottom: 0 }}>
              {f.text}
            </p>
          </div>
        ))}
      </div>
    </div>
  );
}

// The Payroll add-on: price, an employee estimate and an "Add Payroll"
// request (lands in staff Home → Needs you as an Upgrade). On the Plan page
// (inPlanPage) it also lists what's included, and says so when the client
// already has it.
function PayrollAddOnCard({ client, clientPortalUser, inPlanPage }) {
  const showToast = useToast();
  const { staff } = useContext(StaffToolsContext);
  const [requesting, setRequesting] = useState(false);
  // Opens the client's Messages thread (it goes to their account manager).
  const messageAccountManager = () => {
    const route = buildHashRoute("messages", client.id);
    if (route) window.location.hash = route;
  };

  async function requestAddOn() {
    const supabase = window.mgbSupabase;
    const requestedBy =
      (clientPortalUser && (clientPortalUser.name || clientPortalUser.email)) ||
      "Someone at " + client.name;
    if (!supabase) {
      showToast("Thanks! Your bookkeeper will follow up about Payroll.");
      return;
    }
    setRequesting(true);
    let { error } = await supabase.rpc("request_enterprise_upgrade", {
      p_client_id: client.id,
      p_requested_by: requestedBy,
      p_plan: "payroll",
    });
    // Until staff-client-tools.sql runs, requests only know plan names.
    if (error && /invalid_plan|requested_plan|23514|PGRST202/i.test((error.message || "") + " " + (error.code || ""))) {
      ({ error } = await supabase.rpc("request_enterprise_upgrade", {
        p_client_id: client.id,
        p_requested_by: `${requestedBy} (wants the Payroll add-on)`,
      }));
    }
    setRequesting(false);
    if (error) {
      console.warn("Couldn't file payroll request:", error.message);
      showToast("Couldn't send that request — please email your bookkeeper and we'll sort it out.");
      return;
    }
    setRequested(true);
    showToast("Thanks! Your bookkeeper will follow up about adding Payroll.");
  }
  const [requested, setRequested] = useState(false);

  if (client.payrollAddOn) {
    return (
      <div className="card payroll-addon-hero">
        <div className="eyebrow-badge">Payroll · Add-on</div>
        <h2>Payroll is on for {client.name}</h2>
        <p className="payroll-addon-lede">
          It's billed with the rest of your MyGoodBooks fee. Find it under Finances › Payroll.
          For billing questions or to stop it, message your account manager.
        </p>
      </div>
    );
  }

  return (
      <div className="card payroll-addon-hero">
        <div className="eyebrow-badge">Payroll · Add-on</div>
        <h2>Add Payroll for {client.name || "your organization"}</h2>
        <p className="payroll-addon-lede">
          Keep running payroll in Gusto. With the add-on, every employee's pay, withholding and
          upcoming tax deposits sit right alongside the rest of your books in a Payroll tab.
        </p>
        <p className="payroll-addon-note">
          For pricing and more details, message your account manager.
        </p>
        {staff ? (
          <p className="payroll-addon-staff">
            Staff: turn Payroll on for this client under Settings → Firm settings → Client roster (Client organizations card).
          </p>
        ) : (
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap", justifyContent: "center" }}>
            <button className="btn-primary" disabled={requesting || requested} onClick={requestAddOn}>
              {requesting ? "Sending…" : requested ? "Request sent" : "Add Payroll"}
            </button>
            <button type="button" className="btn-secondary" onClick={messageAccountManager}>
              Message your account manager
            </button>
          </div>
        )}
        {inPlanPage && (
          <ul className="payroll-addon-includes">
            {PAYROLL_ADDON_FEATURES.map((f) => (
              <li key={f.title}>
                <strong>{f.title}.</strong> {f.text}
              </li>
            ))}
          </ul>
        )}
      </div>
  );
}

