// ----------------------------------------------------------------------------
// My Tasks — a bookkeeper's tasks and reminders. Private by default; an item
// linked to a client can be shared with that client's team (see
// staff-reminders-v2.sql). Backed by the same staff_reminders table as Home's
// "Your reminders" card, both through staffItemsApi above. Today / Upcoming /
// Overdue / All tabs, client and mine-vs-shared filters, and completed items
// kept (with a completed_at) rather than deleted the moment they're checked.
// ----------------------------------------------------------------------------

const TASK_PRIORITIES = ["high", "normal", "low"];
const TASK_PRIORITY_LABEL = { high: "High", normal: "Normal", low: "Low" };

const TASK_TABS = [
  { id: "today", label: "Today" },
  { id: "upcoming", label: "Upcoming" },
  { id: "overdue", label: "Overdue" },
  { id: "all", label: "All" },
  { id: "byclient", label: "By client" },
];
// Notes and SOPs have their own cards below the tasks card.
function scrollToTasksCard(id) {
  setTimeout(() => {
    const el = document.getElementById(id);
    if (el) el.scrollIntoView({ block: "start", behavior: "smooth" });
  }, 0);
}
// Tabs that show tasks (vs. the client/notes views).
const TASK_LIST_TABS = ["today", "upcoming", "overdue", "all"];

const TASK_PRIORITY_RANK = { high: 0, normal: 1, low: 2 };
// Dated first (soonest first), then by due time, then priority.
function compareOpenStaffItems(a, b) {
  if (!!a.due_date !== !!b.due_date) return a.due_date ? -1 : 1;
  if (a.due_date !== b.due_date) return a.due_date < b.due_date ? -1 : 1;
  const aAt = a.due_at || "";
  const bAt = b.due_at || "";
  if (aAt !== bAt) return aAt < bAt ? -1 : 1;
  return (
    (TASK_PRIORITY_RANK[a.priority] ?? 1) - (TASK_PRIORITY_RANK[b.priority] ?? 1)
  );
}

// Add-a-note form used by My Tasks' Notes tab (client picker) and each By
// client card (client fixed). onSubmit resolves true on success.
function NoteComposer({ clients, fixedClientId, legacy, onSubmit, onCancel }) {
  const [clientId, setClientId] = useState(fixedClientId || "");
  const [category, setCategory] = useState("general");
  const [text, setText] = useState("");
  const [busy, setBusy] = useState(false);
  const ready = !!text.trim() && !!(fixedClientId || clientId);

  async function submit(e) {
    e.preventDefault();
    if (!ready || busy) return;
    setBusy(true);
    const ok = await onSubmit({
      client_id: fixedClientId || clientId,
      category,
      text: text.trim(),
    });
    setBusy(false);
    if (ok) setText("");
  }

  return (
    <form className="note-composer" onSubmit={submit}>
      <div className="note-composer-options">
        {!fixedClientId && (
          <label className="task-field">
            <span>Client</span>
            <select
              value={clientId}
              onChange={(e) => setClientId(e.target.value)}
              required
            >
              <option value="">Pick a client</option>
              {(clients || []).map((c) => (
                <option key={c.id} value={c.id}>
                  {c.name}
                </option>
              ))}
            </select>
          </label>
        )}
        {!legacy && (
          <label className="task-field">
            <span>Category</span>
            <select
              value={category}
              onChange={(e) => setCategory(e.target.value)}
            >
              {NOTE_CATEGORIES.map((c) => (
                <option key={c} value={c}>
                  {NOTE_CATEGORY_LABEL[c]}
                </option>
              ))}
            </select>
          </label>
        )}
      </div>
      <textarea
        className="note-textarea"
        rows={3}
        placeholder="Called the owner — March statements coming Friday…"
        aria-label="Note"
        value={text}
        onChange={(e) => setText(e.target.value)}
      />
      <div className="note-composer-actions">
        {onCancel && (
          <button type="button" className="btn-secondary" onClick={onCancel}>
            Cancel
          </button>
        )}
        <button type="submit" className="btn-primary" disabled={!ready || busy}>
          {busy ? "Adding…" : "Add note"}
        </button>
      </div>
    </form>
  );
}
const TASK_TAB_EMPTY = {
  today: "Nothing due today.",
  upcoming: "Nothing coming up.",
  overdue: "Nothing overdue.",
  all: "Nothing on your list — add a task above.",
};

function MyTasksPage({
  staffUser,
  clients,
  statusOverrides,
  canManageTemplates,
  canCreateTemplates,
  onOpenTemplates,
}) {
  const showToast = useToast();
  const supabase = window.mgbSupabase;
  const today = todayLocal();
  const me = staffUser.email;

  const [tasks, setTasks] = useState(null);
  const [error, setError] = useState("");
  const [legacy, setLegacy] = useState(staffItemsApi.legacy);
  const [tab, setTab] = useState("today");
  const [showCompleted, setShowCompleted] = useState(false);
  const [clientFilter, setClientFilter] = useState(""); // "", "__none", id
  const [scopeFilter, setScopeFilter] = useState("all"); // all | mine | shared

  const [newText, setNewText] = useState("");
  const [newDueDate, setNewDueDate] = useState("");
  const [newDueTime, setNewDueTime] = useState("");
  const [newClientId, setNewClientId] = useState("");
  const [newPriority, setNewPriority] = useState("normal");
  const [newKind, setNewKind] = useState("task");
  const [newRemindAt, setNewRemindAt] = useState("");
  const [newRecurrence, setNewRecurrence] = useState("none");
  const [newShared, setNewShared] = useState(false);
  const [adding, setAdding] = useState(false);
  const addTextRef = useRef(null);

  // Notes + handoff summaries (clientNotesApi) for the By client and Notes
  // tabs, and for the note <-> task link chips.
  const [notes, setNotes] = useState(null);
  const [notesError, setNotesError] = useState("");
  const [notesLegacy, setNotesLegacy] = useState(clientNotesApi.legacy);
  const [handoffs, setHandoffs] = useState({});
  const [clientSearch, setClientSearch] = useState("");
  const [noteClientFilter, setNoteClientFilter] = useState("");
  const [noteCategoryFilter, setNoteCategoryFilter] = useState("");
  const [composerFor, setComposerFor] = useState(null); // client id on By client
  const [editingHandoffFor, setEditingHandoffFor] = useState(null);
  const [handoffDraft, setHandoffDraft] = useState("");
  const [savingHandoff, setSavingHandoff] = useState(false);
  const [editingNoteId, setEditingNoteId] = useState(null);
  const [editingNoteText, setEditingNoteText] = useState("");
  const [highlightNoteId, setHighlightNoteId] = useState(null);

  // SOPs tab (clientSopsApi): the chosen client, the picker search, and the
  // "n of 7 sections filled" counts shown there and on By client cards.
  const [sopClientId, setSopClientId] = useState("");
  const [sopSearch, setSopSearch] = useState("");
  const [sopCounts, setSopCounts] = useState({});
  const [sopsMissing, setSopsMissing] = useState(clientSopsApi.missing);

  const clientById = useMemo(
    () => Object.fromEntries((clients || []).map((c) => [c.id, c])),
    [clients],
  );

  const loadTasks = useCallback(() => {
    if (!supabase) return;
    staffItemsApi.list(supabase, me).then(({ data, error }) => {
      setLegacy(staffItemsApi.legacy);
      if (error) {
        setError("Couldn't load tasks. " + error.message);
        setTasks([]);
      } else {
        setError("");
        setTasks(data);
      }
    });
  }, [supabase, me]);

  useEffect(() => {
    loadTasks();
  }, [loadTasks]);
  useStaffItemsChanged(loadTasks);

  const clientIdsKey = (clients || []).map((c) => c.id).join(",");
  const loadNotes = useCallback(() => {
    if (!supabase) return;
    clientNotesApi.list(supabase).then(({ data, error }) => {
      setNotesLegacy(clientNotesApi.legacy);
      if (error) {
        setNotesError("Couldn't load notes. " + error.message);
        setNotes([]);
      } else {
        setNotesError("");
        setNotes(data);
      }
    });
    clientNotesApi
      .getHandoffs(supabase, clientIdsKey ? clientIdsKey.split(",") : [])
      .then(({ data, error }) => {
        if (!error) setHandoffs(data);
      });
  }, [supabase, clientIdsKey]);

  useEffect(() => {
    loadNotes();
  }, [loadNotes]);
  useClientNotesChanged(loadNotes);

  const loadSopCounts = useCallback(() => {
    if (!supabase) return;
    clientSopsApi.filledCounts(supabase).then(({ data, error }) => {
      setSopsMissing(clientSopsApi.missing);
      if (!error) setSopCounts(data);
    });
  }, [supabase]);
  useEffect(() => {
    loadSopCounts();
  }, [loadSopCounts]);
  useClientSopsChanged(loadSopCounts);

  function openSop(clientId) {
    setSopClientId(clientId || "");
    setSopSearch("");
    scrollToTasksCard("my-tasks-sops");
  }

  // Client details → SOP → "Edit in My Tasks" lands here with a client.
  useEffect(() => {
    if (pendingClientSopId) {
      openSop(pendingClientSopId);
      pendingClientSopId = null;
    }
    const onOpen = (e) => {
      pendingClientSopId = null;
      openSop(e.detail);
    };
    window.addEventListener(OPEN_CLIENT_SOP_EVENT, onOpen);
    return () => window.removeEventListener(OPEN_CLIENT_SOP_EVENT, onOpen);
  }, []);

  const sopClient = sopClientId ? clientById[sopClientId] : null;
  const sopPickerClients = useMemo(() => {
    const q = sopSearch.trim().toLowerCase();
    return (clients || [])
      .filter((c) => !q || (c.name || "").toLowerCase().includes(q))
      .slice()
      .sort((a, b) => (a.name || "").localeCompare(b.name || ""));
  }, [clients, sopSearch]);

  // Bring a note into view after jumping to it from a task's link chip.
  useEffect(() => {
    if (!highlightNoteId) return;
    const el = document.getElementById(`note-${highlightNoteId}`);
    if (el) el.scrollIntoView({ block: "center", behavior: "smooth" });
    const id = setTimeout(() => setHighlightNoteId(null), 2500);
    return () => clearTimeout(id);
  }, [highlightNoteId, notes]);

  async function addTask() {
    const text = newText.trim();
    if (!text) return;
    setAdding(true);
    const { error } = await staffItemsApi.add(supabase, me, {
      text,
      due_date: newDueDate || null,
      due_at: buildStaffDueAt(newDueDate, newDueTime || null),
      client_id: newClientId || null,
      priority: newPriority,
      kind: newKind,
      remind_at: newRemindAt ? new Date(newRemindAt).toISOString() : null,
      recurrence: newDueDate ? newRecurrence : "none",
      visibility: newShared && newClientId ? "shared" : "private",
    });
    setAdding(false);
    if (error) {
      showToast(`Couldn't add task: ${error.message}`);
      return;
    }
    setNewText("");
    setNewDueDate("");
    setNewDueTime("");
    setNewPriority("normal");
    setNewKind("task");
    setNewRemindAt("");
    setNewRecurrence("none");
    setNewShared(false);
    // Client stays picked — adding several items for one client in a row is
    // the common case.
  }

  async function toggleTask(task) {
    const { error } = await staffItemsApi.toggleDone(supabase, me, task);
    if (error) showToast(`Couldn't update task: ${error.message}`);
  }

  // "Save as template" (components/staff/TaskTemplates.jsx): admins get the
  // pre-filled template editor; everyone else sends admins a suggestion.
  async function saveAsTemplate(task) {
    if (typeof TT_draftFromTask !== "function") return;
    if (canCreateTemplates && onOpenTemplates) {
      const checklist =
        typeof TCL_fetchTexts === "function" ? await TCL_fetchTexts(supabase, task.id) : [];
      TT_openDraft(TT_draftFromTask(task, { checklist }));
      onOpenTemplates();
      return;
    }
    const { error, duplicate } = await TT_suggestFromTask(supabase, task);
    if (duplicate) showToast("You've already suggested this one. An admin will review it.");
    else if (error) showToast(`Couldn't send the suggestion: ${error.message}`);
    else showToast("Suggested to admins as a recurring template.");
  }

  async function toggleShared(task) {
    const { error } = await staffItemsApi.update(supabase, task.id, {
      visibility: task.visibility === "shared" ? "private" : "shared",
    });
    if (error) showToast(`Couldn't change sharing: ${error.message}`);
  }

  async function removeTask(task) {
    const { error } = await staffItemsApi.remove(supabase, task.id);
    if (error) showToast(`Couldn't remove task: ${error.message}`);
  }

  // "Add task" on a By client card: pre-pick the client in the form above.
  function startTaskForClient(clientId) {
    setNewClientId(clientId);
    const el = addTextRef.current;
    if (el) {
      el.scrollIntoView({ block: "center", behavior: "smooth" });
      el.focus({ preventScroll: true });
    }
  }

  async function addNote(fields) {
    const { error } = await clientNotesApi.add(supabase, staffUser, fields);
    if (error) {
      showToast(`Couldn't add note: ${error.message}`);
      return false;
    }
    return true;
  }

  async function saveNoteEdit(note) {
    const text = editingNoteText.trim();
    if (!text) return;
    const { error } = await clientNotesApi.update(supabase, note.id, { text });
    if (error) {
      showToast(`Couldn't update note: ${error.message}`);
      return;
    }
    setEditingNoteId(null);
  }

  async function pinNote(note) {
    const { error } = await clientNotesApi.pin(supabase, note);
    if (error) showToast(`Couldn't update note: ${error.message}`);
  }

  async function removeNote(note) {
    if (!window.confirm("Delete this note? This can't be undone.")) return;
    const { error } = await clientNotesApi.remove(supabase, note.id);
    if (error) showToast(`Couldn't delete note: ${error.message}`);
  }

  // Note -> private task for me on the same client, linked both ways
  // (task.source_ref = note id, note.linked_task_id = task id).
  async function makeTaskFromNote(note) {
    const firstLine = note.text.split("\n")[0].trim() || note.text.trim();
    const text =
      firstLine.length > 140 ? firstLine.slice(0, 139) + "…" : firstLine;
    const { data, error } = await staffItemsApi.add(supabase, me, {
      text,
      client_id: note.client_id,
      source: "note",
      source_ref: note.id,
    });
    if (error) {
      showToast(`Couldn't make a task: ${error.message}`);
      return;
    }
    if (data && data.id) {
      const res = await clientNotesApi.linkTask(supabase, note.id, data.id);
      if (res.error) showToast(`Task added, but couldn't link it: ${res.error.message}`);
      else showToast("Task added, private to you and admins.");
    }
  }

  async function saveHandoff(clientId) {
    setSavingHandoff(true);
    const { error } = await clientNotesApi.saveHandoff(
      supabase,
      clientId,
      handoffDraft,
      me,
    );
    setSavingHandoff(false);
    if (error) {
      showToast(`Couldn't save handoff summary: ${error.message}`);
      return;
    }
    setEditingHandoffFor(null);
  }

  function jumpToNote(note) {
    setNoteClientFilter(note.client_id);
    setNoteCategoryFilter("");
    setHighlightNoteId(note.id);
  }

  function jumpToTask(task) {
    setTab("all");
    setShowCompleted(!!task.done);
    setClientFilter(task.client_id || "");
    setScopeFilter("all");
  }

  // Client + mine/shared filters apply to every tab and to Completed.
  const filtered = useMemo(() => {
    if (!tasks) return [];
    return tasks.filter((t) => {
      if (clientFilter === "__none" && t.client_id) return false;
      if (clientFilter && clientFilter !== "__none" && t.client_id !== clientFilter)
        return false;
      if (scopeFilter === "mine" && !isMyStaffItem(t, me)) return false;
      if (scopeFilter === "shared" && t.visibility !== "shared") return false;
      return true;
    });
  }, [tasks, clientFilter, scopeFilter, me]);

  const openTasks = useMemo(
    () => filtered.filter((t) => !t.done).sort(compareOpenStaffItems),
    [filtered],
  );

  const buckets = useMemo(
    () => ({
      today: openTasks.filter((t) => t.due_date === today),
      // Undated items sit at the end of Upcoming (openTasks sorts them last).
      upcoming: openTasks.filter((t) => !t.due_date || t.due_date > today),
      overdue: openTasks.filter((t) => t.due_date && t.due_date < today),
      all: openTasks,
    }),
    [openTasks, today],
  );

  const completedTasks = useMemo(
    () =>
      filtered
        .filter((t) => t.done)
        .sort((a, b) => {
          const aAt = a.completed_at || a.created_at;
          const bAt = b.completed_at || b.created_at;
          return aAt < bAt ? 1 : -1;
        }),
    [filtered],
  );

  const isListTab = TASK_LIST_TABS.includes(tab);
  const shown = showCompleted ? completedTasks : buckets[tab] || [];
  const nowMs = Date.now();

  // Link lookups, both directions.
  const taskById = useMemo(
    () => Object.fromEntries((tasks || []).map((t) => [t.id, t])),
    [tasks],
  );
  const noteById = useMemo(
    () => Object.fromEntries((notes || []).map((n) => [n.id, n])),
    [notes],
  );
  // Checklists inside tasks (components/staff/TaskChecklist.jsx): "3/5"
  // progress per task and which task's checklist is open.
  const checklistTaskIds = useMemo(() => (tasks || []).map((t) => t.id), [tasks]);
  const checklistCounts =
    typeof TCL_useCounts === "function" ? TCL_useCounts(checklistTaskIds) : {};
  const [openChecklistId, setOpenChecklistId] = useState(null);
  const taskForNote = (n) =>
    (n.linked_task_id && taskById[n.linked_task_id]) ||
    (tasks || []).find((t) => t.source === "note" && t.source_ref === n.id) ||
    null;

  // Only notes for clients on this staffer's list (RLS already scopes them;
  // this just keeps the view in step with the client picker).
  const visibleNotes = useMemo(
    () =>
      (notes || [])
        .filter((n) => clientById[n.client_id])
        .sort((a, b) => {
          if (a.pinned !== b.pinned) return a.pinned ? -1 : 1;
          return a.created_at < b.created_at ? 1 : -1;
        }),
    [notes, clientById],
  );

  const filteredNotes = useMemo(
    () =>
      visibleNotes.filter(
        (n) =>
          (!noteClientFilter || n.client_id === noteClientFilter) &&
          (notesLegacy || !noteCategoryFilter || n.category === noteCategoryFilter),
      ),
    [visibleNotes, noteClientFilter, noteCategoryFilter, notesLegacy],
  );

  // By client: every client with a handoff summary, a status override, an
  // open task (mine or shared) or a dated note. Most urgent first (overdue,
  // then due today), then name.
  const clientCards = useMemo(() => {
    const q = clientSearch.trim().toLowerCase();
    const openByClient = {};
    (tasks || []).forEach((t) => {
      if (t.done || !t.client_id) return;
      (openByClient[t.client_id] = openByClient[t.client_id] || []).push(t);
    });
    const notesByClient = {};
    visibleNotes.forEach((n) => {
      (notesByClient[n.client_id] = notesByClient[n.client_id] || []).push(n);
    });
    return (clients || [])
      .map((c) => {
        const open = (openByClient[c.id] || []).sort(compareOpenStaffItems);
        const cNotes = notesByClient[c.id] || [];
        const handoff = handoffs[c.id];
        const override = statusOverrides && statusOverrides[c.id];
        const overdue = open.filter((t) => t.due_date && t.due_date < today)
          .length;
        const dueToday = open.filter((t) => t.due_date === today).length;
        const has =
          open.length > 0 ||
          cNotes.length > 0 ||
          !!(handoff && (handoff.note || "").trim()) ||
          !!(override && override.status);
        return { client: c, open, notes: cNotes, handoff, override, overdue, dueToday, has };
      })
      .filter(
        (x) =>
          (x.has || x.client.id === editingHandoffFor || x.client.id === composerFor) &&
          (!q || (x.client.name || "").toLowerCase().includes(q)),
      )
      .sort((a, b) => {
        const rank = (x) => (x.overdue > 0 ? 0 : x.dueToday > 0 ? 1 : 2);
        if (rank(a) !== rank(b)) return rank(a) - rank(b);
        if (a.overdue !== b.overdue) return b.overdue - a.overdue;
        return (a.client.name || "").localeCompare(b.client.name || "");
      });
  }, [
    clients,
    tasks,
    visibleNotes,
    handoffs,
    statusOverrides,
    clientSearch,
    today,
    editingHandoffFor,
    composerFor,
  ]);

  // Clients without anything yet can still get a first note / handoff from
  // the search box.
  const searchMatchesWithoutCard = useMemo(() => {
    const q = clientSearch.trim().toLowerCase();
    if (!q) return [];
    const shownIds = new Set(clientCards.map((x) => x.client.id));
    return (clients || [])
      .filter(
        (c) => !shownIds.has(c.id) && (c.name || "").toLowerCase().includes(q),
      )
      .slice(0, 5);
  }, [clientSearch, clientCards, clients]);

  function renderNote(n, { showClient }) {
    const client = clientById[n.client_id];
    const linked = taskForNote(n);
    const editing = editingNoteId === n.id;
    return (
      <li
        key={n.id}
        id={`note-${n.id}`}
        className={"note-row" + (highlightNoteId === n.id ? " highlight" : "")}
      >
        <div className="task-meta note-meta">
          {n.pinned && <span className="task-chip">Pinned</span>}
          {!notesLegacy && (
            <span className="task-chip">
              {NOTE_CATEGORY_LABEL[n.category] || n.category}
            </span>
          )}
          {showClient && client && (
            <span className="task-client">{client.name}</span>
          )}
          <span>{n.author_name || n.author_email}</span>
          <span className="task-due">
            {fmtDateTime(n.updated_at || n.created_at)}
            {n.updated_at ? " (edited)" : ""}
          </span>
        </div>
        {editing ? (
          <div className="note-edit">
            <textarea
              className="note-textarea"
              rows={3}
              aria-label="Edit note"
              value={editingNoteText}
              onChange={(e) => setEditingNoteText(e.target.value)}
            />
            <div className="note-composer-actions">
              <button
                type="button"
                className="btn-secondary"
                onClick={() => setEditingNoteId(null)}
              >
                Cancel
              </button>
              <button
                type="button"
                className="btn-primary"
                disabled={!editingNoteText.trim()}
                onClick={() => saveNoteEdit(n)}
              >
                Save
              </button>
            </div>
          </div>
        ) : (
          <p className="note-text">{n.text}</p>
        )}
        {!editing && (
          <div className="note-actions">
            {linked ? (
              <button
                type="button"
                className="note-link-chip"
                onClick={() => jumpToTask(linked)}
                title={linked.text}
              >
                Task · {linked.done ? "Done" : staffItemDueLabel(linked, today) || "Open"}
              </button>
            ) : (
              n.linked_task_id && (
                <span className="task-chip" title="Linked to a task you can't see">
                  Linked task
                </span>
              )
            )}
            <button type="button" className="note-action" onClick={() => pinNote(n)}>
              {n.pinned ? "Unpin" : "Pin"}
            </button>
            <button
              type="button"
              className="note-action"
              onClick={() => {
                setEditingNoteId(n.id);
                setEditingNoteText(n.text);
              }}
            >
              Edit
            </button>
            {!notesLegacy && !staffItemsApi.legacy && !linked && !n.linked_task_id && (
              <button
                type="button"
                className="note-action"
                onClick={() => makeTaskFromNote(n)}
              >
                Make task
              </button>
            )}
            <button
              type="button"
              className="note-action danger"
              onClick={() => removeNote(n)}
              aria-label={`Delete note: ${n.text.slice(0, 40)}`}
            >
              Delete
            </button>
          </div>
        )}
      </li>
    );
  }

  function renderClientCard(x) {
    const { client, open, notes: cNotes, handoff, override } = x;
    const health = effectiveClientHealth(client, today, statusOverrides);
    const editingHandoff = editingHandoffFor === client.id;
    return (
      <section className="tn-client-card" key={client.id} aria-label={client.name}>
        <header className="tn-client-head">
          <h4 className="tn-client-name">{client.name}</h4>
          <span className="tn-client-status">
            <ClientHealthDot health={health} />
            <span>{CLIENT_HEALTH_LABEL[health.status] || ""}</span>
          </span>
          {x.overdue > 0 && (
            <span className="task-chip bad">{x.overdue} overdue</span>
          )}
        </header>
        {override && override.status && (override.note || override.set_by) && (
          <p className="tn-status-reason">
            {override.note}
            {override.set_by && (
              <span className="tn-muted">
                {override.note ? " — " : ""}set by {override.set_by.split("@")[0]}
              </span>
            )}
          </p>
        )}

        <div className="tn-section">
          <div className="tn-section-head">
            <span className="tn-label">Handoff summary</span>
            {!editingHandoff && (
              <button
                type="button"
                className="note-action"
                onClick={() => {
                  setEditingHandoffFor(client.id);
                  setHandoffDraft((handoff && handoff.note) || "");
                }}
              >
                {handoff && (handoff.note || "").trim() ? "Edit" : "Add"}
              </button>
            )}
          </div>
          {editingHandoff ? (
            <div className="note-edit">
              <textarea
                className="note-textarea"
                rows={4}
                aria-label={`Handoff summary for ${client.name}`}
                value={handoffDraft}
                onChange={(e) => setHandoffDraft(e.target.value)}
                placeholder="Waiting on March bank statement, flagged for QuickBooks migration, ..."
              />
              <div className="note-composer-actions">
                <button
                  type="button"
                  className="btn-secondary"
                  onClick={() => setEditingHandoffFor(null)}
                >
                  Cancel
                </button>
                <button
                  type="button"
                  className="btn-primary"
                  disabled={savingHandoff}
                  onClick={() => saveHandoff(client.id)}
                >
                  {savingHandoff ? "Saving…" : "Save"}
                </button>
              </div>
            </div>
          ) : handoff && (handoff.note || "").trim() ? (
            <>
              <p className="note-text">{handoff.note}</p>
              {handoff.updated_by && (
                <p className="tn-muted tn-small">
                  Last edited by {handoff.updated_by.split("@")[0]}
                  {handoff.updated_at ? ` · ${fmtDateTime(handoff.updated_at)}` : ""}
                </p>
              )}
            </>
          ) : (
            <p className="tn-muted">No handoff summary yet.</p>
          )}
        </div>

        <div className="tn-section">
          <div className="tn-section-head">
            <span className="tn-label">
              Open tasks{open.length > 0 ? ` · ${open.length}` : ""}
            </span>
          </div>
          {open.length === 0 ? (
            <p className="tn-muted">No open tasks.</p>
          ) : (
            <ul className="task-list tn-task-list" aria-label={`Open tasks for ${client.name}`}>
              {open.map(renderRow)}
            </ul>
          )}
        </div>

        <div className="tn-section">
          <div className="tn-section-head">
            <span className="tn-label">SOP</span>
            <button
              type="button"
              className="note-action"
              aria-label={`View SOP for ${client.name}`}
              onClick={() => openSop(client.id)}
            >
              View SOP
            </button>
          </div>
          <p className="tn-muted tn-small sop-indicator">
            {sopsMissing
              ? CLIENT_SOP_MISSING_TEXT
              : `SOP: ${sopCounts[client.id] || 0} of ${CLIENT_SOP_SECTIONS.length} sections filled`}
          </p>
        </div>

        <div className="tn-section">
          <div className="tn-section-head">
            <span className="tn-label">Latest notes</span>
            {cNotes.length > 3 && (
              <button
                type="button"
                className="note-action"
                onClick={() => {
                  setNoteClientFilter(client.id);
                  setNoteCategoryFilter("");
                  scrollToTasksCard("my-tasks-notes");
                }}
              >
                All {cNotes.length}
              </button>
            )}
          </div>
          {cNotes.length === 0 ? (
            <p className="tn-muted">No notes yet.</p>
          ) : (
            <ul className="note-list">
              {cNotes.slice(0, 3).map((n) => renderNote(n, { showClient: false }))}
            </ul>
          )}
        </div>

        {composerFor === client.id && (
          <NoteComposer
            fixedClientId={client.id}
            legacy={notesLegacy}
            onSubmit={async (f) => {
              const ok = await addNote(f);
              if (ok) setComposerFor(null);
              return ok;
            }}
            onCancel={() => setComposerFor(null)}
          />
        )}
        {composerFor !== client.id && (
          <div className="tn-card-actions">
            <button
              type="button"
              className="btn-secondary"
              onClick={() => setComposerFor(client.id)}
            >
              Add note
            </button>
            <button
              type="button"
              className="btn-secondary"
              onClick={() => startTaskForClient(client.id)}
            >
              Add task
            </button>
          </div>
        )}
      </section>
    );
  }

  function renderRow(t) {
    const client = t.client_id ? clientById[t.client_id] : null;
    const overdue = !t.done && t.due_date && t.due_date < today;
    const mine = t.staff_email === me;
    const remindDue =
      !t.done && t.remind_at && new Date(t.remind_at).getTime() <= nowMs;
    const dueLabel = staffItemDueLabel(t, today);
    const checkboxId = `task-done-${t.id}`;
    return (
      <li className={"task-row" + (t.done ? " done" : "")} key={t.id}>
        <label className="task-check-wrap">
          <input
            id={checkboxId}
            type="checkbox"
            className="task-check"
            checked={t.done}
            onChange={() => toggleTask(t)}
            aria-label={`${t.done ? "Mark not done" : "Mark done"}: ${t.text}`}
          />
        </label>
        <div className="task-main">
          <label htmlFor={checkboxId} className="task-text">
            {t.text}
          </label>
          <div className="task-meta">
            {t.kind === "reminder" && (
              <span className="task-chip">Reminder</span>
            )}
            {checklistCounts[t.id] && checklistCounts[t.id].total > 0 && (
              <button
                type="button"
                className={
                  "task-chip tcl-chip" +
                  (checklistCounts[t.id].done === checklistCounts[t.id].total ? " complete" : "")
                }
                onClick={() => setOpenChecklistId(openChecklistId === t.id ? null : t.id)}
                aria-expanded={openChecklistId === t.id}
                aria-label={`Checklist ${checklistCounts[t.id].done} of ${checklistCounts[t.id].total} done: ${t.text}`}
                title="Show checklist"
              >
                {typeof TCL_Icon === "function" && <TCL_Icon width="12" height="12" />}
                {checklistCounts[t.id].done}/{checklistCounts[t.id].total}
              </button>
            )}
            {t.priority === "high" && !t.done && (
              <span className="task-chip bad">High priority</span>
            )}
            {client && <span className="task-client">{client.name}</span>}
            {!client && t.client_id && (
              <span className="task-client">{t.client_id}</span>
            )}
            {dueLabel && !t.done && (
              <span className={"task-due" + (overdue ? " overdue" : "")}>
                {dueLabel}
              </span>
            )}
            {t.done && t.completed_at && (
              <span className="task-due">
                Completed {fmtDate(t.completed_at.slice(0, 10))}
              </span>
            )}
            {t.recurrence && t.recurrence !== "none" && (
              <span
                className="task-icon-label"
                title={`Repeats ${TASK_RECURRENCE_LABEL[t.recurrence].toLowerCase()}`}
              >
                <RepeatIcon />
                <span>{TASK_RECURRENCE_LABEL[t.recurrence]}</span>
              </span>
            )}
            {t.remind_at && !t.done && (
              <span
                className={"task-icon-label" + (remindDue ? " attention" : "")}
              >
                <BellIcon />
                <span>{fmtDateTime(t.remind_at)}</span>
              </span>
            )}
            {t.visibility === "shared" && (
              <span className="task-chip">
                Shared{!mine && t.staff_email ? ` · ${t.staff_email.split("@")[0]}` : ""}
              </span>
            )}
            {t.source === "note" && noteById[t.source_ref] ? (
              <button
                type="button"
                className="note-link-chip"
                onClick={() => jumpToNote(noteById[t.source_ref])}
                title={noteById[t.source_ref].text}
              >
                From note
              </button>
            ) : (
              t.source &&
              TASK_SOURCE_LABEL[t.source] && (
                <span className="task-chip">{TASK_SOURCE_LABEL[t.source]}</span>
              )
            )}
          </div>
          {openChecklistId === t.id && typeof TCL_Checklist === "function" && (
            <TCL_Checklist
              task={t}
              canEdit={mine || (t.visibility === "shared" && !!t.client_id)}
            />
          )}
        </div>
        <div className="task-actions">
          {!legacy && t.kind !== "note" && typeof TCL_Checklist === "function" && (
            <button
              type="button"
              className={"task-icon-btn" + (openChecklistId === t.id ? " active" : "")}
              onClick={() => setOpenChecklistId(openChecklistId === t.id ? null : t.id)}
              aria-expanded={openChecklistId === t.id}
              aria-label={`${openChecklistId === t.id ? "Hide" : "Show"} checklist: ${t.text}`}
              title={openChecklistId === t.id ? "Hide checklist" : "Checklist"}
            >
              <TCL_Icon />
            </button>
          )}
          {mine && !legacy && t.client_id && !t.done && (
            <button
              type="button"
              className="task-icon-btn"
              onClick={() => toggleShared(t)}
              aria-pressed={t.visibility === "shared"}
              aria-label={
                t.visibility === "shared"
                  ? `Stop sharing with ${client ? client.name : "client"}'s team: ${t.text}`
                  : `Share with ${client ? client.name : "client"}'s team: ${t.text}`
              }
              title={
                t.visibility === "shared"
                  ? "Stop sharing with this client's team"
                  : "Share with this client's team"
              }
            >
              <UsersIcon width="16" height="16" />
            </button>
          )}
          {!legacy && t.kind !== "note" && typeof TT_TemplateIcon === "function" && (
            <button
              type="button"
              className="task-icon-btn"
              onClick={() => saveAsTemplate(t)}
              aria-label={`${canCreateTemplates ? "Save as template" : "Suggest as template"}: ${t.text}`}
              title={canCreateTemplates ? "Save as template" : "Suggest as a template (admins review it)"}
            >
              <TT_TemplateIcon />
            </button>
          )}
          {mine && (
            <button
              type="button"
              className="task-icon-btn"
              onClick={() => removeTask(t)}
              aria-label={`Remove task: ${t.text}`}
              title="Remove"
            >
              ×
            </button>
          )}
        </div>
      </li>
    );
  }

  return (
    <div className="tasks-page">
      {canManageTemplates && onOpenTemplates && (
        <div className="tasks-manage-templates">
          <button type="button" className="link-btn" onClick={onOpenTemplates}>
            <RepeatIcon />
            <span>Manage templates</span>
          </button>
          <span className="tasks-manage-hint">Recurring tasks, in Settings → Firm settings</span>
        </div>
      )}
      <div className="card" style={{ marginBottom: 20 }}>
        <h3 className="card-title">Add a task or reminder</h3>
        <p className="card-subtitle">
          Private to you and admins unless you share it with a client's team.
        </p>
        <form
          className="task-add"
          onSubmit={(e) => {
            e.preventDefault();
            addTask();
          }}
        >
          <div className="task-add-row">
            <input
              ref={addTextRef}
              type="text"
              className="task-add-text"
              placeholder="Reconcile Riverside's operating account"
              aria-label="Task"
              value={newText}
              onChange={(e) => setNewText(e.target.value)}
            />
            <button
              type="submit"
              className="btn-primary"
              disabled={adding || !newText.trim()}
            >
              Add
            </button>
          </div>
          <div className="task-add-options">
            <label className="task-field">
              <span>Client</span>
              <select
                value={newClientId}
                onChange={(e) => {
                  setNewClientId(e.target.value);
                  if (!e.target.value) setNewShared(false);
                }}
              >
                <option value="">No client</option>
                {(clients || []).map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </select>
            </label>
            <label className="task-field">
              <span>Due</span>
              <input
                type="date"
                value={newDueDate}
                onChange={(e) => setNewDueDate(e.target.value)}
              />
            </label>
            {!legacy && (
              <label className="task-field">
                <span>Time</span>
                <input
                  type="time"
                  value={newDueTime}
                  disabled={!newDueDate}
                  onChange={(e) => setNewDueTime(e.target.value)}
                />
              </label>
            )}
            {!legacy && (
              <label className="task-field">
                <span>Type</span>
                <select
                  value={newKind}
                  onChange={(e) => setNewKind(e.target.value)}
                >
                  <option value="task">Task</option>
                  <option value="reminder">Reminder</option>
                </select>
              </label>
            )}
            {!legacy && (
              <label className="task-field">
                <span>Remind me</span>
                <input
                  type="datetime-local"
                  value={newRemindAt}
                  onChange={(e) => setNewRemindAt(e.target.value)}
                />
              </label>
            )}
            {!legacy && (
              <label className="task-field">
                <span>Repeat</span>
                <select
                  value={newRecurrence}
                  disabled={!newDueDate}
                  onChange={(e) => setNewRecurrence(e.target.value)}
                  title={newDueDate ? undefined : "Pick a due date to repeat"}
                >
                  {TASK_RECURRENCES.map((r) => (
                    <option key={r} value={r}>
                      {TASK_RECURRENCE_LABEL[r]}
                    </option>
                  ))}
                </select>
              </label>
            )}
            <label className="task-field">
              <span>Priority</span>
              <select
                value={newPriority}
                onChange={(e) => setNewPriority(e.target.value)}
              >
                {TASK_PRIORITIES.map((p) => (
                  <option key={p} value={p}>
                    {TASK_PRIORITY_LABEL[p]}
                  </option>
                ))}
              </select>
            </label>
            {!legacy && (
              <label
                className={"task-share" + (newClientId ? "" : " disabled")}
              >
                <input
                  type="checkbox"
                  checked={newShared}
                  disabled={!newClientId}
                  onChange={(e) => setNewShared(e.target.checked)}
                />
                <span>
                  Share with this client's team
                  {!newClientId && (
                    <span className="task-share-hint"> — pick a client first</span>
                  )}
                </span>
              </label>
            )}
          </div>
          {legacy && (
            <p className="card-subtitle" style={{ marginTop: 12 }}>
              Times, reminders, repeats and sharing turn on once the
              staff-reminders-v2 database update is applied.
            </p>
          )}
        </form>
      </div>

      {error && (
        <div className="card" style={{ marginBottom: 20 }}>
          <p className="card-subtitle negative">{error}</p>
        </div>
      )}

      <div className="card">
        <div className="task-toolbar">
          <div className="view-toggle task-tabs" role="tablist" aria-label="Task view">
            {TASK_TABS.map((t) => {
              const count = buckets[t.id] ? buckets[t.id].length : 0;
              const active = (!showCompleted || !TASK_LIST_TABS.includes(t.id)) && tab === t.id;
              return (
                <button
                  key={t.id}
                  type="button"
                  role="tab"
                  aria-selected={active}
                  className={"view-toggle-btn" + (active ? " active" : "")}
                  onClick={() => {
                    setTab(t.id);
                    setShowCompleted(false);
                  }}
                >
                  {t.label}
                  {count > 0 && (
                    <span
                      className={
                        "task-tab-count" +
                        (t.id === "overdue" && !active ? " bad" : "")
                      }
                    >
                      {count}
                    </span>
                  )}
                </button>
              );
            })}
          </div>
          {tab === "byclient" && (
            <div className="task-filters">
              <label className="task-field compact tn-search">
                <input
                  type="search"
                  placeholder="Search clients"
                  aria-label="Search clients"
                  value={clientSearch}
                  onChange={(e) => setClientSearch(e.target.value)}
                />
              </label>
            </div>
          )}
          {isListTab && (
          <div className="task-filters">
            <label className="task-field compact">
              <select
                aria-label="Filter by client"
                value={clientFilter}
                onChange={(e) => setClientFilter(e.target.value)}
              >
                <option value="">All clients</option>
                <option value="__none">No client</option>
                {(clients || []).map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </select>
            </label>
            {!legacy && (
              <label className="task-field compact">
              <select
                aria-label="Mine or shared"
                  value={scopeFilter}
                  onChange={(e) => setScopeFilter(e.target.value)}
                >
                  <option value="all">Mine + shared</option>
                  <option value="mine">Mine</option>
                  <option value="shared">Shared</option>
                </select>
              </label>
            )}
            <button
              type="button"
              className="btn-secondary task-completed-toggle"
              aria-pressed={showCompleted}
              onClick={() => setShowCompleted((v) => !v)}
            >
              {showCompleted ? "Hide completed" : `Completed (${completedTasks.length})`}
            </button>
          </div>
          )}
        </div>

        {isListTab && tasks === null && (
          <p className="card-subtitle" style={{ marginTop: 16 }}>
            Loading…
          </p>
        )}
        {isListTab && tasks && shown.length === 0 && !error && (
          <p className="card-subtitle" style={{ marginTop: 16 }}>
            {showCompleted ? "Nothing completed yet." : TASK_TAB_EMPTY[tab]}
          </p>
        )}
        {isListTab && shown.length > 0 && (
          <ul className="task-list" aria-label={showCompleted ? "Completed tasks" : `${TASK_TABS.find((x) => x.id === tab).label} tasks`}>
            {shown.map(renderRow)}
          </ul>
        )}

        {tab === "byclient" && notesError && (
          <p className="card-subtitle negative" style={{ marginTop: 16 }}>
            {notesError}
          </p>
        )}

        {tab === "byclient" && (
          <div className="tn-view">
            <p className="card-subtitle tn-intro">
              Staff-only — clients never see any of this. The handoff summary
              is the same one on Home.
            </p>
            {(tasks === null || notes === null) && (
              <p className="card-subtitle">Loading…</p>
            )}
            {tasks !== null && notes !== null && clientCards.length === 0 && (
              <p className="card-subtitle">
                {clientSearch.trim()
                  ? "No matching client has tasks or notes yet."
                  : "No client has open tasks, notes or a handoff summary yet."}
              </p>
            )}
            {searchMatchesWithoutCard.length > 0 && (
              <div className="tn-start-list">
                {searchMatchesWithoutCard.map((c) => (
                  <button
                    key={c.id}
                    type="button"
                    className="btn-secondary"
                    onClick={() => setComposerFor(c.id)}
                  >
                    Add a note for {c.name}
                  </button>
                ))}
              </div>
            )}
            <div className="tn-client-grid">{clientCards.map(renderClientCard)}</div>
          </div>
        )}
      </div>

      <div className="card" id="my-tasks-notes" style={{ marginTop: 20 }}>
        <div className="task-toolbar">
          <div>
            <h3 className="card-title">Notes</h3>
            <p className="card-subtitle">
              Client notes from here, Home and Client details. Staff-only.
            </p>
          </div>
          <div className="task-filters">
            <label className="task-field compact">
              <select
                aria-label="Filter notes by client"
                value={noteClientFilter}
                onChange={(e) => setNoteClientFilter(e.target.value)}
              >
                <option value="">All clients</option>
                {(clients || []).map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </select>
            </label>
            {!notesLegacy && (
              <label className="task-field compact">
                <select
                  aria-label="Filter notes by category"
                  value={noteCategoryFilter}
                  onChange={(e) => setNoteCategoryFilter(e.target.value)}
                >
                  <option value="">All categories</option>
                  {NOTE_CATEGORIES.map((c) => (
                    <option key={c} value={c}>
                      {NOTE_CATEGORY_LABEL[c]}
                    </option>
                  ))}
                </select>
              </label>
            )}
          </div>
        </div>
        {notesError && (
          <p className="card-subtitle negative" style={{ marginTop: 16 }}>
            {notesError}
          </p>
        )}
        <div className="tn-view">
          <NoteComposer
            clients={clients}
            fixedClientId={null}
            legacy={notesLegacy}
            onSubmit={addNote}
          />
          {notes === null && <p className="card-subtitle">Loading…</p>}
          {notes !== null && filteredNotes.length === 0 && !notesError && (
            <p className="card-subtitle">
              {visibleNotes.length === 0
                ? "No notes yet — add one above."
                : "No notes match these filters."}
            </p>
          )}
          {filteredNotes.length > 0 && (
            <ul className="note-list" aria-label="Client notes">
              {filteredNotes.map((n) => renderNote(n, { showClient: true }))}
            </ul>
          )}
          {notesLegacy && (
            <p className="card-subtitle" style={{ marginTop: 12 }}>
              Categories and note-to-task links turn on once the
              tasks-notes-v3 database update is applied.
            </p>
          )}
        </div>
      </div>

      <div className="card" id="my-tasks-sops" style={{ marginTop: 20 }}>
        <div className="task-toolbar">
          <div>
            <h3 className="card-title">SOPs</h3>
            <p className="card-subtitle">
              How each client's books are run, so anyone on the team can step
              in. Staff-only; every edit is kept in History.
            </p>
          </div>
          <div className="task-filters">
            <label className="task-field compact tn-search">
              <input
                type="search"
                placeholder="Search clients"
                aria-label="Search clients for an SOP"
                value={sopSearch}
                onChange={(e) => {
                  setSopSearch(e.target.value);
                  if (e.target.value) setSopClientId("");
                }}
              />
            </label>
          </div>
        </div>
        <div className="tn-view">
          {sopsMissing ? (
            <p className="card-subtitle">{CLIENT_SOP_MISSING_TEXT}</p>
          ) : sopClient ? (
            <>
              <div className="sop-client-head">
                <h3 className="sop-client-name">{sopClient.name}</h3>
                <button
                  type="button"
                  className="btn-secondary"
                  onClick={() => setSopClientId("")}
                >
                  Change client
                </button>
              </div>
              <ClientSopView client={sopClient} />
            </>
          ) : sopPickerClients.length === 0 ? (
            <p className="card-subtitle">
              {sopSearch.trim() ? "No matching client." : "No clients yet."}
            </p>
          ) : (
            <ul className="sop-picker" aria-label="Pick a client">
              {sopPickerClients.map((c) => (
                <li key={c.id}>
                  <button
                    type="button"
                    className="sop-picker-btn"
                    onClick={() => setSopClientId(c.id)}
                  >
                    <span className="sop-picker-name">{c.name}</span>
                    <span className="sop-picker-count">
                      {sopCounts[c.id] || 0} of {CLIENT_SOP_SECTIONS.length} filled
                    </span>
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </div>
  );
}

// Built-in Documents folder (staff only) listing files under
// <client>/internal/. Not a real folder name, so it can't clash with one.
const DOC_STAFF_FOLDER = "\u0000staff-only";
// Built-in Trash folder (staff only): files moved to <client>/trash/ and
// links with trashed_at set (supabase/document-trash.sql). Restorable.
const DOC_TRASH_FOLDER = "\u0000trash";

function DocumentsPage({ client, isBookkeeper, searchTarget }) {
  // Folders are shared per client in the database (components/client/
  // DocFolders.jsx); "local" is the per-browser fallback for prototype
  // clients and signed-out use.
  const [folders, setFolders] = useState(
    () => loadDocFolders(client.id).folders,
  );
  const [folderMode, setFolderMode] = useState("local");
  // Three sources, one list:
  //   - client.documents: data.js sample files (sample clients only; the
  //     QuickBooks mapper empties it),
  //   - client_documents: links MyGoodBooks staff add (Google Drive etc.),
  //   - client-uploads/<client>/shared/: files anyone at the org uploads
  //     here, stored for real in Supabase Storage.
  // Each row has a stable `key` that folder assignments are saved under
  // (they used to be keyed by filename, so two files with the same name
  // shared a folder).
  const [docs, setDocs] = useState(() => {
    const { assignments } = loadDocFolders(client.id);
    return (client.documents || []).map((d) => ({
      ...d,
      key: "sample:" + d.name,
      source: "sample",
      folder: assignments["sample:" + d.name] || assignments[d.name] || null,
    }));
  });
  const [remoteState, setRemoteState] = useState("idle"); // idle | loading | ready | error
  const [uploading, setUploading] = useState(false);
  const [docSearch, setDocSearch] = useState("");
  const [docSort, setDocSort] = useState("newest"); // newest | oldest | name
  // Google Drive file storage (components/files/DriveFiles.js): connected?,
  // how many old Storage files haven't been copied yet, and the staff upload
  // picker (Drive folder <Client>/<Year>/<Document type>).
  const [driveInfo, setDriveInfo] = useState({ connected: null, legacyCount: 0 });
  const [uploadDocType, setUploadDocType] = useState("Other");
  const [uploadYear, setUploadYear] = useState(() => DRV_currentYear());
  const [copyingLegacy, setCopyingLegacy] = useState(false);
  const docSb = window.mgbSupabase || null;

  const loadRemoteDocs = useCallback(async () => {
    const fm = await DF_load(docSb, client.id);
    const { assignments } = fm;
    setFolderMode(fm.mode);
    setFolders(fm.folders);
    setDocs((prev) =>
      prev.map((d) =>
        d.source === "sample" ? { ...d, folder: assignments[d.key] || assignments[d.name] || null } : d,
      ),
    );
    if (!docSb) return;
    // Signed out (the local prototype): nothing to load, and storage would
    // just answer "permission denied".
    const sess = await docSb.auth.getSession();
    if (!sess.data || !sess.data.session) return;
    setRemoteState("loading");
    // Staff also see the client's staff-only files (client-uploads/<client>/
    // internal/, supabase/staff-only-documents.sql). Client users can't read
    // that folder, so they never ask for it.
    const staffList = (sub) =>
      isBookkeeper
        ? docSb.storage.from("client-uploads").list(`${client.id}/${sub}`, {
            limit: 500,
            sortBy: { column: "created_at", order: "desc" },
          })
        : Promise.resolve({ data: [], error: null });
    // Files in Google Drive (client_files, through the drive-files function).
    // Listing works whether or not Drive is connected yet.
    const driveP = Promise.all([
      DRV_list(client.id, "documents").catch(() => null),
      isBookkeeper ? DRV_list(client.id, "trash").catch(() => null) : Promise.resolve(null),
      DRV_status(),
    ]);
    const [linksRes, filesRes, internalRes, trashSharedRes, trashInternalRes] = await Promise.all([
      docSb
        .from("client_documents")
        .select(isBookkeeper ? "id, name, drive_url, category, created_at, trashed_at" : "id, name, drive_url, category, created_at")
        .eq("client_id", client.id)
        .order("created_at", { ascending: false })
        .limit(500),
      docSb.storage
        .from("client-uploads")
        .list(`${client.id}/shared`, {
          limit: 500,
          sortBy: { column: "created_at", order: "desc" },
        }),
      staffList("internal"),
      staffList("trash/shared"),
      staffList("trash/internal"),
    ]);
    if (linksRes.error && filesRes.error) {
      setRemoteState("error");
      return;
    }
    const linkRow = (r) => ({
      key: "link:" + r.id,
      id: r.id,
      source: "link",
      name: r.name,
      category: r.category || "Shared by MyGoodBooks",
      uploadedBy: "MyGoodBooks",
      date: String(r.created_at || "").slice(0, 10),
      size: "Link",
      url: safeHttpUrl(r.drive_url),
    });
    const links = (linksRes.data || []).filter((r) => !r.trashed_at).map(linkRow);
    const files = (filesRes.data || [])
      .filter((f) => f && f.id && f.name)
      .map((f) => ({
        key: "file:" + f.name,
        source: "upload",
        // Stored as "<timestamp>-<name>"; show the original name.
        name: f.name.replace(/^\d+-/, ""),
        category: "Uploaded",
        uploadedBy: "Your organization",
        date: String(f.created_at || "").slice(0, 10),
        size: f.metadata && f.metadata.size ? formatBytes(f.metadata.size) : "",
        path: `${client.id}/shared/${f.name}`,
      }));
    const internalFiles = ((internalRes && internalRes.data) || [])
      .filter((f) => f && f.id && f.name)
      .map((f) => ({
        key: "file:internal/" + f.name,
        source: "upload",
        staffOnly: true,
        name: f.name.replace(/^\d+-/, ""),
        category: "Staff only",
        uploadedBy: "MyGoodBooks",
        date: String(f.created_at || "").slice(0, 10),
        size: f.metadata && f.metadata.size ? formatBytes(f.metadata.size) : "",
        path: `${client.id}/internal/${f.name}`,
      }));
    const [driveRes, driveTrashRes, driveConnected] = await driveP;
    // Old Storage files already copied into Drive show once, as the Drive
    // copy (the originals stay in Storage untouched).
    const copied = new Set((driveRes && driveRes.copied_legacy_paths) || []);
    const fromStaff = (email) => /@mygoodbooks\.org$/i.test(String(email || ""));
    const driveRow = (r) => {
      const base = String(r.legacy_path || "").split("/").pop();
      const legacyKey = r.legacy_path
        ? r.legacy_path.startsWith(`${client.id}/internal/`)
          ? "file:internal/" + base
          : r.legacy_path.startsWith(`${client.id}/shared/`)
            ? "file:" + base
            : null
        : null;
      return {
        key: "drive:" + r.id,
        legacyKey,
        driveId: r.id,
        source: "drive",
        staffOnly: r.visibility === "internal",
        name: r.name,
        category: r.visibility === "internal" ? "Staff only" : r.doc_type || "Uploaded",
        uploadedBy: isBookkeeper ? r.uploaded_by || "" : fromStaff(r.uploaded_by) ? "MyGoodBooks" : "Your organization",
        date: String(r.uploaded_at || "").slice(0, 10),
        size: r.size ? formatBytes(r.size) : "",
        webViewLink: isBookkeeper ? r.web_view_link || null : null,
      };
    };
    const driveFiles = ((driveRes && driveRes.files) || []).map(driveRow);
    const oldFiles = [...files, ...internalFiles].filter((d) => !copied.has(d.path));
    setDriveInfo({ connected: !!driveConnected, legacyCount: oldFiles.length });
    const remote = [...driveFiles, ...oldFiles, ...links].map((d) => ({
      ...d,
      folder: assignments[d.key] || (d.legacyKey && assignments[d.legacyKey]) || null,
    }));
    setDocs((prev) => [...prev.filter((d) => d.source === "sample"), ...remote]);
    // Trash keeps each item's original key, so its folder comes back on
    // restore.
    const trashFile = (sub) => (f) => {
      const origKey = "file:" + (sub === "internal" ? "internal/" : "") + f.name;
      return {
        key: "trash:" + origKey,
        origKey,
        trashed: true,
        source: "upload",
        staffOnly: sub === "internal",
        name: f.name.replace(/^\d+-/, ""),
        category: sub === "internal" ? "Staff only" : "Uploaded",
        uploadedBy: sub === "internal" ? "MyGoodBooks" : "Your organization",
        date: String(f.created_at || "").slice(0, 10),
        size: f.metadata && f.metadata.size ? formatBytes(f.metadata.size) : "",
        path: `${client.id}/trash/${sub}/${f.name}`,
        restorePath: `${client.id}/${sub}/${f.name}`,
        folder: assignments[origKey] || null,
      };
    };
    const okFile = (f) => f && f.id && f.name;
    setTrashDocs([
      ...((driveTrashRes && driveTrashRes.files) || []).map((r) => {
        const d = driveRow(r);
        return { ...d, key: "trash:" + d.key, origKey: d.key, trashed: true, folder: assignments[d.key] || null };
      }),
      ...((trashSharedRes && trashSharedRes.data) || []).filter(okFile).map(trashFile("shared")),
      ...((trashInternalRes && trashInternalRes.data) || []).filter(okFile).map(trashFile("internal")),
      ...(linksRes.data || [])
        .filter((r) => r.trashed_at)
        .map((r) => {
          const d = linkRow(r);
          return { ...d, key: "trash:" + d.key, origKey: d.key, trashed: true, folder: assignments[d.key] || null };
        }),
    ]);
    setRemoteState(linksRes.error || filesRes.error ? "error" : "ready");
  }, [docSb, client.id, isBookkeeper]);

  useEffect(() => {
    loadRemoteDocs();
  }, [loadRemoteDocs]);
  // A file dropped anywhere on the page (components/staff/PageDrop.jsx)
  // lands here too; refresh when it's this client's.
  useEffect(() => {
    const onChanged = (e) => {
      if (!e.detail || e.detail.clientId === client.id) loadRemoteDocs();
    };
    window.addEventListener(PD_DOCS_CHANGED_EVENT, onChanged);
    return () => window.removeEventListener(PD_DOCS_CHANGED_EVENT, onChanged);
  }, [client.id, loadRemoteDocs]);

  const openDoc = async (d, index) => {
    if (d.source === "link") {
      if (d.url) window.open(d.url, "_blank", "noopener");
      else showToast("That link isn't a valid https:// address.");
      return;
    }
    if (d.source === "drive") {
      try {
        window.open(await DRV_link(d.driveId), "_blank", "noopener");
      } catch (e) {
        showToast(`Couldn't open that file: ${e.message}`);
      }
      return;
    }
    if (d.source === "upload") {
      const { data, error } = await docSb.storage
        .from("client-uploads")
        .createSignedUrl(d.path, 300);
      if (error || !data) {
        showToast("Couldn't open that file. Try again in a moment.");
        return;
      }
      window.open(data.signedUrl, "_blank", "noopener");
      return;
    }
    setPreviewIndex(index);
  };
  const [activeFolder, setActiveFolder] = useState(null); // null = "All"
  const [trashDocs, setTrashDocs] = useState([]);
  const [addingFolder, setAddingFolder] = useState(false);
  const [newFolderName, setNewFolderName] = useState("");
  const [isDragging, setIsDragging] = useState(false);
  const [previewIndex, setPreviewIndex] = useState(null);
  const fileInputRef = useRef(null);
  const newFolderInputRef = useRef(null);
  const showToast = useToast();
  const { flashCardId, jumpToCard } = useCardFlash();

  useEffect(() => {
    if (searchTarget)
      jumpToCard(searchTarget.highlightKey, searchTarget.highlightKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchTarget && searchTarget.nonce]);

  // Trash and restore (staff only). Files move between <client>/<sub>/ and
  // <client>/trash/<sub>/; links flip trashed_at. Trash never empties on
  // its own; only Delete forever (below) removes anything.
  const [trashBusy, setTrashBusy] = useState(null);
  const trashDoc = async (d) => {
    if (!docSb || trashBusy) return;
    setTrashBusy(d.key);
    let error = null;
    if (d.source === "link") {
      ({ error } = await docSb.from("client_documents").update({ trashed_at: new Date().toISOString() }).eq("id", d.id));
    } else if (d.source === "drive") {
      // Google Drive's own trash: nothing is deleted.
      error = await DRV_trash(d.driveId).then(() => null, (e) => e);
    } else {
      const rel = d.path.slice(client.id.length + 1);
      ({ error } = await docSb.storage.from("client-uploads").move(d.path, `${client.id}/trash/${rel}`));
    }
    setTrashBusy(null);
    if (error) {
      showToast(`Couldn't move ${d.name} to Trash: ${error.message}`);
      return;
    }
    showToast(
      d.source === "drive"
        ? `Moved ${d.name} to Trash (also Google Drive's trash). Restore it within 30 days, before Drive empties its trash.`
        : `Moved ${d.name} to Trash. You can restore it from the Trash folder.`,
    );
    loadRemoteDocs();
  };
  const restoreDoc = async (d) => {
    if (!docSb || trashBusy) return;
    setTrashBusy(d.key);
    let error = null;
    if (d.source === "link") {
      ({ error } = await docSb.from("client_documents").update({ trashed_at: null }).eq("id", d.id));
    } else if (d.source === "drive") {
      error = await DRV_restore(d.driveId).then(() => null, (e) => e);
    } else {
      ({ error } = await docSb.storage.from("client-uploads").move(d.path, d.restorePath));
    }
    setTrashBusy(null);
    if (error) {
      showToast(`Couldn't restore ${d.name}: ${error.message}`);
      return;
    }
    showToast(`Restored ${d.name}.`);
    loadRemoteDocs();
  };
  // Delete forever: staff, from Trash only, after a confirm. The storage
  // and table policies (supabase/document-folders.sql) only allow it for
  // items already in Trash. Both APIs answer "no error" when a policy
  // quietly matched nothing, so check something was actually removed.
  const [deletePending, setDeletePending] = useState(null);
  const deleteForever = async () => {
    const d = deletePending;
    setDeletePending(null);
    // Drive files are never deleted from the portal; Drive empties its own
    // trash after 30 days.
    if (!docSb || !d || !d.trashed || trashBusy || d.source === "drive") return;
    setTrashBusy(d.key);
    let res;
    if (d.source === "link") {
      res = await docSb
        .from("client_documents")
        .delete()
        .eq("id", d.id)
        .not("trashed_at", "is", null)
        .select("id");
    } else {
      res = await docSb.storage.from("client-uploads").remove([d.path]);
    }
    setTrashBusy(null);
    if (res.error || !res.data || !res.data.length) {
      showToast(`Couldn't delete ${d.name}${res.error ? ": " + res.error.message : ". You may not have permission."}`);
      return;
    }
    await DF_assign(docSb, client.id, folderMode, d.origKey, null);
    showToast(`Deleted ${d.name} forever.`);
    loadRemoteDocs();
  };

  // Real upload: same bucket and client-folder rule as the document-request
  // card (storage policy "client uploads own files"), under <client>/shared/.
  const addFiles = async (fileList) => {
    const files = Array.from(fileList || []);
    if (files.length === 0) return;
    const sess = docSb ? await docSb.auth.getSession() : null;
    if (!sess || !sess.data || !sess.data.session) {
      showToast("Uploading needs a signed-in account.");
      return;
    }
    const tooBig = files.find((f) => f.size > 25 * 1024 * 1024);
    if (tooBig) {
      showToast(`${tooBig.name} is ${formatBytes(tooBig.size)}. Files are capped at 25 MB.`);
      return;
    }
    // The Staff only folder uploads to <client>/internal/, which client
    // users can't read (supabase/staff-only-documents.sql).
    const staffView = isBookkeeper && activeFolder === DOC_STAFF_FOLDER;
    setUploading(true);
    let ok = 0;
    let firstError = null;
    const filed = [];
    // Google Drive when it's connected (components/files/DriveFiles.js);
    // Supabase Storage below is the fallback until then.
    let useStorage = true;
    try {
      useStorage = await DRV_useStorage();
    } catch (e) {
      setUploading(false);
      showToast(isBookkeeper ? e.message : "Uploads are paused for a moment. Please try again later.");
      return;
    }
    for (const f of useStorage ? [] : files) {
      try {
        const res = await DRV_upload({
          file: f,
          clientId: client.id,
          visibility: staffView ? "internal" : "shared",
          docType: isBookkeeper ? uploadDocType : "Other",
          year: isBookkeeper ? uploadYear : undefined,
        });
        ok += 1;
        if (activeFolder && !staffView && res.file) filed.push("drive:" + res.file.id);
      } catch (e) {
        firstError = firstError || e.message;
      }
    }
    for (const f of useStorage ? files : []) {
      const safe = f.name.replace(/[^\w.\- ]+/g, "_").slice(-120);
      const stored = `${Date.now()}-${safe}`;
      const { error } = await docSb.storage
        .from("client-uploads")
        .upload(`${client.id}/${staffView ? "internal" : "shared"}/${stored}`, f, {
          upsert: false,
          contentType: f.type || undefined,
        });
      if (error) {
        firstError = firstError || error.message;
      } else {
        ok += 1;
        if (activeFolder && !staffView) filed.push("file:" + stored);
      }
    }
    if (filed.length) {
      const err = await DF_assign(docSb, client.id, folderMode, filed, activeFolder);
      if (err) showToast(`Uploaded, but couldn't file into ${activeFolder}: ${err}`);
    }
    setUploading(false);
    if (ok && staffView) showToast(`Uploaded ${ok} staff-only file${ok > 1 ? "s" : ""}. ${client.name} can't see ${ok > 1 ? "them" : "it"}.`);
    else if (ok) showToast(`Uploaded ${ok} file${ok > 1 ? "s" : ""}. Your bookkeeper can see ${ok > 1 ? "them" : "it"} now.`);
    if (firstError) showToast(`Couldn't upload: ${firstError}`);
    loadRemoteDocs();
  };

  // Staff: copy this client's old Storage files into Drive (50 per click).
  // The originals stay where they are; the page then shows the Drive copy.
  const copyLegacy = async () => {
    if (copyingLegacy) return;
    setCopyingLegacy(true);
    try {
      const r = await DRV_copyLegacy(client.id);
      const left = Math.max(0, r.remaining || 0);
      showToast(
        `Copied ${r.copied} file${r.copied === 1 ? "" : "s"} to Google Drive.` +
          (left ? ` ${left} left; click again to continue.` : "") +
          (r.errors && r.errors.length ? ` ${r.errors.length} couldn't be copied: ${r.errors[0]}` : ""),
      );
    } catch (e) {
      showToast(`Couldn't copy files to Drive: ${e.message}`);
    }
    setCopyingLegacy(false);
    loadRemoteDocs();
  };

  const moveDocToFolder = async (index, folderName) => {
    const doc = docs[index];
    if (!doc) return;
    const prevFolder = doc.folder;
    const setFolder = (f) =>
      setDocs((d) => d.map((x) => (x.key === doc.key ? { ...x, folder: f || null } : x)));
    setFolder(folderName);
    const err = await DF_assign(docSb, client.id, folderMode, doc.key, folderName || null);
    if (err) {
      setFolder(prevFolder);
      showToast(`Couldn't move ${doc.name}: ${err}`);
    }
  };

  // Returns an error message, or null once the folder exists.
  const createFolder = async (name) => {
    if (folders.includes(name)) return `"${name}" already exists.`;
    const err = await DF_addFolder(docSb, client.id, folderMode, name, folders);
    if (err) return `Couldn't create "${name}": ${err}`;
    setFolders((f) => (f.includes(name) ? f : [...f, name]));
    return null;
  };

  const addFolder = async () => {
    const name = newFolderName.trim();
    if (!name) return;
    const err = await createFolder(name);
    if (err) {
      showToast(err);
      return;
    }
    setNewFolderName("");
    setAddingFolder(false);
    setActiveFolder(name);
  };

  // "+ New folder…" in a row's folder menu: the document's index in docs.
  const [newFolderFor, setNewFolderFor] = useState(null);
  const NEW_FOLDER_OPTION = "\u0000new";

  const [folderPendingDelete, setFolderPendingDelete] = useState(null);

  const confirmRemoveFolder = async () => {
    const name = folderPendingDelete;
    setFolderPendingDelete(null);
    const err = await DF_removeFolder(docSb, client.id, folderMode, name);
    if (err) {
      showToast(`Couldn't delete "${name}": ${err}`);
      return;
    }
    setFolders((f) => f.filter((x) => x !== name));
    setDocs((d) =>
      d.map((doc) => (doc.folder === name ? { ...doc, folder: null } : doc)),
    );
    if (activeFolder === name) setActiveFolder(null);
  };

  // "Full Access Only" filters down to the visibility flag itself
  // (set on the sample documents) rather than some separate "shared with me"
  // concept — this app's documents only ever carry that one binary flag
  // (org-wide vs. full-access-only), so that's the real, honest thing to
  // filter by. Only worth offering when there's at least one such document
  // to filter to — a restricted client viewer never has any (scopedClient's
  // documents are already filtered upstream), so this naturally stays
  // hidden for them.
  const [visFilter, setVisFilter] = useState("all");
  const hasRestrictedDocs = docs.some((d) => d.visibility === "full");
  const staffView = isBookkeeper && activeFolder === DOC_STAFF_FOLDER;
  const trashView = isBookkeeper && activeFolder === DOC_TRASH_FOLDER;
  const folderFiltered =
    activeFolder === null
      ? docs
      : trashView
        ? trashDocs
      : staffView
        ? docs.filter((d) => d.staffOnly)
        : docs.filter((d) => d.folder === activeFolder);
  const docQuery = docSearch.trim().toLowerCase();
  const visibleDocs = (
    visFilter === "full"
      ? folderFiltered.filter((d) => d.visibility === "full")
      : folderFiltered
  )
    .filter(
      (d) =>
        !docQuery ||
        [d.name, d.category, d.uploadedBy].some((v) =>
          String(v || "").toLowerCase().includes(docQuery),
        ),
    )
    .slice()
    .sort((a, b) => {
      if (docSort === "name") return String(a.name).localeCompare(String(b.name));
      const cmp = String(a.date || "").localeCompare(String(b.date || ""));
      return docSort === "oldest" ? cmp : -cmp;
    });
  const unfiledCount = docs.filter((d) => !d.folder).length;

  return (
    <div>
      {docs.some((d) => d.source === "sample") && (
        <MockBanner text="Sample documents are shown for this prototype client. Files you upload here are stored for real; folders are saved on this browser." client={client} />
      )}

      <DocumentRequestsCard client={client} />

      <div className="doc-folder-bar">
        <button
          type="button"
          className={
            "doc-folder-pill" + (activeFolder === null ? " active" : "")
          }
          onClick={() => setActiveFolder(null)}
        >
          <FolderIcon width="14" height="14" strokeWidth="1.8" />
          All Documents
          <span className="doc-folder-count">{docs.length}</span>
        </button>
        {isBookkeeper && (
          <button
            type="button"
            className={"doc-folder-pill doc-folder-staff" + (staffView ? " active" : "")}
            onClick={() => setActiveFolder(DOC_STAFF_FOLDER)}
            title="Files only MyGoodBooks staff can see"
          >
            <LockIcon />
            Staff only
            <span className="doc-folder-count">{docs.filter((d) => d.staffOnly).length}</span>
          </button>
        )}
        {isBookkeeper && (
          <button
            type="button"
            className={"doc-folder-pill doc-folder-staff" + (trashView ? " active" : "")}
            onClick={() => setActiveFolder(DOC_TRASH_FOLDER)}
            title="Documents moved to Trash. Clients can't see them."
          >
            <TrashIcon width="14" height="14" strokeWidth="1.8" />
            Trash
            <span className="doc-folder-count">{trashDocs.length}</span>
          </button>
        )}
        {folders.map((name) => {
          const count = docs.filter((d) => d.folder === name).length;
          return (
            <button
              type="button"
              key={name}
              className={
                "doc-folder-pill" + (activeFolder === name ? " active" : "")
              }
              onClick={() => setActiveFolder(name)}
            >
              <FolderIcon width="14" height="14" strokeWidth="1.8" />
              {name}
              <span className="doc-folder-count">{count}</span>
              <span
                className="doc-folder-remove"
                role="button"
                tabIndex={0}
                aria-label={`Delete folder ${name}`}
                onClick={(e) => {
                  e.stopPropagation();
                  setFolderPendingDelete(name);
                }}
                onKeyDown={(e) => {
                  if (e.key === "Enter") {
                    e.stopPropagation();
                    setFolderPendingDelete(name);
                  }
                }}
              >
                ×
              </span>
            </button>
          );
        })}
        {addingFolder ? (
          <span className="doc-folder-new">
            <input
              ref={newFolderInputRef}
              type="text"
              placeholder="Folder name"
              value={newFolderName}
              onChange={(e) => setNewFolderName(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") addFolder();
                if (e.key === "Escape") {
                  setAddingFolder(false);
                  setNewFolderName("");
                }
              }}
              autoFocus
            />
            <button type="button" className="btn-secondary" onClick={addFolder}>
              Add
            </button>
          </span>
        ) : (
          <button
            type="button"
            className="doc-folder-pill doc-folder-add-trigger"
            onClick={() => setAddingFolder(true)}
          >
            + New Folder
          </button>
        )}
      </div>

      {!trashView && (
      <div
        className={
          "card upload-card dropzone" + (isDragging ? " dragging" : "")
        }
        style={{ marginBottom: 20 }}
        onClick={() => fileInputRef.current.click()}
        onDragOver={(e) => {
          e.preventDefault();
          setIsDragging(true);
        }}
        onDragLeave={() => setIsDragging(false)}
        onDrop={(e) => {
          e.preventDefault();
          setIsDragging(false);
          addFiles(e.dataTransfer.files);
        }}
      >
        <svg className="dropzone-border" preserveAspectRatio="none">
          <rect x="1" y="1" rx="19" ry="19" />
        </svg>
        <div className="upload-content">
          <div className="dropzone-icon">
            <UploadIcon width="22" height="22" strokeWidth="1.6" />
          </div>
          <div>
            <h3 className="card-title">{staffView ? "Add a staff-only file" : "Share a document"}</h3>
            <p className="card-subtitle" style={{ margin: 0 }}>
              {staffView
                ? `Drag and drop files here, or click to browse. Only MyGoodBooks staff can see them, never ${client.name}.`
                : "Drag and drop files here, or click to browse. Receipts, statements, or anything your bookkeeper should see."}
            </p>
          </div>
        </div>
        {isBookkeeper && (
          <div
            className="doc-drive-picker"
            onClick={(e) => e.stopPropagation()}
            style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}
          >
            {driveInfo.connected ? (
              <React.Fragment>
                <label className="tp-muted" style={{ fontSize: 12.5 }}>
                  Drive folder{" "}
                  <select
                    className="rb-select"
                    aria-label="Document type"
                    value={uploadDocType}
                    onChange={(e) => setUploadDocType(e.target.value)}
                    style={{ width: "auto" }}
                  >
                    {DRV_DOC_TYPES.map((t) => (
                      <option key={t} value={t}>{t}</option>
                    ))}
                  </select>
                </label>
                <select
                  className="rb-select"
                  aria-label="Year"
                  value={uploadYear}
                  onChange={(e) => setUploadYear(Number(e.target.value))}
                  style={{ width: "auto" }}
                >
                  {[0, 1, 2, 3].map((n) => DRV_currentYear() - n).map((y) => (
                    <option key={y} value={y}>{y}</option>
                  ))}
                </select>
              </React.Fragment>
            ) : driveInfo.connected === false ? (
              <span className="tp-muted" style={{ fontSize: 12.5 }}>
                {DRV_NOT_CONNECTED_MSG} Files are kept in the portal's own storage until then.
              </span>
            ) : null}
          </div>
        )}
        <button
          className="btn-primary"
          disabled={uploading}
          onClick={(e) => {
            e.stopPropagation();
            fileInputRef.current.click();
          }}
        >
          {uploading ? "Uploading…" : "Upload Document"}
        </button>
        <input
          ref={fileInputRef}
          type="file"
          multiple
          style={{ display: "none" }}
          onChange={(e) => {
            addFiles(e.target.files);
            e.target.value = "";
          }}
        />
      </div>
      )}

      <div className="card">
        <div className="page-header" style={{ marginBottom: 4 }}>
          <div>
            <h3 className="card-title">
              {activeFolder === null ? "All Documents" : staffView ? "Staff only" : trashView ? "Trash" : activeFolder}
            </h3>
            <p className="card-subtitle" style={{ margin: 0 }}>
              {visibleDocs.length} file{visibleDocs.length !== 1 ? "s" : ""} ·
              click a document to open it
              {remoteState === "loading" ? " · loading…" : ""}
            </p>
          </div>
          <div className="doc-tools" style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
            {isBookkeeper && driveInfo.connected && driveInfo.legacyCount > 0 && (
              <button
                type="button"
                className="btn-secondary btn-sm"
                disabled={copyingLegacy}
                onClick={copyLegacy}
                title="Copies the older files stored in the portal into Google Drive. The originals stay where they are."
              >
                {copyingLegacy ? "Copying…" : `Copy ${driveInfo.legacyCount} older file${driveInfo.legacyCount === 1 ? "" : "s"} to Drive`}
              </button>
            )}
            <input
              type="search"
              className="rb-select"
              placeholder="Search documents"
              aria-label="Search documents"
              value={docSearch}
              onChange={(e) => setDocSearch(e.target.value)}
              style={{ minWidth: 0, width: 200, maxWidth: "100%" }}
            />
            <select
              className="rb-select"
              aria-label="Sort documents"
              value={docSort}
              onChange={(e) => setDocSort(e.target.value)}
              style={{ width: "auto" }}
            >
              <option value="newest">Newest first</option>
              <option value="oldest">Oldest first</option>
              <option value="name">Name A–Z</option>
            </select>
          </div>
          {hasRestrictedDocs && (
            <div className="view-toggle">
              <button
                type="button"
                className={
                  "view-toggle-btn" + (visFilter === "all" ? " active" : "")
                }
                onClick={() => setVisFilter("all")}
              >
                All Documents
              </button>
              <button
                type="button"
                className={
                  "view-toggle-btn" + (visFilter === "full" ? " active" : "")
                }
                onClick={() => setVisFilter("full")}
              >
                Full Access Only
              </button>
            </div>
          )}
        </div>
        <div className="table-scroll">
          <table className="tx-table tx-table-labeled">
            <thead>
              <tr>
                <th>Name</th>
                <th>Category</th>
                <th>Uploaded By</th>
                <th>Date</th>
                <th>Folder</th>
                {isBookkeeper && <th>Visible To</th>}
                <th className="num">Size</th>
                {isBookkeeper && (
                  <th aria-label="Actions" />
                )}
              </tr>
            </thead>
            <tbody>
              {remoteState === "error" && (
                <EmptyRow colSpan={isBookkeeper ? 8 : 6}>
                  Some documents couldn't be loaded.{" "}
                  <button type="button" className="btn-secondary" onClick={loadRemoteDocs}>
                    Try again
                  </button>
                </EmptyRow>
              )}
              {visibleDocs.length === 0 && remoteState !== "loading" && (
                <EmptyRow colSpan={isBookkeeper ? 8 : 6}>
                  {docQuery
                    ? "No documents match that search."
                    : trashView
                      ? "Trash is empty."
                      : staffView
                      ? "No staff-only files yet. Upload one above, or drop a file anywhere and leave Visible to client off."
                      : activeFolder
                      ? "Nothing in this folder yet."
                      : "No documents yet. Upload one above, or your bookkeeper can share files here."}
                </EmptyRow>
              )}
              {visibleDocs.map((d) => {
                const i = docs.indexOf(d);
                const rowId = "doc-row-" + slugify(d.name);
                return (
                  <tr
                    key={d.key}
                    id={rowId}
                    className={
                      "doc-row" + (flashCardId === rowId ? " row-flash" : "")
                    }
                    onClick={() => openDoc(d, i)}
                    tabIndex={0}
                    onKeyDown={(e) => {
                      if (e.key === "Enter") openDoc(d, i);
                    }}
                  >
                    <td data-primary="">
                      <span className="doc-name-link">
                        <FileIcon
                          width="15"
                          height="15"
                          strokeWidth="1.7"
                          className="icon-inline"
                        />
                        {d.name}
                      </span>
                    </td>
                    <td data-label="Category">
                      <span
                        className={"category-tag" + (d.staffOnly ? " category-tag-staff" : "")}
                        title={d.staffOnly ? "Only MyGoodBooks staff can see this file" : undefined}
                      >
                        {d.category}
                      </span>
                    </td>
                    <td data-label="Uploaded by">{d.uploadedBy}</td>
                    <td data-label="Date">{fmtDate(d.date)}</td>
                    <td data-label="Folder">
                      {d.trashed ? (
                        d.folder || "Unfiled"
                      ) : (
                      <select
                        className="doc-folder-select"
                        value={d.folder || ""}
                        onClick={(e) => e.stopPropagation()}
                        onChange={(e) =>
                          e.target.value === NEW_FOLDER_OPTION
                            ? setNewFolderFor(i)
                            : moveDocToFolder(i, e.target.value)
                        }
                      >
                        <option value="">Unfiled</option>
                        {folders.map((name) => (
                          <option key={name} value={name}>
                            {name}
                          </option>
                        ))}
                        <option value={NEW_FOLDER_OPTION}>+ New folder…</option>
                      </select>
                      )}
                    </td>
                    {isBookkeeper && (
                      <td data-label="Visible to">
                        {/* Read-only: there's no stored visibility setting
                            yet, so a toggle here would only pretend. */}
                        <span
                          className={
                            "visibility-toggle" +
                            (d.visibility === "full" || d.staffOnly ? " restricted" : "")
                          }
                        >
                          {d.trashed ? (
                            "Staff only (in Trash)"
                          ) : d.staffOnly ? (
                            <React.Fragment>
                              <LockIcon /> Staff only
                            </React.Fragment>
                          ) : d.visibility === "full" ? (
                            <React.Fragment>
                              <LockIcon /> Full access only
                            </React.Fragment>
                          ) : (
                            "Everyone"
                          )}
                        </span>
                      </td>
                    )}
                    <td className="num" data-label="Size">
                      {d.size}
                    </td>
                    {isBookkeeper && (
                      <td className="doc-actions" data-label="">
                        {d.source === "sample" ? null : d.trashed ? (
                          <span className="doc-actions-row">
                          <button
                            type="button"
                            className="btn-secondary btn-sm"
                            disabled={!!trashBusy}
                            onClick={(e) => {
                              e.stopPropagation();
                              restoreDoc(d);
                            }}
                          >
                            {trashBusy === d.key ? "Working…" : "Restore"}
                          </button>
                          {d.source !== "drive" && (
                          <button
                            type="button"
                            className="btn-secondary btn-sm doc-delete-btn"
                            disabled={!!trashBusy}
                            onClick={(e) => {
                              e.stopPropagation();
                              setDeletePending(d);
                            }}
                          >
                            Delete forever
                          </button>
                          )}
                          </span>
                        ) : (
                          <span className="doc-actions-row">
                          {d.webViewLink && (
                            <a
                              className="btn-secondary btn-sm"
                              href={d.webViewLink}
                              target="_blank"
                              rel="noopener noreferrer"
                              title="Open in Google Drive (staff only)"
                              onClick={(e) => e.stopPropagation()}
                            >
                              Open in Drive
                            </a>
                          )}
                          <button
                            type="button"
                            className="doc-trash-btn"
                            disabled={!!trashBusy}
                            aria-label={`Move ${d.name} to Trash`}
                            title="Move to Trash"
                            onClick={(e) => {
                              e.stopPropagation();
                              trashDoc(d);
                            }}
                          >
                            <TrashIcon width="15" height="15" />
                          </button>
                          </span>
                        )}
                      </td>
                    )}
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {previewIndex !== null && docs[previewIndex] && (
        <DocumentPreviewModal
          doc={docs[previewIndex]}
          onClose={() => setPreviewIndex(null)}
        />
      )}

      {folderPendingDelete && (
        <ConfirmModal
          title={`Delete "${folderPendingDelete}"?`}
          body="Its documents move back to Unfiled. Nothing is deleted, and this changes the folder for everyone on this client's Documents page."
          confirmLabel="Delete folder"
          onConfirm={confirmRemoveFolder}
          onCancel={() => setFolderPendingDelete(null)}
        />
      )}

      {deletePending && (
        <ConfirmModal
          title={`Delete "${deletePending.name}" forever?`}
          body="This can't be undone. It's removed for good and no one, staff or client, can restore it."
          confirmLabel="Delete forever"
          onConfirm={deleteForever}
          onCancel={() => setDeletePending(null)}
        />
      )}

      {newFolderFor !== null && docs[newFolderFor] && (
        <DF_NewFolderModal
          docName={docs[newFolderFor].name}
          onCancel={() => setNewFolderFor(null)}
          onCreate={async (name) => {
            const err = await createFolder(name);
            if (err) return err;
            const index = newFolderFor;
            setNewFolderFor(null);
            await moveDocToFolder(index, name);
            return null;
          }}
        />
      )}
    </div>
  );
}

// File extensions we know how to render inline. Anything else — real upload
// or sample document alike — falls back to the metadata-only preview panel
// rather than guessing at a MIME type from the extension.
const PREVIEWABLE_IMAGE_EXT = /\.(png|jpe?g|gif|webp|svg)$/i;
const PREVIEWABLE_PDF_EXT = /\.pdf$/i;

function docExtension(name) {
  const match = /\.([a-z0-9]+)$/i.exec(name || "");
  return match ? match[1].toUpperCase() : "FILE";
}

function DocumentPreviewModal({ doc, onClose }) {
  const objectUrl = useMemo(
    () => (doc.file ? URL.createObjectURL(doc.file) : null),
    [doc.file],
  );
  useEffect(
    () => () => {
      if (objectUrl) URL.revokeObjectURL(objectUrl);
    },
    [objectUrl],
  );

  const isImage = PREVIEWABLE_IMAGE_EXT.test(doc.name);
  const isPdf = PREVIEWABLE_PDF_EXT.test(doc.name);

  return (
    <ModalShell
      onClose={onClose}
      labelledBy="doc-preview-title"
      className="doc-preview-modal"
    >
      <div className="modal-header">
        <h3 className="card-title" id="doc-preview-title" style={{ margin: 0 }}>
          <FileIcon
            width="17"
            height="17"
            strokeWidth="1.7"
            className="icon-inline"
          />
          {doc.name}
        </h3>
        <button className="modal-close" onClick={onClose} aria-label="Close">
          ×
        </button>
      </div>

      <div className="modal-body doc-preview-body">
        {objectUrl && isImage && (
          <img src={objectUrl} alt={doc.name} className="doc-preview-image" />
        )}
        {objectUrl && isPdf && (
          <iframe
            src={objectUrl}
            title={doc.name}
            className="doc-preview-frame"
          />
        )}
        {!objectUrl && (
          <div className="doc-preview-placeholder">
            <FileIcon width="40" height="40" strokeWidth="1.3" />
            <p
              className="card-subtitle"
              style={{ margin: "10px 0 0", textAlign: "center" }}
            >
              {doc.file
                ? `Preview isn't available for .${docExtension(doc.name).toLowerCase()} files yet — download to open it.`
                : "This is sample data — there's no real file behind it to preview yet."}
            </p>
          </div>
        )}
        {objectUrl && !isImage && !isPdf && (
          <div className="doc-preview-placeholder">
            <FileIcon width="40" height="40" strokeWidth="1.3" />
            <p
              className="card-subtitle"
              style={{ margin: "10px 0 0", textAlign: "center" }}
            >
              Preview isn't available for .
              {docExtension(doc.name).toLowerCase()} files yet — download to
              open it.
            </p>
          </div>
        )}
      </div>

      <div className="modal-footer doc-preview-footer">
        <div className="doc-preview-meta">
          <span className="category-tag">{doc.category}</span>
          <span>{doc.uploadedBy}</span>
          <span>{fmtDate(doc.date)}</span>
          <span>{doc.size}</span>
        </div>
        <div className="doc-preview-actions">
          {objectUrl && (
            <a className="btn-secondary" href={objectUrl} download={doc.name}>
              Download
            </a>
          )}
          <button className="btn-primary" onClick={onClose}>
            Close
          </button>
        </div>
      </div>
    </ModalShell>
  );
}

// ----------------------------------------------------------------------------
// Floating "you have unread messages" indicator — a plain round tap target
// that jumps straight to the real Messages page, used on every screen size.
// A fixed-position floating mini-thread (this used to be desktop-only,
// `ChatWidget`) fought the on-screen keyboard on mobile, but it wasn't much
// better on desktop either — a 3-message preview isn't very useful when the
// real Messages page is one click away regardless, so this is now the only
// form the unread indicator takes anywhere.
// ----------------------------------------------------------------------------

function ChatFab({ unreadCount, onOpen, onDismiss }) {
  return (
    <div className="chat-fab-wrap">
      <button className="chat-fab" onClick={onOpen} aria-label="Open messages">
        <ChatIcon width="22" height="22" strokeWidth="1.6" />
        {unreadCount > 0 && (
          <span className="chat-fab-badge">{unreadCount}</span>
        )}
      </button>
      <button
        className="chat-fab-dismiss"
        onClick={onDismiss}
        aria-label="Dismiss"
      >
        ×
      </button>
    </div>
  );
}

// ----------------------------------------------------------------------------
// Messages page
// ----------------------------------------------------------------------------

// Stands in for SI_useClientMessaging when the inbox component isn't loaded:
// a signed-in client then sees "Messaging isn't available right now".
const MSG_OFF = {
  status: "off",
  messages: [],
  unread: false,
  waitingCount: 0,
  readOnly: true,
  hasMore: false,
  lastId: null,
  lastText: "",
  retry: () => {},
  markRead: () => {},
  loadEarlier: async () => null,
  send: () => "Messaging isn't available right now.",
};

// Consecutive messages from one sender within this gap share a group (one
// author line, tighter spacing).
const MSG_GROUP_GAP_MS = 10 * 60 * 1000;
// Within this many pixels of the bottom counts as "reading the latest", so a
// new message scrolls into view; further up, a "New message" pill shows.
const MSG_NEAR_BOTTOM_PX = 80;
// Signed attachment links last 10 minutes; past this, re-sign on click.
const MSG_LINK_STALE_MS = 9 * 60 * 1000;

// A message's moment: created_at for real rows, noon on its date for the
// sample rows (which only have a YYYY-MM-DD date).
function MSG_when(m) {
  const d = new Date(m.created_at || (m.date ? `${m.date}T12:00:00` : NaN));
  return isFinite(d.getTime()) ? d : null;
}

const MSG_dayKey = (d) => (d ? `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}` : "");

// Today, Yesterday, then "Mon, Sep 29" (with the year once it isn't this one).
function MSG_dayLabel(d) {
  const now = new Date();
  const yest = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1);
  if (MSG_dayKey(d) === MSG_dayKey(now)) return "Today";
  if (MSG_dayKey(d) === MSG_dayKey(yest)) return "Yesterday";
  return d.toLocaleDateString("en-US", {
    weekday: "short",
    month: "short",
    day: "numeric",
    ...(d.getFullYear() !== now.getFullYear() ? { year: "numeric" } : {}),
  });
}

const MSG_time = (d) => d.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" });

function MessagesPage({
  client,
  messages,
  onSend,
  users,
  activeUserId,
  onSelectUser,
  unreadUserIds,
  isBookkeeper,
  searchTarget,
  bookkeeperTyping,
  // Real messaging (client_messages, see SI_useClientMessaging): no sample
  // banner, attachments are checked and uploaded, and onSend returns an
  // error message or null (the message then shows at once with a "Sending…"
  // state). readOnlyNote: staff previewing a real thread.
  live,
  validateAttachment,
  readOnlyNote,
  // Real threads only: "loading" | "error" | "real" | "unavailable" (no
  // messaging for this signed-in client), a retry for the error state, and
  // the "Load earlier messages" pager (resolves to an error or null).
  loadStatus = "real",
  onRetry,
  hasEarlier,
  onLoadEarlier,
  loadingEarlier,
  // Real threads only: the reader's own read marker as it was when the page
  // opened (for the "New messages" divider), the latest staff read marker
  // (for "Seen"), failed-send handlers and a fresh-link getter for
  // attachments whose signed URL has expired.
  readAt,
  staffReadAt,
  onRetrySend,
  onDiscardSend,
  onAttachmentUrl,
  // Real threads, the signed-in client only: delete one of their own
  // messages within 24 hours (resolves to an error message or null). It
  // then disappears for everyone.
  onDeleteMessage,
}) {
  const [draft, setDraft] = useState("");
  const [confirmDeleteId, setConfirmDeleteId] = useState(null);
  const [pendingAttachment, setPendingAttachment] = useState(null);
  const [isDragging, setIsDragging] = useState(false);
  const [sending, setSending] = useState(false);
  const [showNewPill, setShowNewPill] = useState(false);
  const fileInputRef = useRef(null);
  const threadRef = useRef(null);
  const draftRef = useRef(null);
  const nearBottomRef = useRef(true);
  const openedRef = useRef(false);
  const prependRef = useRef(null);
  const lastPendingRef = useRef(null);
  const { flashCardId, jumpToCard } = useCardFlash();
  const showToast = useToast();
  const unavailable = loadStatus === "unavailable";

  // Who wrote each staff reply: name and title from their public profile
  // (client_team_profiles, Settings.jsx AM_useTeamProfiles), falling back to
  // the name saved on the message.
  const staffAuthorEmails = live
    ? Array.from(new Set(messages.filter((m) => m.from === "bookkeeper" && m.authorEmail).map((m) => String(m.authorEmail).toLowerCase())))
    : [];
  const team =
    typeof AM_useTeamProfiles === "function"
      ? AM_useTeamProfiles(live && client ? client.id : null, staffAuthorEmails)
      : { byEmail: {} };
  const staffAuthor = (m) => {
    if (!live) return { name: client && client.assignedBookkeeper ? client.assignedBookkeeper.name : m.author, title: null };
    const p = m.authorEmail ? team.byEmail[String(m.authorEmail).toLowerCase()] : null;
    // No title on their profile yet: say what they are to this client.
    const role = p && (p.is_account_manager ? "Account manager" : p.is_bookkeeper ? "Bookkeeper" : null);
    return { name: (p && p.name) || m.author || "MyGoodBooks", title: (p && p.title) || role || null };
  };

  // Where unread starts: the first staff message after the reader's own
  // read marker, worked out once when the thread first loads, before the
  // page marks it read, so the divider stays put while they read.
  const newFromRef = useRef(undefined);
  if (newFromRef.current === undefined && live && loadStatus === "real") {
    const first = readAt
      ? messages.find((m) => m.from === "bookkeeper" && m.created_at && new Date(m.created_at) > new Date(readAt))
      : null;
    newFromRef.current = first ? first.id : null;
  }
  const newFromId = newFromRef.current || null;

  const lastMsg = messages.length ? messages[messages.length - 1] : null;
  // Unsent messages stay at the bottom, so a reply that arrives while one is
  // sending lands above it: watch the last sent message as well.
  const lastSent = [...messages].reverse().find((m) => !m.sendState);
  const msgKey = (m) => (m ? m.id || m.created_at || "" : "");
  const lastMsgKey = messages.length ? msgKey(lastMsg) + "|" + msgKey(lastSent) + "|" + messages.length : null;
  const firstMsgKey = messages.length ? messages[0].id || messages[0].created_at || "first" : null;

  const scrollToBottom = (smooth) => {
    const el = threadRef.current;
    if (!el) return;
    el.scrollTo({ top: el.scrollHeight, behavior: smooth ? "smooth" : "auto" });
    nearBottomRef.current = true;
    setShowNewPill(false);
  };

  // First load: open at the "New messages" divider if there is one, else at
  // the newest message. After that a new message only scrolls the thread if
  // the reader is already at the bottom (or sent it); otherwise the pill.
  React.useLayoutEffect(() => {
    const el = threadRef.current;
    if (!el || searchTarget || !messages.length) return;
    if (!openedRef.current) {
      openedRef.current = true;
      const divider = el.querySelector(".msg-new-divider");
      if (divider) el.scrollTop = Math.max(0, divider.offsetTop - 12);
      else el.scrollTop = el.scrollHeight;
      nearBottomRef.current = el.scrollHeight - el.scrollTop - el.clientHeight < MSG_NEAR_BOTTOM_PX;
      return;
    }
    const mineJustAdded = lastMsg && lastMsg.sendState === "sending" && lastMsg.id !== lastPendingRef.current;
    lastPendingRef.current = lastMsg && lastMsg.sendState ? lastMsg.id : null;
    if (nearBottomRef.current || mineJustAdded) scrollToBottom(false);
    else if (lastSent && lastSent.from === "bookkeeper") setShowNewPill(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [lastMsgKey, loadStatus]);

  // "Load earlier" adds rows above: keep the reader's place by holding the
  // distance from the bottom steady.
  React.useLayoutEffect(() => {
    const el = threadRef.current;
    const p = prependRef.current;
    if (!el || !p) return;
    if (firstMsgKey !== p.firstKey) el.scrollTop = el.scrollHeight - p.fromBottom;
    if (!loadingEarlier) prependRef.current = null;
  }, [firstMsgKey, loadingEarlier]);

  const loadEarlier = async () => {
    const el = threadRef.current;
    if (el) prependRef.current = { fromBottom: el.scrollHeight - el.scrollTop, firstKey: firstMsgKey };
    const err = await onLoadEarlier();
    if (err) showToast(err);
  };

  const onThreadScroll = () => {
    const el = threadRef.current;
    if (!el) return;
    const near = el.scrollHeight - el.scrollTop - el.clientHeight < MSG_NEAR_BOTTOM_PX;
    nearBottomRef.current = near;
    if (near && showNewPill) setShowNewPill(false);
  };

  // The compose box grows with its text up to about six lines.
  useEffect(() => {
    const el = draftRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = Math.min(el.scrollHeight, 160) + "px";
    el.style.overflowY = el.scrollHeight > 160 ? "auto" : "hidden";
  }, [draft]);

  // Search only ever looks within the currently-open thread (see
  // GlobalSearch), so there's no other person's conversation to switch to
  // first — just scroll to and flash the matching bubble.
  useEffect(() => {
    if (searchTarget)
      jumpToCard(searchTarget.highlightKey, searchTarget.highlightKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchTarget && searchTarget.nonce]);

  const stageFile = (file) => {
    if (!file) return;
    const err = validateAttachment ? validateAttachment(file) : null;
    if (err) {
      showToast(err);
      return;
    }
    setPendingAttachment({ file, name: file.name, size: formatBytes(file.size) });
  };

  const canSend =
    (draft.trim() || pendingAttachment) && !sending && !readOnlyNote && !unavailable && loadStatus !== "loading";

  const send = async () => {
    if (!canSend) return;
    let res = onSend(draft.trim(), pendingAttachment || undefined);
    if (res && typeof res.then === "function") {
      setSending(true);
      res = await res;
      setSending(false);
    }
    // A message back means nothing was sent: keep the draft.
    if (typeof res === "string" && res) {
      showToast(res);
      return;
    }
    setDraft("");
    setPendingAttachment(null);
    draftRef.current && draftRef.current.focus();
  };

  // Puts a failed message back in the compose box (keeping anything already
  // typed there) and takes it out of the thread.
  const editFailed = (id) => {
    const back = onDiscardSend && onDiscardSend(id);
    if (!back) return;
    if (back.text) setDraft((d) => (d.trim() ? `${back.text}\n${d}` : back.text));
    if (back.file && !pendingAttachment)
      setPendingAttachment({ file: back.file, name: back.file.name, size: back.size || formatBytes(back.file.size) });
    draftRef.current && draftRef.current.focus();
  };

  // A signed link older than ~9 minutes has expired: open a tab right away
  // (so it isn't blocked as a popup), then point it at a fresh link.
  const openAttachment = async (e, m) => {
    const a = m.attachment;
    if (!onAttachmentUrl || (a.url && a.signedAt && Date.now() - a.signedAt < MSG_LINK_STALE_MS)) return;
    e.preventDefault();
    const w = window.open("about:blank", "_blank");
    const url = safeHttpUrl(await onAttachmentUrl(m.id));
    if (w) {
      if (url) {
        w.opener = null;
        w.location.href = url;
      } else w.close();
    }
    if (!url) showToast(`Couldn't open ${a.name}. Try again in a moment.`);
  };

  const activeUser = (users || []).find((u) => u.id === activeUserId);

  // "Seen" sits under the reader's latest sent message once a staff read
  // marker is at or after it.
  let seenId = null;
  if (live && staffReadAt) {
    const lastOwn = [...messages].reverse().find((m) => m.from === "client" && !m.sendState);
    if (lastOwn && lastOwn.created_at && new Date(staffReadAt) >= new Date(lastOwn.created_at)) seenId = lastOwn.id;
  }

  // Day dividers, the "New messages" divider, and sender groups.
  const items = [];
  let prevDay = null;
  let prev = null;
  messages.forEach((m, i) => {
    const when = MSG_when(m);
    const day = MSG_dayKey(when);
    if (day && day !== prevDay) {
      items.push({ kind: "day", key: "day-" + day, label: MSG_dayLabel(when) });
      prevDay = day;
      prev = null;
    }
    if (newFromId && m.id === newFromId) {
      items.push({ kind: "new", key: "new" });
      prev = null;
    }
    const prevWhen = prev && MSG_when(prev);
    const grouped = !!(
      prev &&
      prev.from === m.from &&
      prev.author === m.author &&
      (!when || !prevWhen || when - prevWhen < MSG_GROUP_GAP_MS)
    );
    items.push({ kind: "msg", key: m.id || "i" + i, m, i, when, grouped });
    prev = m;
  });

  // The client's thread is with the whole team: name the account manager
  // (main contact) and the bookkeeper under the title.
  const amPerson = client && client.accountManager;
  const bkPerson = client && client.assignedBookkeeper;
  const teamLine =
    live && !isBookkeeper && amPerson
      ? [
          `${amPerson.name}, account manager`,
          bkPerson && bkPerson.name && String(bkPerson.email || "").toLowerCase() !== amPerson.email
            ? `${bkPerson.name}, bookkeeper`
            : null,
        ]
          .filter(Boolean)
          .join(" · ")
      : null;
  const threadTitle =
    isBookkeeper && activeUser
      ? `Conversation with ${activeUser.name}`
      : teamLine
        ? "Conversation with your MyGoodBooks team"
        : client && client.assignedBookkeeper
        ? // §161: the green "Online now" dot that used to sit here was
          // hardcoded — nothing checked presence, so it told every client
          // their bookkeeper was at their desk at 3am on a Sunday. The
          // staff-side thread list (see .online-dot above) drives the same
          // indicator off a real `onlineEmails` set; this side has no such
          // signal, so it shows nothing rather than a false one.
          `Conversation with ${client.assignedBookkeeper.name}`
        : "Conversation with MyGoodBooks";

  return (
    <div className="msg-page">
      {!live && (
        <MockBanner text="This is a sample conversation — sending a message here doesn't notify anyone yet." />
      )}

      {/* Each person has a private thread, so in bookkeeper view MyGoodBooks
          picks whose conversation to open. Clients never see this. */}
      {isBookkeeper && users && users.length > 0 && (
        <div className="thread-picker">
          <span className="thread-picker-label">Conversation with</span>
          <div className="thread-picker-tabs">
            {users.map((u) => (
              <button
                key={u.id}
                className={
                  "thread-tab" + (u.id === activeUserId ? " active" : "")
                }
                onClick={() => onSelectUser(u.id)}
              >
                <span className="thread-tab-name">{u.name}</span>
                <span className="thread-tab-role">{u.role}</span>
                {(unreadUserIds || []).includes(u.id) && (
                  <span className="thread-tab-dot" />
                )}
              </button>
            ))}
          </div>
        </div>
      )}

      <div
        className={
          "card message-card msg-page-card" + (unavailable ? " msg-page-card--off" : "") + (isDragging ? " dragging" : "")
        }
        onDragOver={(e) => {
          if (unavailable || readOnlyNote) return;
          e.preventDefault();
          setIsDragging(true);
        }}
        onDragLeave={() => setIsDragging(false)}
        onDrop={(e) => {
          e.preventDefault();
          setIsDragging(false);
          stageFile(e.dataTransfer.files && e.dataTransfer.files[0]);
        }}
      >
        <h3 className="card-title">{threadTitle}</h3>
        {teamLine && <p className="card-subtitle msg-team-sub">{teamLine}</p>}
        {unavailable ? (
          <div className="msg-unavailable" role="status">
            <strong>Messaging isn't available right now.</strong>
            <span>
              Please try again later. If you need us sooner, email your bookkeeper directly.
            </span>
          </div>
        ) : loadStatus === "loading" && messages.length === 0 ? (
          <p className="card-subtitle" role="status">Loading your conversation…</p>
        ) : loadStatus === "error" ? (
          <div className="message-load-error" role="alert">
            <span>Couldn't load your messages. Check your connection and try again.</span>
            {onRetry && (
              <button type="button" className="btn-secondary" onClick={onRetry}>
                Try again
              </button>
            )}
          </div>
        ) : (
          messages.length === 0 && (
            <p className="card-subtitle">No messages yet. Say hello, or ask us anything about your books.</p>
          )
        )}
        {!unavailable && (
        <div className="msg-thread-wrap">
          <div
            className="message-thread msg-thread"
            ref={threadRef}
            onScroll={onThreadScroll}
            role="log"
            aria-live="polite"
            aria-label="Messages"
            aria-busy={loadStatus === "loading" || !!loadingEarlier}
          >
            {hasEarlier && onLoadEarlier && (
              <button
                type="button"
                className="btn-secondary message-load-earlier"
                onClick={loadEarlier}
                disabled={!!loadingEarlier}
              >
                {loadingEarlier ? "Loading…" : "Load earlier messages"}
              </button>
            )}
            {items.map((it) => {
              if (it.kind === "day")
                return (
                  <div className="msg-divider" key={it.key} role="separator">
                    <span>{it.label}</span>
                  </div>
                );
              if (it.kind === "new")
                return (
                  <div className="msg-divider msg-new-divider" key={it.key} role="separator">
                    <span>New messages</span>
                  </div>
                );
              const { m, i, when, grouped } = it;
              // Stable per message (search results carry the same key), so a
              // flash target survives "Load earlier" adding rows above.
              const rowId = "msg-" + (m.id || i);
              const failed = m.sendState === "failed";
              const attachUrl = m.attachment && safeHttpUrl(m.attachment.url);
              // Sample rows have only a date, which the day divider shows.
              const stamp =
                m.sendState === "sending"
                  ? "Sending…"
                  : failed
                    ? "Not sent"
                    : m.created_at && when
                      ? MSG_time(when)
                      : null;
              return (
                <div
                  className={
                    "message-bubble-row " +
                    m.from +
                    (grouped ? " msg-grouped" : "") +
                    (m.sendState ? " msg-" + m.sendState : "")
                  }
                  id={rowId}
                  key={it.key}
                >
                  <div
                    className={
                      "message-bubble" +
                      (flashCardId === rowId ? " row-flash" : "")
                    }
                  >
                    {!grouped &&
                      (m.from === "bookkeeper" ? (
                        (() => {
                          const a = staffAuthor(m);
                          return (
                            <div className="message-author">
                              {a.name}
                              {a.title && <span className="msg-author-title"> · {a.title}</span>}
                            </div>
                          );
                        })()
                      ) : (
                        <div className="message-author">{m.author}</div>
                      ))}
                    {m.text && <div className="message-text">{m.text}</div>}
                    {m.attachment &&
                      (attachUrl || (onAttachmentUrl && !m.sendState) ? (
                        <a
                          className="message-attachment"
                          href={attachUrl || "#"}
                          target="_blank"
                          rel="noreferrer"
                          onClick={(e) => openAttachment(e, m)}
                        >
                          <PaperclipIcon /> {m.attachment.name}
                        </a>
                      ) : (
                        <div className="message-attachment">
                          <PaperclipIcon /> {m.attachment.name}{" "}
                          {m.attachment.size && (
                            <span className="message-attachment-size">
                              ({m.attachment.size})
                            </span>
                          )}
                        </div>
                      ))}
                    {stamp && <div className="message-date">{stamp}</div>}
                  </div>
                  {failed && (
                    <div className="msg-send-failed" role="alert">
                      <span>{m.sendError || "Couldn't send this message."}</span>
                      {onRetrySend && (
                        <button type="button" className="link-btn" onClick={() => onRetrySend(m.id)}>
                          Retry
                        </button>
                      )}
                      {onDiscardSend && (
                        <button type="button" className="link-btn" onClick={() => editFailed(m.id)}>
                          Edit
                        </button>
                      )}
                    </div>
                  )}
                  {onDeleteMessage && m.from === "client" && m.id && !m.sendState && msgCanDelete(m.created_at) && (
                    <div className="message-own-actions msg-own-actions">
                      {confirmDeleteId === m.id ? (
                        <React.Fragment>
                          <span className="message-confirm-label">Delete this message?</span>
                          <button
                            type="button"
                            onClick={async () => {
                              setConfirmDeleteId(null);
                              const err = await onDeleteMessage(m.id);
                              if (err) showToast(err);
                            }}
                          >
                            Delete
                          </button>
                          <button type="button" onClick={() => setConfirmDeleteId(null)}>
                            Cancel
                          </button>
                        </React.Fragment>
                      ) : (
                        <button type="button" onClick={() => setConfirmDeleteId(m.id)}>
                          Delete
                        </button>
                      )}
                    </div>
                  )}
                  {seenId && m.id === seenId && <div className="msg-seen">Seen</div>}
                </div>
              );
            })}
          </div>
          {showNewPill && (
            <button type="button" className="msg-new-pill" onClick={() => scrollToBottom(true)}>
              New message ↓
            </button>
          )}
        </div>
        )}

        {pendingAttachment && (
          <div className="attachment-chip">
            <span>
              <PaperclipIcon /> {pendingAttachment.name}
            </span>
            <span className="attachment-chip-meta">
              {pendingAttachment.size}
            </span>
            <button
              className="attachment-remove"
              onClick={() => setPendingAttachment(null)}
              aria-label="Remove attachment"
            >
              ×
            </button>
          </div>
        )}

        {/* Sample threads only: their simulated reply "types" for a moment.
            Real threads have no typing signal, so nothing is shown there. */}
        {!live && !isBookkeeper && bookkeeperTyping && client && client.assignedBookkeeper && (
          <div className="typing-indicator">{`${client.assignedBookkeeper.name} is typing…`}</div>
        )}
        {unavailable ? null : readOnlyNote ? (
          <p className="card-subtitle">{readOnlyNote}</p>
        ) : (
        <div className="message-compose">
          <button
            type="button"
            className="attach-btn"
            onClick={() => fileInputRef.current.click()}
            aria-label="Attach file"
          >
            <PaperclipIcon />
          </button>
          <input
            ref={fileInputRef}
            type="file"
            style={{ display: "none" }}
            onChange={(e) => {
              stageFile(e.target.files && e.target.files[0]);
              e.target.value = "";
            }}
          />
          {/* Enter sends; Shift+Enter starts a new line. */}
          <textarea
            ref={draftRef}
            rows={1}
            placeholder="Type a message…"
            aria-label="Message"
            title="Enter to send, Shift+Enter for a new line"
            value={draft}
            onChange={(e) => setDraft(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && !e.shiftKey && !e.nativeEvent.isComposing) {
                e.preventDefault();
                send();
              }
            }}
          />
          <button className="btn-primary" onClick={send} disabled={!canSend}>
            {sending ? "Sending…" : "Send"}
          </button>
        </div>
        )}

        {isDragging && (
          <div className="message-drop-overlay">Drop file to attach</div>
        )}
      </div>
    </div>
  );
}

// ----------------------------------------------------------------------------
// Access Request Form — public, no login (see supabase/access-requests.sql).
// A client's admin uses this to specify exactly what each of their staff
// should see, without needing a MyGoodBooks account of their own. Reached by
// its own query param (see the ReactDOM.createRoot call at the bottom of
// this file), entirely outside AuthGate/App. A bookkeeper reads the
// submission back in Manage Access -> Requests and applies it by hand — see
// that SQL file's header for why this doesn't auto-apply.
// ----------------------------------------------------------------------------

function emptyAccessRequestPerson() {
  return {
    name: "",
    email: "",
    role: "",
    access: "full",
    tabs: [],
    categories: [],
  };
}

function AccessRequestForm({ token }) {
  const supabase = window.mgbSupabase;
  // "loading" | "invalid" | "ready" | "submitting" | "done"
  const [status, setStatus] = useState("loading");
  const [client, setClient] = useState(null);
  const [submitterName, setSubmitterName] = useState("");
  const [submitterEmail, setSubmitterEmail] = useState("");
  const [people, setPeople] = useState([emptyAccessRequestPerson()]);
  const [errorMsg, setErrorMsg] = useState("");

  useEffect(() => {
    if (!supabase) {
      setErrorMsg("This portal isn't configured yet.");
      setStatus("invalid");
      return;
    }
    // Security audit finding H2: the table's blanket select policy is gone
    // (it let anon dump every link, client id, staff email and live token).
    // A security definer RPC now resolves a single token to a single
    // client_id, returning null for anything invalid/inactive.
    supabase
      .rpc("access_link_client", { p_token: token })
      .then(({ data: clientId, error }) => {
        if (error || !clientId) {
          setStatus("invalid");
          return;
        }
        const c = CLIENTS.find((c) => c.id === clientId);
        if (!c) {
          setStatus("invalid");
          return;
        }
        setClient(c);
        setStatus("ready");
      });
  }, [token, supabase]);

  const requestableTabs = NAV_SECTIONS.flatMap((s) => s.items).filter(
    (i) => i.key !== ALWAYS_VISIBLE_KEY,
  );

  function updatePerson(i, patch) {
    setPeople((prev) =>
      prev.map((p, idx) => (idx === i ? { ...p, ...patch } : p)),
    );
  }
  function toggleTab(i, key) {
    setPeople((prev) =>
      prev.map((p, idx) => {
        if (idx !== i) return p;
        const set = new Set(p.tabs);
        if (set.has(key)) set.delete(key);
        else set.add(key);
        return { ...p, tabs: Array.from(set) };
      }),
    );
  }
  function toggleCategory(i, cat) {
    setPeople((prev) =>
      prev.map((p, idx) => {
        if (idx !== i) return p;
        const set = new Set(p.categories);
        if (set.has(cat)) set.delete(cat);
        else set.add(cat);
        return { ...p, categories: Array.from(set) };
      }),
    );
  }

  async function submit() {
    setStatus("submitting");
    // Rate limiting (security audit finding H3): the direct insert() path is
    // gone. This RPC is security definer and checks + inserts atomically, so
    // a script looping against a leaked/guessed token can't out-race the cap.
    const { error } = await supabase.rpc("submit_access_request", {
      p_token: token,
      p_client_id: client.id,
      p_submitted_by_name: submitterName.trim(),
      p_submitted_by_email: submitterEmail.trim(),
      p_people: people.map((p) => ({
        name: p.name.trim(),
        email: p.email.trim(),
        role: p.role.trim(),
        access: p.access,
        tabs: p.access === "full" ? null : p.tabs,
        categories: p.access === "full" ? null : p.categories,
      })),
    });
    if (error) {
      setErrorMsg(
        error.message && error.message.includes("submission_cap_reached")
          ? "This link has already been used to submit a request. Contact your bookkeeper if you need to submit another."
          : "Couldn't submit — " + error.message,
      );
      setStatus("ready");
      return;
    }
    setStatus("done");
  }

  const canSubmit =
    submitterName.trim() &&
    submitterEmail.trim() &&
    people.length > 0 &&
    people.every((p) => p.name.trim() && p.email.trim() && p.role.trim());

  if (status === "loading") {
    return (
      <div className="boot-splash" role="status" aria-live="polite">
        <div className="boot-splash-mark">MyGoodBooks</div>
        <div className="boot-splash-sub">Loading the access form…</div>
      </div>
    );
  }

  if (status === "invalid") {
    return (
      <div className="boot-splash" role="alert">
        <div className="boot-splash-mark">MyGoodBooks</div>
        <div className="boot-splash-sub">
          {errorMsg ||
            "This form link isn't active anymore. Ask your bookkeeper for a new one."}
        </div>
      </div>
    );
  }

  if (status === "done") {
    return (
      <div className="boot-splash" role="status">
        <div className="boot-splash-mark">MyGoodBooks</div>
        <div className="boot-splash-sub">
          Thanks — we've received your access request for {client.name}. Your
          bookkeeper will set this up and follow up if anything's unclear.
        </div>
      </div>
    );
  }

  return (
    <div className="access-form-page">
      <div className="access-form-header">
        <span className="access-form-brand">MyGoodBooks</span>
        <span className="access-form-title">
          Staff Access Request — {client.name}
        </span>
      </div>
      <div className="access-form-body">
        <div className="card">
          <h3 className="card-title">Your info</h3>
          <p className="card-subtitle">
            Who's filling this out, in case we have questions.
          </p>
          <div className="access-form-row">
            <input
              type="text"
              placeholder="Your name"
              value={submitterName}
              onChange={(e) => setSubmitterName(e.target.value)}
            />
            <input
              type="email"
              placeholder="Your email"
              value={submitterEmail}
              onChange={(e) => setSubmitterEmail(e.target.value)}
            />
          </div>
        </div>

        {people.map((p, i) => (
          <div className="card" key={i}>
            <div className="access-form-person-header">
              <h3 className="card-title">Person {i + 1}</h3>
              {people.length > 1 && (
                <button
                  type="button"
                  className="btn-secondary"
                  onClick={() =>
                    setPeople((prev) => prev.filter((_, idx) => idx !== i))
                  }
                >
                  Remove
                </button>
              )}
            </div>
            <div className="access-form-row">
              <input
                type="text"
                placeholder="Full name"
                value={p.name}
                onChange={(e) => updatePerson(i, { name: e.target.value })}
              />
              <input
                type="email"
                placeholder="Email"
                value={p.email}
                onChange={(e) => updatePerson(i, { email: e.target.value })}
              />
              <input
                type="text"
                placeholder="Role (e.g. Board Treasurer)"
                value={p.role}
                onChange={(e) => updatePerson(i, { role: e.target.value })}
              />
            </div>

            <div className="access-level-toggle" style={{ marginTop: 14 }}>
              <button
                type="button"
                className={
                  "access-level-btn" + (p.access === "full" ? " active" : "")
                }
                onClick={() => updatePerson(i, { access: "full" })}
              >
                Full access
                <span>Sees all of {client.name}'s finances</span>
              </button>
              <button
                type="button"
                className={
                  "access-level-btn" + (p.access !== "full" ? " active" : "")
                }
                onClick={() => updatePerson(i, { access: "scoped" })}
              >
                Limited access
                <span>Only the areas you choose below</span>
              </button>
            </div>

            {p.access !== "full" && (
              <div className="modal-body" style={{ padding: "16px 0 0" }}>
                <div className="modal-section">
                  <div className="nav-section-label modal-section-label">
                    Pages they should see
                  </div>
                  {requestableTabs.map((item) => (
                    <label className="tab-toggle-row" key={item.key}>
                      <input
                        type="checkbox"
                        checked={p.tabs.includes(item.key)}
                        onChange={() => toggleTab(i, item.key)}
                      />
                      <span>{item.label}</span>
                    </label>
                  ))}
                </div>
                <div className="modal-section">
                  <div className="nav-section-label modal-section-label">
                    Budget areas they should see
                  </div>
                  <p
                    className="card-subtitle"
                    style={{ marginTop: 0, marginBottom: 8 }}
                  >
                    Leave all unchecked to give them every category.
                  </p>
                  {(client.budget || []).map((b) => (
                    <label className="tab-toggle-row" key={b.category}>
                      <input
                        type="checkbox"
                        checked={p.categories.includes(b.category)}
                        onChange={() => toggleCategory(i, b.category)}
                      />
                      <span>{b.category}</span>
                    </label>
                  ))}
                </div>
              </div>
            )}
          </div>
        ))}

        <button
          type="button"
          className="btn-secondary"
          onClick={() =>
            setPeople((prev) => [...prev, emptyAccessRequestPerson()])
          }
        >
          + Add another person
        </button>

        {errorMsg && (
          <p className="card-subtitle" style={{ color: "var(--bad)" }}>
            {errorMsg}
          </p>
        )}

        <button
          type="button"
          className="btn-primary access-form-submit"
          disabled={!canSubmit || status === "submitting"}
          onClick={submit}
        >
          {status === "submitting" ? "Submitting…" : "Submit access request"}
        </button>
      </div>
    </div>
  );
}

// ----------------------------------------------------------------------------
// Access management (bookkeeper-side only). Two levels: which tabs the whole
// organization gets, and what each named person at that org may see.
// ----------------------------------------------------------------------------

function UserAccessEditor({
  client,
  user,
  orgAllowedKeys,
  userAccess,
  onToggleUserTab,
  onToggleUserCategory,
  onToggleUserFund,
  onSetAccessLevel,
  onToggleUserPremium,
  onBack,
}) {
  const isFull = user.access === "full";
  const effective = userAccess[user.id] || {};
  const userTabs = new Set(effective.tabs || user.tabs || orgAllowedKeys);
  const userCats = new Set(effective.categories || user.categories || []);
  const isCategoryScoped = Boolean(effective.categories || user.categories);
  const userFunds = new Set(effective.funds || user.funds || []);
  const isPremiumClient = hasPremiumPlan(client);
  const premiumThrottled =
    "premiumThrottled" in effective
      ? effective.premiumThrottled
      : Boolean(user.premiumThrottled);

  return (
    <React.Fragment>
      <div className="modal-header">
        <button
          className="modal-back"
          onClick={onBack}
          aria-label="Back to people"
        >
          ‹
        </button>
        <div style={{ flex: 1 }}>
          <h3
            className="card-title"
            id="user-access-editor-title"
            style={{ margin: 0 }}
          >
            {user.name}
          </h3>
          <p className="card-subtitle" style={{ margin: 0 }}>
            {user.role} · {user.email}
          </p>
        </div>
      </div>

      <div className="access-level-toggle">
        <button
          className={"access-level-btn" + (isFull ? " active" : "")}
          onClick={() => onSetAccessLevel(user.id, "full")}
        >
          Full access
          <span>Sees all of {client.name}'s finances</span>
        </button>
        <button
          className={"access-level-btn" + (!isFull ? " active" : "")}
          onClick={() => onSetAccessLevel(user.id, "scoped")}
        >
          Limited access
          <span>Only the areas you choose below</span>
        </button>
      </div>

      {isPremiumClient && (
        <div className="access-level-toggle" style={{ marginTop: 12 }}>
          <button
            className={
              "access-level-btn" + (!premiumThrottled ? " active" : "")
            }
            onClick={() => premiumThrottled && onToggleUserPremium(user.id)}
          >
            Pro features on
            <span>Sees the Pro tools {client.name} is subscribed to</span>
          </button>
          <button
            className={"access-level-btn" + (premiumThrottled ? " active" : "")}
            onClick={() => !premiumThrottled && onToggleUserPremium(user.id)}
          >
            Pro features off
            <span>
              Plain pages without the Pro tools, even though {client.name} has Pro
            </span>
          </button>
        </div>
      )}

      {!isFull && (
        <div className="modal-body">
          <div className="modal-section">
            <div className="nav-section-label modal-section-label">
              Pages they can open
            </div>
            {NAV_SECTIONS.flatMap((s) => s.items)
              .filter((item) => orgAllowedKeys.includes(item.key))
              .map((item) => {
                const locked = item.key === ALWAYS_VISIBLE_KEY;
                const blockedByScope =
                  isCategoryScoped && ORG_WIDE_TABS.has(item.key);
                return (
                  <label
                    className={
                      "tab-toggle-row" +
                      (locked || blockedByScope ? " locked" : "")
                    }
                    key={item.key}
                  >
                    <input
                      type="checkbox"
                      checked={
                        (userTabs.has(item.key) || locked) && !blockedByScope
                      }
                      disabled={locked || blockedByScope}
                      onChange={() => onToggleUserTab(user.id, item.key)}
                    />
                    <span>{item.label}</span>
                    {locked && (
                      <span className="tab-toggle-note">Always visible</span>
                    )}
                    {blockedByScope && (
                      <span className="tab-toggle-note">Org-wide only</span>
                    )}
                  </label>
                );
              })}
          </div>

          <div className="modal-section">
            <div className="nav-section-label modal-section-label">
              Budget areas they can see
            </div>
            <p
              className="card-subtitle"
              style={{ marginTop: 0, marginBottom: 8 }}
            >
              Leave all unchecked to give them every category.
            </p>
            {client.budget.map((b) => (
              <label className="tab-toggle-row" key={b.category}>
                <input
                  type="checkbox"
                  checked={userCats.has(b.category)}
                  onChange={() => onToggleUserCategory(user.id, b.category)}
                />
                <span>{b.category}</span>
              </label>
            ))}
          </div>

          {isCategoryScoped && (
            <div className="modal-section">
              <div className="nav-section-label modal-section-label">
                Funds they can see
              </div>
              <p
                className="card-subtitle"
                style={{ marginTop: 0, marginBottom: 8 }}
              >
                Their dashboard never shows the org-wide fund total — leave all
                unchecked to hide the Funds widget for them entirely, rather
                than showing every fund by default.
              </p>
              {(client.funds || []).map((f) => (
                <label className="tab-toggle-row" key={f.name}>
                  <input
                    type="checkbox"
                    checked={userFunds.has(f.name)}
                    onChange={() => onToggleUserFund(user.id, f.name)}
                  />
                  <span>{f.name}</span>
                </label>
              ))}
            </div>
          )}
        </div>
      )}

      {isFull && (
        <div className="modal-body">
          <p className="card-subtitle">
            {user.name} sees every page and every category for {client.name},
            the same view you get previewing as MyGoodBooks.
          </p>
        </div>
      )}
    </React.Fragment>
  );
}

// Shared chrome for every modal in the app. Previously each one rendered a bare
// overlay div: Escape did nothing, focus stayed on whatever was behind the
// dialog, Tab walked the page underneath, and screen readers announced no
// dialog at all. Anything that puts a modal on screen should go through here.
// A branded stand-in for window.confirm() — the browser's own confirm()
// dialog is chrome-owned and prefixes itself with the page's domain (e.g.
// "example.com says"), which reads wrong for an app clients use under a
// custom brand. This renders as an ordinary in-app modal instead, so it
// carries no browser-domain text at all.
function ConfirmModal({
  title,
  body,
  confirmLabel = "Confirm",
  onConfirm,
  onCancel,
}) {
  return (
    <ModalShell
      onClose={onCancel}
      labelledBy="confirm-modal-title"
      className="confirm-modal"
    >
      <div className="modal-header">
        <h3
          className="card-title"
          id="confirm-modal-title"
          style={{ margin: 0 }}
        >
          {title}
        </h3>
        <button className="modal-close" onClick={onCancel} aria-label="Close">
          ×
        </button>
      </div>
      <div className="modal-body">
        <p className="card-subtitle" style={{ margin: 0 }}>
          {body}
        </p>
      </div>
      <div className="modal-footer">
        <button className="btn-secondary" onClick={onCancel}>
          Cancel
        </button>
        <button
          className="btn-primary"
          onClick={() => {
            onConfirm();
          }}
        >
          {confirmLabel}
        </button>
      </div>
    </ModalShell>
  );
}

function ModalShell({ onClose, labelledBy, className = "", children }) {
  const panelRef = useRef(null);
  const restoreFocusRef = useRef(null);
  // Read the latest onClose without it being an effect dependency — a modal
  // whose OWN invoking component also owns fast-changing state (e.g. a
  // textarea inside it) passes a new inline `onClose` identity on every
  // keystroke; depending on it here would re-run this effect that often,
  // and its cleanup restores focus to whatever was focused before the modal
  // opened, kicking the caret out after every single character typed.
  const onCloseRef = useRef(onClose);
  onCloseRef.current = onClose;

  useEffect(() => {
    const panel = panelRef.current;
    restoreFocusRef.current = document.activeElement;

    const focusables = () =>
      [
        ...panel.querySelectorAll(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])',
        ),
      ].filter((el) => !el.disabled && el.offsetParent !== null);

    // Land the caret inside the dialog rather than leaving it behind the scrim.
    const first = focusables()[0];
    (first || panel).focus();

    const onKeyDown = (e) => {
      if (e.key === "Escape") {
        e.stopPropagation();
        onCloseRef.current();
        return;
      }
      if (e.key !== "Tab") return;
      const items = focusables();
      if (!items.length) return;
      const firstEl = items[0];
      const lastEl = items[items.length - 1];
      // Wrap at both ends so Tab can't walk out into the page behind.
      if (e.shiftKey && document.activeElement === firstEl) {
        e.preventDefault();
        lastEl.focus();
      } else if (!e.shiftKey && document.activeElement === lastEl) {
        e.preventDefault();
        firstEl.focus();
      }
    };

    document.addEventListener("keydown", onKeyDown, true);
    return () => {
      document.removeEventListener("keydown", onKeyDown, true);
      const prev = restoreFocusRef.current;
      if (prev && typeof prev.focus === "function") prev.focus();
    };
    // Deliberately mount/unmount only (see onCloseRef above) — this must NOT
    // re-run on every render, or the cleanup's focus-restore fires on every
    // keystroke in a text field elsewhere in the modal.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div
        className={"modal-panel" + (className ? " " + className : "")}
        role="dialog"
        aria-modal="true"
        aria-labelledby={labelledBy}
        tabIndex={-1}
        ref={panelRef}
        onClick={(e) => e.stopPropagation()}
      >
        {children}
      </div>
    </div>
  );
}

function TabSettingsModal({
  scope = "access",
  client,
  visibleKeys,
  tabOrder,
  userAccess,
  onToggle,
  onReorder,
  onToggleUserTab,
  onToggleUserCategory,
  onToggleUserFund,
  onSetAccessLevel,
  onToggleUserPremium,
  staffUser,
  onOpenSop,
  initialTab,
  onClose,
}) {
  const [draggedKey, setDraggedKey] = useState(null);
  const [dragOverKey, setDragOverKey] = useState(null);
  const [editingUserId, setEditingUserId] = useState(null);
  // "access" (People/Org tabs/Requests) vs "details" (Documents/QuickBooks/
  // Notes/Activity) — two openers onto the same modal component rather than
  // two components, since every tab's data-loading and rendering logic below
  // is unchanged; only which tabs are offered differs per scope.
  const [tab, setTab] = useState(
    initialTab || (scope === "details" ? "documents" : "people"),
  );
  const [activeLink, setActiveLink] = useState(undefined); // undefined = loading, null = none
  const [requests, setRequests] = useState([]);
  const [generatingLink, setGeneratingLink] = useState(false);
  const [copied, setCopied] = useState(false);
  const [documents, setDocuments] = useState(undefined); // undefined = loading
  const [newDocName, setNewDocName] = useState("");
  const [newDocUrl, setNewDocUrl] = useState("");
  const [addingDoc, setAddingDoc] = useState(false);
  const [qboConnection, setQboConnection] = useState(undefined); // undefined = loading
  const [qboSyncing, setQboSyncing] = useState(false);
  const [confirmQboDisconnect, setConfirmQboDisconnect] = useState(false);
  const [privateNotes, setPrivateNotes] = useState(undefined); // undefined = loading
  const [newNoteText, setNewNoteText] = useState("");
  const [addingNote, setAddingNote] = useState(false);
  const [editingNoteId, setEditingNoteId] = useState(null);
  const [editingNoteText, setEditingNoteText] = useState("");
  const [activityLog, setActivityLog] = useState(undefined); // undefined = loading
  const showToast = useToast();

  const supabase = window.mgbSupabase;

  const loadQboConnection = useCallback(() => {
    if (!supabase) return;
    supabase
      .from("qbo_connections")
      .select("client_id, status, connected_at, last_synced_at, last_error")
      .eq("client_id", client.id)
      .maybeSingle()
      .then(({ data }) => setQboConnection(data || null));
  }, [supabase, client.id]);

  useEffect(() => {
    if (tab === "quickbooks") loadQboConnection();
  }, [tab, loadQboConnection]);

  // §170: pulls this one client's books from QuickBooks on demand, rather
  // than waiting for the hourly cron sweep (supabase/qbo-sync-cron.sql).
  // The Edge Function re-checks authorization as the caller — active staff
  // row plus can_access_client() — so this button is a convenience, not the
  // access control. The fresh numbers land in the qbo_* tables; the page
  // itself picks them up on the next load (index.html's loadQboData runs at
  // boot), which is what the toast says.
  async function syncQuickBooksNow() {
    if (!supabase || qboSyncing) return;
    setQboSyncing(true);
    try {
      const { data, error } = await supabase.functions.invoke("qbo-sync", {
        body: { client_id: client.id },
      });
      if (error) {
        showToast("Sync failed: " + error.message);
      } else if (data && data.errors && data.errors.length) {
        showToast("QuickBooks sync failed: " + data.errors[0].error);
      } else if (data && (data.status === "fresh" || data.status === "in_progress")) {
        // qbo-sync's throttle: synced under a minute ago, or already running.
        showToast(
          data.status === "fresh"
            ? "Already synced within the last minute."
            : "A sync is already running for this client.",
        );
      } else {
        const counts = (data && data.synced && data.synced[0] && data.synced[0].counts) || {};
        const total = Object.values(counts).reduce((a, b) => a + (b || 0), 0);
        showToast(
          `Synced ${total} record${total === 1 ? "" : "s"} from QuickBooks. Reload to see the new numbers.`,
        );
      }
    } catch (err) {
      showToast("Sync failed: " + (err && err.message ? err.message : err));
    } finally {
      setQboSyncing(false);
      // Either way, re-read the connection so last_synced_at / last_error
      // reflect what actually just happened.
      loadQboConnection();
    }
  }

  async function connectQuickBooks() {
    if (!window.QBO_CONFIG || !window.QBO_CONFIG.clientId) {
      showToast("QuickBooks isn't configured yet — see qbo-config.js.");
      return;
    }
    // `state` must be an unpredictable, single-use token, not the bare client
    // id — otherwise anyone could craft their own OAuth callback URL with a
    // guessed state and attribute a connection to a client they don't manage.
    // The Edge Function looks this token up server-side rather than trusting
    // whatever client_id shows up in the URL.
    const token = secureRandomToken();
    const { error } = await supabase
      .from("qbo_connect_state")
      .insert({ token, client_id: client.id });
    if (error) {
      showToast("Couldn't start the QuickBooks connection: " + error.message);
      return;
    }
    const redirectUri = `${window.SUPABASE_CONFIG.url}/functions/v1/qbo-callback`;
    const params = new URLSearchParams({
      client_id: window.QBO_CONFIG.clientId,
      response_type: "code",
      scope: "com.intuit.quickbooks.accounting",
      redirect_uri: redirectUri,
      state: token,
    });
    window.open(
      `https://appcenter.intuit.com/connect/oauth2?${params}`,
      "_blank",
      "noopener",
    );
  }

  async function disconnectQuickBooks() {
    setConfirmQboDisconnect(false);
    const { error } = await supabase.rpc("qbo_disconnect", {
      p_client_id: client.id,
    });
    if (error) {
      showToast("Couldn't disconnect QuickBooks: " + error.message);
      return;
    }
    loadQboConnection();
    showToast("QuickBooks disconnected.");
  }

  const loadDocuments = useCallback(() => {
    if (!supabase) return;
    supabase
      .from("client_documents")
      .select("id, name, drive_url, category, created_at")
      .eq("client_id", client.id)
      .is("trashed_at", null)
      .order("created_at", { ascending: false })
      .then(({ data }) => setDocuments(data || []));
  }, [supabase, client.id]);

  useEffect(() => {
    if (tab === "documents") loadDocuments();
  }, [tab, loadDocuments]);

  async function addDocument(e) {
    e.preventDefault();
    if (!supabase || !newDocName.trim() || !newDocUrl.trim()) return;
    // Security audit finding M2: reject anything that isn't a plain https
    // link at save time too, so a javascript:/data: URL can't even get into
    // the table (belt-and-suspenders alongside the render-time safeHttpUrl
    // check).
    const safeUrl = safeHttpUrl(newDocUrl.trim());
    if (!safeUrl) {
      showToast("That doesn't look like a valid https:// link.");
      return;
    }
    setAddingDoc(true);
    const { error } = await supabase.from("client_documents").insert({
      client_id: client.id,
      name: newDocName.trim(),
      drive_url: safeUrl,
      added_by: staffUser && staffUser.email,
    });
    setAddingDoc(false);
    if (error) {
      showToast("Couldn't add that document: " + error.message);
      return;
    }
    setNewDocName("");
    setNewDocUrl("");
    loadDocuments();
  }

  // Moves the link to the client's Documents Trash (restorable there)
  // rather than deleting it (supabase/document-trash.sql).
  async function removeDocument(id) {
    const { error } = await supabase
      .from("client_documents")
      .update({ trashed_at: new Date().toISOString() })
      .eq("id", id);
    if (error) showToast("Couldn't move that link to Trash: " + error.message);
    else showToast("Moved to Trash. Restore it from the Trash folder on Documents.");
    loadDocuments();
  }

  // Private staff notes: distinct from client_notes (a single shared
  // scratchpad shown on the bookkeeper home page) and from client_documents
  // above — these are never readable by the client (see
  // supabase/client-private-notes.sql, which has no client_users policy at
  // all).
  const loadPrivateNotes = useCallback(() => {
    if (!supabase) return;
    clientNotesApi
      .list(supabase, { clientId: client.id })
      .then(({ data, error }) => {
        if (error) {
          showToast(
            "Couldn't load notes. Has client-private-notes.sql been run? " +
              error.message,
          );
          setPrivateNotes([]);
          return;
        }
        setPrivateNotes(data || []);
      });
  }, [supabase, client.id, showToast]);

  useEffect(() => {
    if (tab === "notes") loadPrivateNotes();
  }, [tab, loadPrivateNotes]);
  const reloadNotesIfOpen = useCallback(() => {
    if (tab === "notes") loadPrivateNotes();
  }, [tab, loadPrivateNotes]);
  useClientNotesChanged(reloadNotesIfOpen);

  async function addPrivateNote(e) {
    e.preventDefault();
    if (!supabase || !newNoteText.trim()) return;
    setAddingNote(true);
    const { error } = await clientNotesApi.add(supabase, staffUser, {
      client_id: client.id,
      text: newNoteText.trim(),
    });
    setAddingNote(false);
    if (error) {
      showToast("Couldn't add that note: " + error.message);
      return;
    }
    setNewNoteText("");
  }

  function startEditNote(note) {
    setEditingNoteId(note.id);
    setEditingNoteText(note.text);
  }

  async function saveEditedNote(id) {
    const text = editingNoteText.trim();
    if (!text) return;
    const { error } = await clientNotesApi.update(supabase, id, { text });
    if (error) {
      showToast("Couldn't update that note: " + error.message);
      return;
    }
    setEditingNoteId(null);
  }

  async function togglePinNote(note) {
    const { error } = await clientNotesApi.pin(supabase, note);
    if (error) {
      showToast("Couldn't update that note: " + error.message);
      return;
    }
  }

  async function removePrivateNote(id) {
    const { error } = await clientNotesApi.remove(supabase, id);
    if (error) showToast("Couldn't remove that note: " + error.message);
  }

  // Read-only feed of client_activity_log — populated entirely by database
  // triggers (see supabase/client-activity-log.sql), not by app writes, so it
  // reflects every change regardless of how it was made.
  const loadActivityLog = useCallback(() => {
    if (!supabase) return;
    supabase
      .from("client_activity_log")
      .select("id, actor_email, actor_name, action, detail, created_at")
      .eq("client_id", client.id)
      .order("created_at", { ascending: false })
      .then(({ data, error }) => {
        if (error) {
          showToast("Couldn't load activity: " + error.message);
          return;
        }
        setActivityLog(data || []);
      });
  }, [supabase, client.id, showToast]);

  useEffect(() => {
    if (tab === "activity") loadActivityLog();
  }, [tab, loadActivityLog]);

  function describeActivity(entry) {
    const who = entry.actor_name || entry.actor_email || "System";
    const d = entry.detail || {};
    switch (entry.action) {
      case "document_added":
        return `${who} uploaded "${d.name}"`;
      case "document_removed":
        return `${who} removed "${d.name}"`;
      case "access_granted":
        return `${who} granted ${d.email} access (${d.role})`;
      case "access_revoked":
        return `${who} revoked ${d.email}'s access`;
      case "access_updated": {
        const bits = [];
        if (d.old_role !== d.new_role)
          bits.push(`role ${d.old_role} → ${d.new_role}`);
        if (d.old_active !== d.new_active)
          bits.push(d.new_active ? "reactivated" : "deactivated");
        return `${who} updated ${d.email}'s access${bits.length ? " (" + bits.join(", ") + ")" : ""}`;
      }
      case "qbo_status_changed":
        return `${who} updated QuickBooks status to ${d.new_status}`;
      case "note_updated":
        return `${who} updated the shared note`;
      default:
        return `${who} — ${entry.action}`;
    }
  }

  // Any active staff member (not just the original author) can edit or
  // delete a note — same reasoning as client_documents and client_notes:
  // these describe a client for whoever picks up the account next, not a
  // private diary, so a colleague filling in shouldn't be blocked from
  // fixing a stale or wrong note. Unlike Team Chat's messages there's no
  // time-limited edit window, since notes aren't a conversational record.

  const loadRequestsTab = useCallback(() => {
    if (!supabase) return;
    supabase
      .from("access_request_links")
      .select("token, active, created_at")
      .eq("client_id", client.id)
      .eq("active", true)
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle()
      .then(({ data }) => setActiveLink(data || null));
    supabase
      .from("access_requests")
      .select(
        "id, submitted_by_name, submitted_by_email, submitted_at, people, reviewed",
      )
      .eq("client_id", client.id)
      .order("submitted_at", { ascending: false })
      .then(({ data }) => setRequests(data || []));
  }, [supabase, client.id]);

  useEffect(() => {
    if (tab === "requests") loadRequestsTab();
  }, [tab, loadRequestsTab]);

  async function generateLink() {
    if (!supabase) return;
    setGeneratingLink(true);
    if (activeLink) {
      await supabase
        .from("access_request_links")
        .update({ active: false })
        .eq("token", activeLink.token);
    }
    const token = secureRandomToken().replace(/-/g, "");
    const { error } = await supabase.from("access_request_links").insert({
      token,
      client_id: client.id,
      created_by: staffUser && staffUser.email,
    });
    setGeneratingLink(false);
    if (error) {
      showToast("Couldn't generate a link: " + error.message);
      return;
    }
    loadRequestsTab();
  }

  async function markReviewed(id, reviewed) {
    await supabase.from("access_requests").update({ reviewed }).eq("id", id);
    loadRequestsTab();
  }

  function copyLink() {
    if (!activeLink) return;
    const url = `${window.location.origin}${window.location.pathname}?access-form=${activeLink.token}`;
    navigator.clipboard.writeText(url).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  }

  const orgAllowedKeys = ALL_TAB_KEYS.filter((k) => visibleKeys.has(k));
  const editingUser = editingUserId
    ? (client.users || []).find((u) => u.id === editingUserId)
    : null;

  if (editingUser) {
    return (
      <ModalShell onClose={onClose} labelledBy="user-access-editor-title">
        <UserAccessEditor
          client={client}
          user={editingUser}
          orgAllowedKeys={orgAllowedKeys}
          userAccess={userAccess}
          onToggleUserTab={onToggleUserTab}
          onToggleUserCategory={onToggleUserCategory}
          onToggleUserFund={onToggleUserFund}
          onSetAccessLevel={onSetAccessLevel}
          onToggleUserPremium={onToggleUserPremium}
          onBack={() => setEditingUserId(null)}
        />
        <div className="modal-footer">
          <button className="btn-primary" onClick={onClose}>
            Done
          </button>
        </div>
      </ModalShell>
    );
  }

  return (
    <ModalShell
      onClose={onClose}
      labelledBy="manage-access-title"
      className="modal-panel-wide"
    >
      <div className="modal-header">
        <h3
          className="card-title"
          id="manage-access-title"
          style={{ margin: 0 }}
        >
          {scope === "details" ? "Client details" : "Manage access"}
        </h3>
        <button className="modal-close" onClick={onClose} aria-label="Close">
          ×
        </button>
      </div>
      <p className="card-subtitle">{client.name}</p>

      <div className="modal-tabs">
        {scope === "access" && (
          <React.Fragment>
            <button
              className={"modal-tab" + (tab === "people" ? " active" : "")}
              onClick={() => setTab("people")}
            >
              People
            </button>
            <button
              className={"modal-tab" + (tab === "org" ? " active" : "")}
              onClick={() => setTab("org")}
            >
              Organization tabs
            </button>
            <button
              className={"modal-tab" + (tab === "requests" ? " active" : "")}
              onClick={() => setTab("requests")}
            >
              Requests
              {requests.some((r) => !r.reviewed) && (
                <span className="thread-tab-dot" />
              )}
            </button>
          </React.Fragment>
        )}
        {scope === "details" && (
          <React.Fragment>
            <button
              className={"modal-tab" + (tab === "documents" ? " active" : "")}
              onClick={() => setTab("documents")}
            >
              Documents
            </button>
            <button
              className={"modal-tab" + (tab === "quickbooks" ? " active" : "")}
              onClick={() => setTab("quickbooks")}
            >
              QuickBooks
            </button>
            <button
              className={"modal-tab" + (tab === "notes" ? " active" : "")}
              onClick={() => setTab("notes")}
            >
              Notes
            </button>
            <button
              className={"modal-tab" + (tab === "sop" ? " active" : "")}
              onClick={() => setTab("sop")}
            >
              SOP
            </button>
            <button
              className={"modal-tab" + (tab === "milestone" ? " active" : "")}
              onClick={() => setTab("milestone")}
            >
              Milestone
            </button>
            <button
              className={"modal-tab" + (tab === "activity" ? " active" : "")}
              onClick={() => setTab("activity")}
            >
              Activity
            </button>
          </React.Fragment>
        )}
      </div>

      {tab === "people" && (
        <div className="modal-body">
          <p className="card-subtitle" style={{ marginTop: 0 }}>
            Only MyGoodBooks can change these. Nobody at {client.name} can widen
            their own access.
          </p>
          {(client.users || []).map((u) => {
            const eff = userAccess[u.id] || {};
            const cats = eff.categories || u.categories;
            const throttled =
              "premiumThrottled" in eff
                ? eff.premiumThrottled
                : u.premiumThrottled;
            return (
              <button
                className="person-row"
                key={u.id}
                onClick={() => setEditingUserId(u.id)}
              >
                <div className="person-avatar">
                  {u.name
                    .split(" ")
                    .map((p) => p[0])
                    .slice(0, 2)
                    .join("")}
                </div>
                <div className="person-text">
                  <span className="person-name">{u.name}</span>
                  <span className="person-role">{u.role}</span>
                </div>
                {hasPremiumPlan(client) && (
                  <span
                    className={
                      "pill " + (throttled ? "restricted" : "unrestricted")
                    }
                  >
                    {throttled ? "Pro off" : "Pro"}
                  </span>
                )}
                <span
                  className={
                    "pill " +
                    (u.access === "full" ? "unrestricted" : "restricted")
                  }
                >
                  {u.access === "full"
                    ? "Full access"
                    : cats
                      ? `${cats.length} area${cats.length === 1 ? "" : "s"}`
                      : "Limited"}
                </span>
                <span className="person-chevron">›</span>
              </button>
            );
          })}
        </div>
      )}

      {tab === "org" && (
        <div className="modal-body">
          <p className="card-subtitle" style={{ marginTop: 0 }}>
            Turn a tab off here and nobody at {client.name} sees it, whatever
            their individual access. Drag ⠿ to reorder the Finances tabs.
          </p>
          {NAV_SECTIONS.map((section) => {
            const items = orderedSectionItems(section, tabOrder, client.id);
            return (
              <div className="modal-section" key={section.label}>
                <div className="nav-section-label modal-section-label">
                  {section.label}
                </div>
                {items.map((item) => {
                  const locked = item.key === ALWAYS_VISIBLE_KEY;
                  const checked = visibleKeys.has(item.key);
                  return (
                    <div
                      key={item.key}
                      className={
                        "tab-toggle-row" +
                        (locked ? " locked" : "") +
                        (dragOverKey === item.key && draggedKey !== item.key
                          ? " drag-over"
                          : "")
                      }
                      draggable={!locked}
                      onDragStart={() => setDraggedKey(item.key)}
                      onDragOver={(e) => {
                        e.preventDefault();
                        if (!locked) setDragOverKey(item.key);
                      }}
                      onDragLeave={() =>
                        setDragOverKey((k) => (k === item.key ? null : k))
                      }
                      onDrop={(e) => {
                        e.preventDefault();
                        if (draggedKey && draggedKey !== item.key && !locked) {
                          onReorder(section.label, draggedKey, item.key);
                        }
                        setDraggedKey(null);
                        setDragOverKey(null);
                      }}
                      onDragEnd={() => {
                        setDraggedKey(null);
                        setDragOverKey(null);
                      }}
                    >
                      <span
                        className={"drag-handle" + (locked ? " disabled" : "")}
                      >
                        {locked ? "" : "⠿"}
                      </span>
                      <label className="tab-toggle-label">
                        <input
                          type="checkbox"
                          checked={checked}
                          disabled={locked}
                          onChange={() => onToggle(item.key)}
                        />
                        <span>{item.label}</span>
                      </label>
                      {locked && (
                        <span className="tab-toggle-note">Always visible</span>
                      )}
                    </div>
                  );
                })}
              </div>
            );
          })}
        </div>
      )}

      {tab === "requests" && (
        <div className="modal-body">
          <p className="card-subtitle" style={{ marginTop: 0 }}>
            Send {client.name} a link to specify each person's access
            themselves. Applying a request still has to be done by hand in the
            People tab above — nothing here changes anyone's access on its own.
          </p>

          <div className="modal-section">
            {activeLink === undefined ? (
              <p className="card-subtitle">Loading…</p>
            ) : activeLink ? (
              <div className="access-link-row">
                <input
                  type="text"
                  readOnly
                  value={`${window.location.origin}${window.location.pathname}?access-form=${activeLink.token}`}
                  onFocus={(e) => e.target.select()}
                />
                <button className="btn-secondary" onClick={copyLink}>
                  {copied ? "Copied!" : "Copy"}
                </button>
                <button
                  className="btn-secondary"
                  disabled={generatingLink}
                  onClick={generateLink}
                >
                  {generatingLink ? "Working…" : "Regenerate"}
                </button>
              </div>
            ) : (
              <button
                className="btn-primary"
                disabled={generatingLink}
                onClick={generateLink}
              >
                {generatingLink ? "Generating…" : "Generate a link"}
              </button>
            )}
          </div>

          <div className="modal-section">
            <div className="nav-section-label modal-section-label">
              Submitted requests
            </div>
            {requests.length === 0 && (
              <p className="card-subtitle">Nothing submitted yet.</p>
            )}
            {requests.map((r) => (
              <div className="access-request-row" key={r.id}>
                <div className="access-request-row-header">
                  <div>
                    <span className="person-name">{r.submitted_by_name}</span>
                    <span className="person-role">
                      {" "}
                      · {r.submitted_by_email} ·{" "}
                      {fmtDate(r.submitted_at.slice(0, 10))}
                    </span>
                  </div>
                  <label className="tab-toggle-row" style={{ margin: 0 }}>
                    <input
                      type="checkbox"
                      checked={r.reviewed}
                      onChange={(e) => markReviewed(r.id, e.target.checked)}
                    />
                    <span>Reviewed</span>
                  </label>
                </div>
                {(r.people || []).map((p, i) => (
                  <div className="access-request-person" key={i}>
                    <div>
                      <strong>{p.name}</strong> · {p.role} · {p.email}
                    </div>
                    <div
                      className="card-subtitle"
                      style={{ margin: "2px 0 0" }}
                    >
                      {p.access === "full"
                        ? "Full access requested"
                        : [
                            (p.tabs || []).length
                              ? "Pages: " +
                                p.tabs
                                  .map((k) =>
                                    ALL_TAB_KEYS.includes(k)
                                      ? NAV_SECTIONS.flatMap(
                                          (s) => s.items,
                                        ).find((i) => i.key === k)
                                      : null,
                                  )
                                  .filter(Boolean)
                                  .map((i) => i.label)
                                  .join(", ")
                              : "No specific pages requested",
                            (p.categories || []).length
                              ? "Categories: " + p.categories.join(", ")
                              : null,
                          ]
                            .filter(Boolean)
                            .join(" — ")}
                    </div>
                  </div>
                ))}
              </div>
            ))}
          </div>
        </div>
      )}

      {tab === "documents" && (
        <div className="modal-body">
          <p className="card-subtitle" style={{ marginTop: 0 }}>
            Links to files already in {client.name}'s Google Drive. Nothing is
            uploaded or stored here — this just points at where the file already
            lives.
          </p>

          <form
            className="access-link-row"
            onSubmit={addDocument}
            style={{ marginBottom: 16 }}
          >
            <input
              type="text"
              placeholder="Document name"
              value={newDocName}
              onChange={(e) => setNewDocName(e.target.value)}
              required
            />
            <input
              type="url"
              placeholder="Google Drive share link"
              value={newDocUrl}
              onChange={(e) => setNewDocUrl(e.target.value)}
              required
            />
            <button className="btn-primary" disabled={addingDoc} type="submit">
              {addingDoc ? "Adding…" : "Add"}
            </button>
          </form>

          <div className="modal-section">
            <div className="nav-section-label modal-section-label">
              Linked documents
            </div>
            {documents === undefined ? (
              <p className="card-subtitle">Loading…</p>
            ) : documents.length === 0 ? (
              <p className="card-subtitle">No documents linked yet.</p>
            ) : (
              documents.map((d) => (
                <div className="access-request-row" key={d.id}>
                  <div className="access-request-row-header">
                    {safeHttpUrl(d.drive_url) ? (
                      <a
                        href={safeHttpUrl(d.drive_url)}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="person-name"
                      >
                        {d.name}
                      </a>
                    ) : (
                      <span className="person-name">{d.name}</span>
                    )}
                    <button
                      className="btn-secondary"
                      onClick={() => removeDocument(d.id)}
                    >
                      Move to Trash
                    </button>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      )}

      {tab === "quickbooks" && (
        <div className="modal-body">
          <p className="card-subtitle" style={{ marginTop: 0 }}>
            Connect {client.name}'s QuickBooks Online account to sync
            transactions, accounts, and budgets automatically instead of
            entering them by hand.
          </p>

          {window.QBO_CONFIG &&
            window.QBO_CONFIG.environment !== "production" && (
              <p
                className="card-subtitle"
                style={{ color: "#e0664f", marginTop: 0 }}
              >
                Sandbox mode only — this connects test QuickBooks companies, not
                a real client's account. Real clients need Intuit's production
                keys (separate from sandbox) and Intuit's app review to pass
                first.
              </p>
            )}

          <div className="modal-section">
            {qboConnection === undefined ? (
              <p className="card-subtitle">Loading…</p>
            ) : qboConnection && qboConnection.status === "connected" ? (
              <div className="access-request-row">
                <div className="access-request-row-header">
                  <span className="person-name">Connected</span>
                </div>
                <div className="card-subtitle" style={{ margin: "2px 0 0" }}>
                  Last synced{" "}
                  {relTime(qboConnection.last_synced_at) || "never yet"}
                </div>
                {qboConnection.last_error && (
                  <div
                    className="card-subtitle"
                    style={{ margin: "2px 0 0", color: "#e0664f" }}
                  >
                    Last sync: {qboConnection.last_error}
                  </div>
                )}
                <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
                  <button
                    className="btn-primary"
                    onClick={syncQuickBooksNow}
                    disabled={qboSyncing}
                  >
                    {qboSyncing ? "Syncing…" : "Sync now"}
                  </button>
                  <button className="btn-secondary" onClick={connectQuickBooks}>
                    Reconnect
                  </button>
                  <button
                    className="btn-secondary"
                    onClick={() => setConfirmQboDisconnect(true)}
                  >
                    Disconnect
                  </button>
                  {confirmQboDisconnect && (
                    <ConfirmModal
                      title="Disconnect QuickBooks?"
                      body={`${client.name} stops syncing from QuickBooks. Data already synced stays in the portal. Reconnecting needs someone to sign in to this client's QuickBooks again.`}
                      confirmLabel="Disconnect"
                      onConfirm={disconnectQuickBooks}
                      onCancel={() => setConfirmQboDisconnect(false)}
                    />
                  )}
                </div>
              </div>
            ) : qboConnection && qboConnection.status === "error" ? (
              <div className="access-request-row">
                <div className="access-request-row-header">
                  <span className="person-name" style={{ color: "#e0664f" }}>
                    Connection failed
                  </span>
                </div>
                {qboConnection.last_error && (
                  <div className="card-subtitle" style={{ margin: "2px 0 0" }}>
                    {qboConnection.last_error}
                  </div>
                )}
                <button
                  className="btn-primary"
                  style={{ marginTop: 12 }}
                  onClick={connectQuickBooks}
                >
                  Try again
                </button>
              </div>
            ) : (
              <button className="btn-primary" onClick={connectQuickBooks}>
                Connect QuickBooks
              </button>
            )}
          </div>

          {/* Which income accounts count as giving (components/client/QboGiving.jsx). */}
          {qboConnection &&
            qboConnection.status === "connected" &&
            typeof QG_GivingAccountsPicker === "function" && (
              <QG_GivingAccountsPicker client={client} />
            )}

          {/* Which balance-sheet accounts are funds (components/client/QboGiving.jsx). */}
          {qboConnection &&
            qboConnection.status === "connected" &&
            typeof QG_FundAccountsPicker === "function" && (
              <QG_FundAccountsPicker client={client} />
            )}
        </div>
      )}

      {tab === "notes" && (
        <div className="modal-body">
          <p className="card-subtitle" style={{ marginTop: 0 }}>
            Staff-only scratchpad for {client.name} — things like billing quirks
            or how to handle a touchy owner. Never visible to the client, in the
            chat, or anywhere they can see.
          </p>

          <form
            className="access-link-row"
            onSubmit={addPrivateNote}
            style={{ marginBottom: 16, alignItems: "flex-start" }}
          >
            <textarea
              placeholder="Add a note…"
              value={newNoteText}
              onChange={(e) => setNewNoteText(e.target.value)}
              rows={3}
              style={{ flex: 1, resize: "vertical" }}
              required
            />
            <button className="btn-primary" disabled={addingNote} type="submit">
              {addingNote ? "Adding…" : "Add note"}
            </button>
          </form>

          <div className="modal-section">
            <div className="nav-section-label modal-section-label">Notes</div>
            {privateNotes === undefined ? (
              <p className="card-subtitle">Loading…</p>
            ) : privateNotes.length === 0 ? (
              <p className="card-subtitle">No notes yet.</p>
            ) : (
              privateNotes.map((n) => (
                <div className="access-request-row" key={n.id}>
                  {editingNoteId === n.id ? (
                    <>
                      <textarea
                        value={editingNoteText}
                        onChange={(e) => setEditingNoteText(e.target.value)}
                        rows={3}
                        style={{ width: "100%", resize: "vertical" }}
                      />
                      <div style={{ display: "flex", gap: 8, marginTop: 8 }}>
                        <button
                          className="btn-primary"
                          onClick={() => saveEditedNote(n.id)}
                        >
                          Save
                        </button>
                        <button
                          className="btn-secondary"
                          onClick={() => setEditingNoteId(null)}
                        >
                          Cancel
                        </button>
                      </div>
                    </>
                  ) : (
                    <>
                      <div className="access-request-row-header">
                        <span className="person-name">
                          {n.pinned && "📌 "}
                          {n.author_name}
                        </span>
                        <span className="card-subtitle" style={{ margin: 0 }}>
                          {fmtDateTime(n.updated_at || n.created_at)}
                          {n.updated_at ? " (edited)" : ""}
                        </span>
                      </div>
                      <p
                        style={{ whiteSpace: "pre-wrap", margin: "4px 0 8px" }}
                      >
                        {n.text}
                      </p>
                      <div style={{ display: "flex", gap: 8 }}>
                        <button
                          className="btn-secondary"
                          onClick={() => togglePinNote(n)}
                        >
                          {n.pinned ? "Unpin" : "Pin"}
                        </button>
                        <button
                          className="btn-secondary"
                          onClick={() => startEditNote(n)}
                        >
                          Edit
                        </button>
                        <button
                          className="btn-secondary"
                          onClick={() => removePrivateNote(n.id)}
                        >
                          Remove
                        </button>
                      </div>
                    </>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      )}

      {tab === "sop" && (
        <div className="modal-body">
          <ClientSopView
            client={client}
            readOnly
            onEditInMyTasks={onOpenSop ? () => onOpenSop(client.id) : null}
          />
        </div>
      )}

      {tab === "milestone" && (
        <div className="modal-body">
          <MilestoneStaffPanel client={client} />
        </div>
      )}

      {tab === "activity" && (
        <div className="modal-body">
          <p className="card-subtitle" style={{ marginTop: 0 }}>
            Who touched {client.name}'s data, and when — documents, access
            grants, QuickBooks status, and notes. Logged automatically by the
            database, so it's complete regardless of how a change was made.
          </p>
          <div className="modal-section">
            {activityLog === undefined ? (
              <p className="card-subtitle">Loading…</p>
            ) : activityLog.length === 0 ? (
              <p className="card-subtitle">No activity recorded yet.</p>
            ) : (
              activityLog.map((entry) => (
                <div className="access-request-row" key={entry.id}>
                  <div className="access-request-row-header">
                    <span className="person-name">
                      {describeActivity(entry)}
                    </span>
                    <span className="card-subtitle" style={{ margin: 0 }}>
                      {fmtDateTime(entry.created_at)}
                    </span>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      )}

      <div className="modal-footer">
        {/* Real portal logins are enforced at sign-in (ClientAuthGate + RLS).
            Only a test client's sample people (data.js) are preview-only. */}
        <span className="modal-footnote">
          {client.testOnly !== false && (client.users || []).length > 0
            ? "Sample people on this test client are for preview only. Real portal logins are enforced at sign-in."
            : ""}
        </span>
        <button className="btn-primary" onClick={onClose}>
          Done
        </button>
      </div>
    </ModalShell>
  );
}

// ----------------------------------------------------------------------------
// App
// ----------------------------------------------------------------------------

// Explicit theme choice from the header toggle. Null means "use the
// automatic default" — see AUTO_THEME below (§149; previously always
// dark, see index.html's pre-hydration script and styles.css's
// data-theme guard, both updated to match).
const THEME_STORAGE_KEY = "mygoodbooks_theme_v1";

function loadTheme() {
  try {
    const raw = localStorage.getItem(THEME_STORAGE_KEY);
    return raw === "light" || raw === "dark" ? raw : null;
  } catch (e) {
    return null;
  }
}

// §149/§161: the automatic default follows the operating system's own
// light/dark setting, but only when the person hasn't explicitly picked a
// theme from the header toggle (loadTheme above always wins).
//
// This replaced a sunrise/sunset calculation driven by navigator.geolocation.
// That version worked, but it put a browser "allow location access?" prompt in
// front of a bookkeeping portal on first load, and the only thing it bought was
// a colour scheme. Asking a client for their physical location to guess a
// background colour is a bad trade at any accuracy — and prefers-color-scheme
// is strictly better information anyway, since it reports the preference the
// person actually set rather than inferring one from the sun. It also costs no
// permission, no cache, and no sunrise equation.
//
// The clock heuristic stays as the fallback for a browser that reports no
// preference. It's what index.html's pre-hydration script uses, so the very
// first paint already agrees with this.
function clockHeuristicTheme(date) {
  const hour = (date || new Date()).getHours();
  return hour >= 6 && hour < 19 ? "light" : "dark";
}

function systemOrClockTheme() {
  if (
    typeof window !== "undefined" &&
    typeof window.matchMedia === "function"
  ) {
    if (window.matchMedia("(prefers-color-scheme: dark)").matches)
      return "dark";
    if (window.matchMedia("(prefers-color-scheme: light)").matches)
      return "light";
  }
  return clockHeuristicTheme();
}

// §142: whether the sidebar shows full tab names or just icons — a per-
// browser preference (like theme), not tied to plan/role, so anyone can
// reclaim screen width on a smaller laptop without it resetting each
// visit. Deliberately kept to a single width toggle on one column, not a
// second icon rail — see HANDOFF7.md §124-§128 for why an earlier,
// fancier split-sidebar redesign got fully reverted after it accumulated
// layout bugs; this is intentionally the simpler shape.
// §149: used to default to collapsed — an explicit "0" (the person expanded
// it themselves) was the only thing that opted back out.
// §161: that default was then narrowed to STAFF only, since a client signs
// in occasionally and meets the icon rail cold.
// Staff nav redesign (2026-10-08): now defaults to EXPANDED for everyone.
// The staff rail is five labelled places (Today, Inbox, Work, Clients,
// Team) and the client sidebar no longer sits beside it, so there's no
// width to win back by hiding the words; a new hire should read the rail,
// not guess at it. An explicit choice ("0"/"1") still wins for both tiers;
// this only changes what happens when there is no choice yet.
const SIDEBAR_COLLAPSED_STORAGE_KEY = "mygoodbooks_sidebar_collapsed_v1";

function loadSidebarCollapsed(isClientPortal) {
  const fallback = false;
  try {
    const raw = localStorage.getItem(SIDEBAR_COLLAPSED_STORAGE_KEY);
    if (raw === "0") return false;
    if (raw === "1") return true;
    return fallback;
  } catch (e) {
    return fallback;
  }
}

const PAGE_STORAGE_KEY = "mygoodbooks_page_v1";

// Which tab the viewer was last on, so a refresh doesn't dump them back on the
// default page. Validated against the known tabs on the way out — a key from an
// older build (or a hand-edited value) falls back to the default rather than
// rendering nothing. Access is checked separately at render time via
// effectivePage, so a stored tab the current viewer can't see is handled there.
function loadPage() {
  try {
    const raw = localStorage.getItem(PAGE_STORAGE_KEY);
    // Any known page, staff-only ones included (Inbox, Work, ...);
    // effectivePage still bounces a page this viewer can't see.
    // Keys from before the staff nav redesign (2026-10-08) — "my-tasks",
    // "bookkeeper-home", "close-tracker", "my-time" and friends — aren't in
    // PAGE_META any more, so they fall through to null here and initialPage
    // lands a staff session on Today.
    if (raw && (Object.prototype.hasOwnProperty.call(PAGE_META, raw) || ALL_TAB_KEYS.includes(raw))) {
      return raw;
    }
    return null;
  } catch (e) {
    return null;
  }
}

// §136: how often the feedback survey (FeedbackSurveyModal) re-asks the
// same browser — per-browser via localStorage rather than a server-side
// "last asked" column, since not being nagged is worth more than perfect
// once-per-person accuracy, and this needs no Supabase round trip to decide.
const FEEDBACK_PROMPT_STORAGE_KEY = "mygoodbooks_feedback_prompted_at_v1";
const FEEDBACK_PROMPT_INTERVAL_DAYS = 60;
// Never on someone's first visit: the first sighting starts the clock so
// the first ask comes this many days later, then every interval after.
const FEEDBACK_FIRST_PROMPT_DAYS = 14;

function shouldPromptForFeedback() {
  try {
    const raw = localStorage.getItem(FEEDBACK_PROMPT_STORAGE_KEY);
    if (!raw) {
      const dayMs = 24 * 60 * 60 * 1000;
      localStorage.setItem(
        FEEDBACK_PROMPT_STORAGE_KEY,
        String(
          Date.now() -
            (FEEDBACK_PROMPT_INTERVAL_DAYS - FEEDBACK_FIRST_PROMPT_DAYS) * dayMs,
        ),
      );
      return false;
    }
    const last = Number(raw);
    if (!Number.isFinite(last)) return true;
    return (
      Date.now() - last > FEEDBACK_PROMPT_INTERVAL_DAYS * 24 * 60 * 60 * 1000
    );
  } catch (e) {
    return false;
  }
}

function markFeedbackPrompted() {
  try {
    localStorage.setItem(FEEDBACK_PROMPT_STORAGE_KEY, String(Date.now()));
  } catch (e) {}
}

const SELECTED_CLIENT_STORAGE_KEY = "mygoodbooks_selected_client_v1";

function loadSelectedClientId() {
  try {
    const raw = localStorage.getItem(SELECTED_CLIENT_STORAGE_KEY);
    return raw && CLIENTS.some((c) => c.id === raw) ? raw : null;
  } catch (e) {
    return null;
  }
}

// Set once per browser TAB (sessionStorage, not localStorage — a new tab or
// window gets a fresh one, closing the tab clears it, but a plain refresh of
// the same tab keeps it). Lets the very first render of a tab distinguish
// "just opened/signed in" (land on Home) from "refreshed mid-work" (restore
// exactly where they were) without hooking into Supabase auth events, which
// fire ambiguously between a real new sign-in and a silently-restored
// existing session on a page load.
const SESSION_STARTED_KEY = "mygoodbooks_session_started_v1";

// `email` is only passed for a staff session; a client-portal session calls
// this with nothing and gets its Dashboard.
function initialPage(email) {
  const isStaff = !!email;
  try {
    if (!sessionStorage.getItem(SESSION_STARTED_KEY)) {
      sessionStorage.setItem(SESSION_STARTED_KEY, "1");
      // Settings > Appearance & start page (staff). Read from the cached
      // copy: a fresh sign-in renders before user_settings has loaded.
      const start = typeof ST_cachedStartPage === "function" ? ST_cachedStartPage(email) : null;
      if (start === "tasks") return "work";
      if (start === "last-client" && loadSelectedClientId()) return "client-overview";
      return isStaff ? "today" : "dashboard";
    }
  } catch (e) {}
  // A staff member with nothing (or something stale) saved starts on Today,
  // never on a client's Dashboard — that page belongs to a client they may
  // not have meant to open.
  return loadPage() || (isStaff ? "today" : "dashboard");
}

// When THIS browser last viewed each client — per-device, not shared across
// staff or synced anywhere. Powers Home's "Recently viewed" and "Needs a
// visit" lists. Deliberately not a Supabase table: it's a personal working
// aid, not something anyone needs to see about anyone else.
const CLIENT_VISITS_STORAGE_KEY = "mygoodbooks_client_visits_v1";

function loadClientVisits() {
  try {
    const raw = localStorage.getItem(CLIENT_VISITS_STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    return {};
  }
}

function recordClientVisit(clientId) {
  try {
    const visits = loadClientVisits();
    visits[clientId] = Date.now();
    localStorage.setItem(CLIENT_VISITS_STORAGE_KEY, JSON.stringify(visits));
  } catch (e) {}
}

const TAB_CONFIG_STORAGE_KEY = "mygoodbooks_tab_config_v2";

function loadTabConfig() {
  try {
    const raw = localStorage.getItem(TAB_CONFIG_STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    return {};
  }
}

const TAB_ORDER_STORAGE_KEY = "mygoodbooks_tab_order_v1";

function loadTabOrder() {
  try {
    const raw = localStorage.getItem(TAB_ORDER_STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    return {};
  }
}

// Dashboard widget picker: which cards a client has chosen to show on their
// own dashboard, and in what order. Scoped separately per client + access
// scope (a bookkeeper previewing a limited user sees that user's picks, not
// their own full-access ones) since the set of *available* widgets differs.
const DASHBOARD_WIDGETS_STORAGE_KEY = "mygoodbooks_dashboard_widgets_v1";

function loadDashboardWidgetLayouts() {
  try {
    const raw = localStorage.getItem(DASHBOARD_WIDGETS_STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    return {};
  }
}

// Named snapshots of a widget arrangement ("Board meeting view", "Just the
// numbers", ...) a client can save and switch back to later, separate from
// the single "current" layout above. Scoped the same way (per client +
// access scope) since the available widgets differ by scope too.
const DASHBOARD_VIEWS_STORAGE_KEY = "mygoodbooks_dashboard_views_v1";

function loadDashboardViews() {
  try {
    const raw = localStorage.getItem(DASHBOARD_VIEWS_STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch (e) {
    return {};
  }
}

// allIds: every widget available in this scope right now (order = default
// order). Merges in any ids not yet in a saved layout (new widget added to
// the app later, or one that just became available) and drops any that are
// no longer available (e.g. a fund that was removed).
function useWidgetLayout(scopeKey, allIds) {
  const [layouts, setLayouts] = useState(loadDashboardWidgetLayouts);
  const [views, setViews] = useState(loadDashboardViews);
  const saved = layouts[scopeKey];
  // Custom cards (staff Home, components/staff/HomeCards.jsx) ride in the
  // same layout as { order, hidden, cards }; their ids join allIds so they
  // order and hide like any other widget. Other boards never set cards.
  const cards =
    saved && Array.isArray(saved.cards) && typeof HC_normalizeList === "function"
      ? HC_normalizeList(saved.cards)
      : [];
  allIds = allIds.concat(cards.map((c) => c.id));
  const order = saved
    ? saved.order
        .filter((id) => allIds.includes(id))
        .concat(allIds.filter((id) => !saved.order.includes(id)))
    : allIds.slice();
  const hidden = new Set(
    saved ? saved.hidden.filter((id) => allIds.includes(id)) : [],
  );
  const scopedViews = views[scopeKey] || [];

  // localStorage writers, shared by local edits and by adopting the account
  // copy below.
  const writeLayout = (layout) => {
    setLayouts((prev) => {
      const next = { ...prev, [scopeKey]: layout };
      try {
        localStorage.setItem(
          DASHBOARD_WIDGETS_STORAGE_KEY,
          JSON.stringify(next),
        );
      } catch (e) {}
      return next;
    });
  };
  const writeViews = (list) => {
    setViews((prev) => {
      const next = { ...prev, [scopeKey]: list };
      try {
        localStorage.setItem(DASHBOARD_VIEWS_STORAGE_KEY, JSON.stringify(next));
      } catch (e) {}
      return next;
    });
  };

  // Account copy (components/dashboard/WidgetDrawer.jsx): the scope key is
  // the board key, so each client/scope/Home keeps its own row. Falls back
  // to localStorage alone when the table or the session isn't there.
  WD_useBoardSync(
    scopeKey,
    () => ({ layout: saved || null, views: scopedViews }),
    (row) => {
      if (
        row.layout &&
        Array.isArray(row.layout.order) &&
        Array.isArray(row.layout.hidden)
      )
        writeLayout({
          order: row.layout.order,
          hidden: row.layout.hidden,
          ...(Array.isArray(row.layout.cards) ? { cards: row.layout.cards } : {}),
        });
      if (Array.isArray(row.views)) writeViews(row.views);
    },
  );

  const update = (nextOrder, nextHidden, nextCards = cards) => {
    const layout = { order: nextOrder, hidden: Array.from(nextHidden) };
    if (nextCards.length || (saved && saved.cards)) layout.cards = nextCards;
    writeLayout(layout);
    WD_sync.save(scopeKey, { layout });
  };
  const updateViews = (list) => {
    writeViews(list);
    WD_sync.save(scopeKey, { views: list });
  };

  return {
    order,
    hidden,
    visibleOrder: order.filter((id) => !hidden.has(id)),
    toggle: (id) => {
      const next = new Set(hidden);
      next.has(id) ? next.delete(id) : next.add(id);
      update(order, next);
    },
    // Drops draggedId into targetId's slot, shifting everything between.
    // Direction-aware: removing draggedId shifts every later index down by
    // one, so a forward drag (dragging something onto a neighbor further
    // right/down) has to land *after* the target's post-removal position —
    // landing "before" it (the naive approach) puts it right back where it
    // started for an adjacent swap, which reads as "dragging right does
    // nothing." A backward drag has no such shift, so "before" is correct.
    reorder: (draggedId, targetId) => {
      if (draggedId === targetId) return;
      const draggedIndex = order.indexOf(draggedId);
      const targetIndex = order.indexOf(targetId);
      if (draggedIndex === -1 || targetIndex === -1) return;
      const next = order.filter((id) => id !== draggedId);
      let insertAt = next.indexOf(targetId);
      if (draggedIndex < targetIndex) insertAt += 1;
      next.splice(insertAt, 0, draggedId);
      update(next, hidden);
    },
    // Shows a hidden widget at the end of the board (the drawer's "+").
    add: (id) => {
      const next = new Set(hidden);
      next.delete(id);
      update(order.filter((x) => x !== id).concat(id), next);
    },
    // Reset puts the built-in cards back in their default order; custom
    // cards stay, at the end.
    reset: () => update(allIds.slice(), new Set()),

    // Custom cards: add (to the end, visible) or replace by id, and remove.
    cards,
    saveCard: (def) => {
      const exists = cards.some((c) => c.id === def.id);
      const nextCards = exists
        ? cards.map((c) => (c.id === def.id ? def : c))
        : cards.concat(def);
      const nextOrder = exists ? order : order.filter((x) => x !== def.id).concat(def.id);
      const nextHidden = new Set(hidden);
      if (!exists) nextHidden.delete(def.id);
      update(nextOrder, nextHidden, nextCards);
    },
    removeCard: (id) => {
      const nextHidden = new Set(hidden);
      nextHidden.delete(id);
      update(
        order.filter((x) => x !== id),
        nextHidden,
        cards.filter((c) => c.id !== id),
      );
    },

    // Named snapshots of the current order/hidden set — separate from
    // localStorage's single "current" layout above, so a client can flip
    // between a couple of arrangements (e.g. a stripped-down board view vs.
    // their own everyday one) without losing either.
    views: scopedViews,
    saveView: (name) => {
      const trimmed = (name || "").trim();
      if (!trimmed) return;
      // Saving under a name that already exists overwrites it rather than
      // piling up duplicates.
      updateViews([
        ...scopedViews.filter((v) => v.name !== trimmed),
        { name: trimmed, order, hidden: Array.from(hidden) },
      ]);
    },
    applyView: (name) => {
      const view = scopedViews.find((v) => v.name === name);
      if (!view) return;
      update(
        view.order
          .filter((id) => allIds.includes(id))
          .concat(allIds.filter((id) => !view.order.includes(id))),
        new Set(view.hidden.filter((id) => allIds.includes(id))),
      );
    },
    deleteView: (name) => {
      updateViews(scopedViews.filter((v) => v.name !== name));
    },
  };
}

// Card drag-to-reorder. The implementation (and the long note on why it's
// mouse-only) lives in components/dashboard/WidgetDrawer.jsx so the Live
// Report can share it; dragProps(id) also tags each card with data-wd-id,
// which is how the Customize drawer's edit mode finds the cards.
function useDragReorder(layout) {
  return WD_useDragReorder(layout);
}

// Opens the shared Customize drawer (components/dashboard/WidgetDrawer.jsx).
// Used by DashboardPage and ScopedDashboardPage.
function CustomizeDashboardButton({ widgets, layout, onCreateCustom, createCustomDesc }) {
  return (
    <WD_CustomizeButton
      widgets={widgets}
      layout={layout}
      onCreateCustom={onCreateCustom}
      createCustomDesc={createCustomDesc}
    >
      <SlidersIcon /> Customize dashboard
    </WD_CustomizeButton>
  );
}

