// Without this, any component error unmounts the whole tree and the page
// goes blank with nothing but a console error. This is the only class
// component in the app — getDerivedStateFromError/componentDidCatch have no
// hook equivalent.
class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false };
  }

  static getDerivedStateFromError() {
    return { hasError: true };
  }

  componentDidCatch(error, info) {
    console.error("Uncaught error in app tree:", error, info);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="error-boundary">
          <div className="error-boundary-card">
            <div className="error-boundary-title">Something went wrong</div>
            <p className="error-boundary-body">
              This page hit an unexpected error. Reloading usually fixes it —
              your data hasn't been affected.
            </p>
            <button
              className="btn-primary"
              onClick={() => window.location.reload()}
            >
              Reload
            </button>
          </div>
        </div>
      );
    }
    return this.props.children;
  }
}

// clientPortalUser: a signed-in client (Phase 2 — see ClientAuthGate), never
// present alongside staffUser. Pins the whole app to that one person's own
// client_id (no picker, nothing to switch) and, further down, hands their
// real row straight to resolveAccess instead of the mock viewAsUserId
// lookup — everything downstream (Sidebar's isBookkeeper branch, the
// effectivePage guards, scopeClientData) already treats "access.user is a
// real person" as the client-facing view, the same path "Preview As"
// already exercises, so this reuses it rather than building a parallel one.
// "Sync now", next to the header's sync pill — for staff and clients alike,
// shown only when the viewed client's numbers came from a live QuickBooks
// connection. Asks the qbo-sync Edge Function to pull this one client now
// (it re-checks authorization as the caller and throttles to one real pull
// per minute per connection), then re-runs index.html's loadQboData for just
// this client so the numbers and "synced X ago" update without a reload.
// Rendered inside ToastProvider, which App itself sits above — hence its own
// component rather than a handler in App.
// With `liveLabel` (always syncPillLabel(plan, lastSyncedAt)), renders as one
// combined pill: "● Every 15 min · synced 1m ago  ↻" (the header's sync
// badge and Sync now in one control, to save space). Clicking anywhere on it
// syncs.
function QboSyncNowButton({ clientId, onSynced, liveLabel: liveLabelProp, plan, lastSyncedAt, canSyncNow = true }) {
  const showToast = useToast();
  const [syncing, setSyncing] = useState(false);
  // With plan + lastSyncedAt the pill builds its own label and re-renders
  // itself every 30s so "synced 5m ago" stays current. (App used to re-render
  // every page on a 30-second timer just for this.)
  const ownLabel = plan !== undefined;
  const [, setRelTick] = useState(0);
  useEffect(() => {
    if (!ownLabel) return undefined;
    const id = setInterval(() => setRelTick((t) => t + 1), 30000);
    return () => clearInterval(id);
  }, [ownLabel]);
  const liveLabel = ownLabel ? syncPillLabel(plan, lastSyncedAt) : liveLabelProp;

  async function syncNow() {
    const supabase = window.mgbSupabase;
    if (!supabase || syncing) return;
    setSyncing(true);
    try {
      const { data, error } = await supabase.functions.invoke("qbo-sync", {
        body: { client_id: clientId },
      });
      if (error || !data || data.status === "error" || (data.errors && data.errors.length)) {
        const httpStatus = error && error.context && error.context.status;
        const detail = String(
          (data && (data.error || (data.errors && data.errors[0] && data.errors[0].error))) || "",
        );
        let message = "We couldn't reach QuickBooks just now. Please try again in a few minutes.";
        if (/included with Pro/i.test(detail)) {
          message = "Sync now is included with Pro. Your numbers refresh on your plan's schedule.";
        } else if (httpStatus === 401 || httpStatus === 403) {
          message = "You don't have permission to sync this account. Try signing out and back in.";
        } else if (httpStatus === 400) {
          message = "QuickBooks isn't connected for this account.";
        } else if (/reconnect/i.test(detail)) {
          message = "QuickBooks needs to be reconnected before it can sync. Your bookkeeper can do this.";
        }
        showToast(message);
        return;
      }
      if (window.mgbReloadQboData) await window.mgbReloadQboData([clientId]);
      notifyMilestonesChanged();
      if (onSynced) onSynced();
      if (data.status === "in_progress") {
        showToast("A sync is already running — your numbers will update shortly.");
      } else if (data.status === "fresh") {
        showToast("Already up to date with QuickBooks.");
      } else {
        showToast("Up to date with QuickBooks.");
      }
    } catch (err) {
      showToast("We couldn't reach QuickBooks just now. Please try again in a few minutes.");
    } finally {
      setSyncing(false);
    }
  }

  const syncIcon = (
    <svg
      className={"qbo-sync-now-icon" + (syncing ? " is-spinning" : "")}
      width="14"
      height="14"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      <path d="M20 12a8 8 0 1 1-2.34-5.66" />
      <path d="M20 4v4.5h-4.5" />
    </svg>
  );
  if (liveLabel && !canSyncNow) {
    // Basic: the same pill, as a label only (no Sync now).
    return (
      <span className="live-sync-pill live-sync-pill-static" title={liveLabel}>
        <span className="badge-dot" aria-hidden="true"></span>
        <span className="live-sync-text">{liveLabel}</span>
      </span>
    );
  }
  if (liveLabel) {
    return (
      <>
        <button
          type="button"
          className="live-sync-pill"
          onClick={syncNow}
          disabled={syncing}
          title={syncing ? "Syncing with QuickBooks" : "Sync now with QuickBooks"}
          aria-label={`${liveLabel}. ${syncing ? "Syncing with QuickBooks" : "Sync now with QuickBooks"}`}
        >
          <span className="badge-dot" aria-hidden="true"></span>
          <span className="live-sync-text">{syncing ? "Syncing…" : liveLabel}</span>
          <span className="live-sync-divider" aria-hidden="true"></span>
          {syncIcon}
        </button>
        <span className="qbo-sync-now-status" aria-live="polite">
          {syncing ? "Syncing with QuickBooks…" : ""}
        </span>
      </>
    );
  }
  return (
    <>
      <button
        type="button"
        className="qbo-sync-now"
        onClick={syncNow}
        disabled={syncing}
        aria-label={syncing ? "Syncing with QuickBooks" : "Sync now with QuickBooks"}
      >
        <svg
          className={"qbo-sync-now-icon" + (syncing ? " is-spinning" : "")}
          width="14"
          height="14"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.8"
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden="true"
        >
          <path d="M20 12a8 8 0 1 1-2.34-5.66" />
          <path d="M20 4v4.5h-4.5" />
        </svg>
        <span>{syncing ? "Syncing…" : "Sync now"}</span>
      </button>
      <span className="qbo-sync-now-status" aria-live="polite">
        {syncing ? "Syncing with QuickBooks…" : ""}
      </span>
    </>
  );
}

// Hash routes, so a link can open a specific page (the weekly digest email's
// section links, a URL pasted into chat):
//   #/today  #/inbox  #/work/close  #/team/reviews  #/clients  #/help/<slug>
//   #/audit-log  #/emails  #/templates ...
//   #/client/<client id>/overview  #/client/<client id>/<tab key>
//   #/client/<client id>/sop
// Read once on load and on hashchange; App keeps the hash in step with what's
// on screen (one history entry per page change, so the browser's Back button
// walks back through places and clients — see the hash sync effect in App).
// It only ever sets `page` / `selectedClientId`, so the usual gating still
// decides what renders: effectivePage bounces a page the viewer can't see,
// the visibleClients check drops a client they aren't assigned, and a client
// portal user is always pinned to their own org.
// A place's slug comes from the shared nav contract (NAV_PLACE_BY_KEY in
// components/staff/StaffNav.jsx); every other staff page's slug is its key.
const HASH_PAGE_ALIASES = {
  templates: "task-templates",
};
const HASH_PAGE_SLUGS = Object.fromEntries(
  Object.entries(HASH_PAGE_ALIASES).map(([slug, page]) => [page, slug]),
);
function hashSlugOfPage(page) {
  const place = typeof NAV_PLACE_BY_KEY === "object" && NAV_PLACE_BY_KEY ? NAV_PLACE_BY_KEY[page] : null;
  return (place && place.slug) || HASH_PAGE_SLUGS[page] || page;
}
// Places whose page keeps a sub-route after the slug (#/work/close,
// #/team/reviews/r/<id>, #/help/<slug>) — the page component owns what
// comes after, via NAV_useHashSub / StaffGuide.jsx / TeamReviews.jsx.
const HASH_SUB_ROUTE_PAGES = new Set(["work", "team", "help"]);

// Client-route tab slugs that open client Settings.
const CLIENT_TAB_ALIASES = {
  home: "dashboard",
  settings: "client-settings",
  plan: "client-settings",
  plans: "client-settings",
  "enterprise-upgrade": "client-settings",
  "manage-access": "client-settings",
  "client-details": "client-settings",
};
const CLIENT_SETTINGS_TAB_OF = {
  plan: "plan",
  plans: "plan",
  "enterprise-upgrade": "plan",
  "manage-access": "client",
  "client-details": "client",
};

function isKnownAppPage(p) {
  return !!p && (Object.prototype.hasOwnProperty.call(PAGE_META, p) || ALL_TAB_KEYS.includes(p));
}

// Supabase auth redirects also use the fragment (#access_token=...); leave
// those alone.
function isAuthHash(hash) {
  return /access_token=|refresh_token=|error_description=|type=recovery/.test(String(hash || ""));
}

function parseHashRoute(hash) {
  if (!hash || isAuthHash(hash)) return null;
  let parts;
  try {
    parts = String(hash)
      .replace(/^#\/?/, "")
      .split(/[?]/)[0]
      .split("/")
      .filter(Boolean)
      .map(decodeURIComponent);
  } catch (e) {
    return null;
  }
  if (!parts.length) return null;
  if (parts[0] === "client") {
    if (!parts[1]) return null;
    const tab = parts[2] || "overview";
    const page = tab === "overview" ? "client-overview" : tab;
    // Settings (owner request 2026-09-30): #/client/<id>/settings[/<tab>].
    // The old Plans, Manage access and Client details entry points now open
    // a tab of it, so their slugs stay accepted.
    // #/client/<id>/finances opens the last tab used in Finances.
    const aliased =
      page === "finances"
        ? CLIENT_lastTab("finances", CLIENT_PLACES.find((p) => p.key === "finances").tabs)
        : CLIENT_TAB_ALIASES[page] || page;
    const settingsTab = aliased === "client-settings" ? parts[3] || CLIENT_SETTINGS_TAB_OF[page] || null : null;
    // "sop" (#/client/<id>/sop) is in PAGE_META, so it passes like any tab.
    return { clientId: parts[1], page: isKnownAppPage(aliased) ? aliased : null, settingsTab };
  }
  // A place's slug (#/work, #/team/reviews), an alias (#/templates) or a
  // bare page key (#/audit-log). Anything after the slug belongs to the page
  // (see HASH_SUB_ROUTE_PAGES); it isn't parsed here.
  const place = typeof NAV_PLACE_BY_SLUG === "object" && NAV_PLACE_BY_SLUG ? NAV_PLACE_BY_SLUG[parts[0]] : null;
  const page = (place && place.key) || HASH_PAGE_ALIASES[parts[0]] || parts[0];
  return isKnownAppPage(page) ? { page } : null;
}

function buildHashRoute(page, clientId) {
  if (NON_CLIENT_PAGES.has(page)) {
    const slug = hashSlugOfPage(page);
    // Work, Team and Help keep whatever sub-route is already in the hash
    // (#/work/close, #/team/reviews/r/<id>, #/help/<slug>): the page
    // component put it there and reads it back; App only owns the first
    // segment.
    if (
      HASH_SUB_ROUTE_PAGES.has(page) &&
      new RegExp("^#\\/" + slug + "\\/[a-z0-9-]+(\\/[a-z0-9-]+)*$").test(window.location.hash)
    )
      return window.location.hash;
    return "#/" + slug;
  }
  if (!clientId) return "";
  return (
    "#/client/" +
    encodeURIComponent(clientId) +
    "/" +
    (page === "client-overview" ? "overview" : page === "client-settings" ? "settings" : encodeURIComponent(page))
  );
}

// Back and Refresh buttons for the installed app (owner request 2026-10-06).
// An installed app window has no browser toolbar, so there's no way back to
// the last page or to reload it. Only shown in standalone display mode
// (desktop or phone); in a browser tab the browser's own buttons do this.
// In standalone, App pushes a history entry per page change (instead of
// replacing it), numbering each one in history.state.mgbNav so Back knows
// when there's nothing left to go back to inside the app.
function AN_isStandalone() {
  try {
    return (
      (window.matchMedia && window.matchMedia("(display-mode: standalone)").matches) ||
      window.navigator.standalone === true
    );
  } catch (e) {
    return false;
  }
}
function AN_navIndex() {
  const st = window.history.state;
  return st && typeof st.mgbNav === "number" ? st.mgbNav : 0;
}

function AN_AppNav({ variant }) {
  const [standalone] = useState(AN_isStandalone);
  const [canBack, setCanBack] = useState(() => AN_navIndex() > 0);
  useEffect(() => {
    if (!standalone) return;
    const sync = () => setCanBack(AN_navIndex() > 0);
    window.addEventListener("hashchange", sync);
    window.addEventListener("popstate", sync);
    window.addEventListener("mgb-nav", sync);
    return () => {
      window.removeEventListener("hashchange", sync);
      window.removeEventListener("popstate", sync);
      window.removeEventListener("mgb-nav", sync);
    };
  }, [standalone]);
  if (!standalone) return null;
  const cls = variant === "tb" ? "tb-icon-btn" : "an-btn";
  return (
    <span className="an-nav">
      <button
        type="button"
        className={cls}
        onClick={() => window.history.back()}
        disabled={!canBack}
        aria-label="Back"
        data-tip="Back"
      >
        <svg viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <path d="M12.5 4.5 7 10l5.5 5.5" />
        </svg>
      </button>
      <button
        type="button"
        className={cls}
        onClick={() => window.location.reload()}
        aria-label="Refresh"
        data-tip="Refresh"
      >
        <svg viewBox="0 0 20 20" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
          <path d="M16 10a6 6 0 1 1-1.76-4.24" />
          <path d="M16 3.5V7h-3.5" />
        </svg>
      </button>
    </span>
  );
}

// Signing in with Google redirects back to the bare origin, which drops the
// hash. Stash a deep link at boot (this file runs before the sign-in screen)
// so App can still open it after the round trip.
const PENDING_ROUTE_KEY = "mygoodbooks_pending_route_v1";
try {
  if (parseHashRoute(window.location.hash)) {
    sessionStorage.setItem(PENDING_ROUTE_KEY, window.location.hash);
  }
} catch (e) {}

function App({ staffUser, onSignOut, clientPortalUser }) {
  // Deep link from the URL hash, read once on mount (see parseHashRoute).
  const [initialRoute] = useState(() => {
    try {
      let route = parseHashRoute(window.location.hash);
      if (!route) route = parseHashRoute(sessionStorage.getItem(PENDING_ROUTE_KEY));
      sessionStorage.removeItem(PENDING_ROUTE_KEY);
      return route;
    } catch (e) {
      return null;
    }
  });
  // Riverside: premium plan (so Live Report is reachable) and, as of the
  // thread fixes in data.js, no thread whose last message is unread —
  // nothing steals focus with the chat popup on first load. Only the
  // fallback when nothing was ever persisted (loadSelectedClientId returns
  // null) — a returning staffer lands back on whatever client they last had
  // open, per initialPage's refresh-vs-fresh-open distinction below.
  const [selectedClientId, setSelectedClientId] = useState(
    () =>
      (clientPortalUser && clientPortalUser.client_id) ||
      (initialRoute &&
        initialRoute.clientId &&
        CLIENTS.some((c) => c.id === initialRoute.clientId) &&
        initialRoute.clientId) ||
      loadSelectedClientId() ||
      "riverside-pantry",
  );
  // A refresh keeps whatever page was open, for staff and clients alike. A
  // client never lands on a staff place like "today" — that's staff-only
  // chrome they can't render (no staffUser) — and a staff member never
  // starts on a client's Dashboard by accident (initialPage).
  // Sub-tab inside a client place that isn't its own page (Reports ›
  // Downloads | Board packet, Messages › Conversation | Requests). Keyed by
  // page so it never leaks across pages. Mirrored into the hash's 4th segment.
  const [clientSub, setClientSub] = useState(CLIENT_subFromHash);
  const [page, setPage] = useState(() => {
    const p = clientPortalUser ? initialPage() : initialPage(staffUser && staffUser.email);
    const fromHash = initialRoute && initialRoute.page;
    const chosen = fromHash || p;
    // #/settings is the staff page; a client gets their own Settings.
    if (clientPortalUser && chosen === "settings") return "client-settings";
    return clientPortalUser && NON_CLIENT_PAGES.has(chosen) ? "dashboard" : chosen;
  });
  // Which tab client Settings shows (Settings.jsx ST_ClientSettingsPage).
  const [settingsTab, setSettingsTab] = useState(() => (initialRoute && initialRoute.settingsTab) || null);
  // Sidebar dot for Team Chat — recomputed on every page change and on any
  // Team Chat activity (cheap, single-purpose query) rather than polling,
  // same posture as the rest of this app's Supabase reads. "Read" is now a
  // real per-conversation server column (staff_conversation_members.last_read_at),
  // not a per-browser localStorage guess, so this works the same regardless
  // of who the other side of any given conversation is.
  const [staffMessagesUnread, setStaffMessagesUnread] = useState(false);
  const checkStaffMessagesUnread = useCallback(() => {
    const supabase = window.mgbSupabase;
    if (!supabase || !staffUser) {
      setStaffMessagesUnread(false);
      return;
    }
    supabase
      .from("staff_conversation_members")
      .select("conversation_id, last_read_at")
      .eq("staff_email", staffUser.email)
      .then(({ data, error }) => {
        if (error || !data || data.length === 0) {
          setStaffMessagesUnread(false);
          return;
        }
        const convIds = data.map((r) => r.conversation_id);
        const readByConv = {};
        data.forEach((r) => {
          readByConv[r.conversation_id] = r.last_read_at;
        });
        supabase
          .from("staff_messages")
          .select("conversation_id, author_email, created_at")
          .in("conversation_id", convIds)
          .is("deleted_at", null)
          .order("created_at", { ascending: false })
          .limit(200)
          .then(({ data: msgs, error: msgErr }) => {
            if (msgErr || !msgs) {
              setStaffMessagesUnread(false);
              return;
            }
            const latestByConv = {};
            msgs.forEach((m) => {
              if (!latestByConv[m.conversation_id])
                latestByConv[m.conversation_id] = m;
            });
            const unread = Object.values(latestByConv).some((m) => {
              if (m.author_email === staffUser.email) return false;
              const readAt = readByConv[m.conversation_id];
              return !readAt || new Date(m.created_at) > new Date(readAt);
            });
            setStaffMessagesUnread(unread);
          });
      });
  }, [staffUser]);
  useEffect(() => {
    checkStaffMessagesUnread();
  }, [checkStaffMessagesUnread, page]);

  // Sidebar count beside "My Tasks": my open items (owned or assigned to me)
  // that are overdue, due today, or past their remind-me time. Refetched on
  // page change and on any staff_reminders write (staffItemsApi's event, which
  // the Realtime subscription below also fires); recounted from the cached
  // rows every minute so midnight and remind-me times roll over without a
  // query.
  const [myTasksDue, setMyTasksDue] = useState({ overdue: 0, due: 0 });
  const myTasksRowsRef = useRef([]);
  const recountMyTasksDue = useCallback(() => {
    if (!staffUser) return;
    setMyTasksDue((prev) => {
      const next = countDueStaffItems(
        myTasksRowsRef.current,
        staffUser.email,
        todayLocal(),
        Date.now(),
      );
      return next.due === prev.due && next.overdue === prev.overdue
        ? prev
        : next;
    });
  }, [staffUser]);
  const refreshMyTasksDue = useCallback(() => {
    const supabase = window.mgbSupabase;
    if (!supabase || !staffUser) {
      myTasksRowsRef.current = [];
      setMyTasksDue({ overdue: 0, due: 0 });
      return;
    }
    staffItemsApi.list(supabase, staffUser.email).then(({ data, error }) => {
      if (error || !data) return;
      myTasksRowsRef.current = data;
      recountMyTasksDue();
    });
  }, [staffUser, recountMyTasksDue]);
  useEffect(() => {
    refreshMyTasksDue();
  }, [refreshMyTasksDue, page]);
  useStaffItemsChanged(refreshMyTasksDue);
  useEffect(() => {
    if (!staffUser) return;
    const id = setInterval(recountMyTasksDue, 60 * 1000);
    return () => clearInterval(id);
  }, [staffUser, recountMyTasksDue]);

  // Live refresh for My Tasks / Home / the badge when a teammate (or another
  // tab) changes a row this person can see. Private channel, same pattern as
  // Team Chat (audit2-realtime-private-channels.sql); RLS on staff_reminders
  // decides which rows' events reach whom. Silent no-op until
  // staff-reminders-v2.sql adds the table to the supabase_realtime
  // publication.
  useEffect(() => {
    const supabase = window.mgbSupabase;
    if (!supabase || !staffUser) return;
    const channel = supabase
      .channel("staff-reminders-" + staffUser.email, {
        config: { private: true },
      })
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "staff_reminders" },
        () => staffItemsApi.notify(),
      )
      .subscribe();
    return () => {
      supabase.removeChannel(channel);
    };
  }, [staffUser]);
  // Same for staff-only client notes (dated notes + handoff summaries), so
  // My Tasks, Home and Client details pick up a teammate's edit. No-op until
  // tasks-notes-v3.sql adds the tables to the publication.
  useEffect(() => {
    const supabase = window.mgbSupabase;
    if (!supabase || !staffUser) return;
    const channel = supabase
      .channel("client-notes-" + staffUser.email, {
        config: { private: true },
      })
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "client_private_notes" },
        () => clientNotesApi.notify(),
      )
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "client_notes" },
        () => clientNotesApi.notify(),
      )
      .subscribe();
    return () => {
      supabase.removeChannel(channel);
    };
  }, [staffUser]);
  // Same for client SOPs, on their own channel so a missing table (before
  // client-sops.sql is applied) can't affect the notes subscription above.
  useEffect(() => {
    const supabase = window.mgbSupabase;
    if (!supabase || !staffUser) return;
    const channel = supabase
      .channel("client-sops-" + staffUser.email, {
        config: { private: true },
      })
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "client_sops" },
        () => clientSopsApi.notify(),
      )
      .subscribe();
    return () => {
      supabase.removeChannel(channel);
    };
  }, [staffUser]);
  // Set when a global-search result is clicked, so the destination page
  // knows exactly which row to scroll to and flash — not just which tab to
  // open. `nonce` forces the effect on the receiving page to re-fire even
  // when the same result is clicked twice in a row (same key, same page).
  const [searchTarget, setSearchTarget] = useState(null);
  const [tabConfig, setTabConfig] = useState(loadTabConfig);
  const [tabOrder, setTabOrder] = useState(loadTabOrder);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [detailsOpen, setDetailsOpen] = useState(false);
  const [detailsTab, setDetailsTab] = useState(null);
  // Bumped when staff change "Preview plan" so access re-resolves.
  const [previewPlanRev, setPreviewPlanRev] = useState(0);
  // Open document requests for the selected client: drives the "your
  // bookkeeper needs…" banner and the Documents dot in the sidebar.
  const docRequestsList = useStaffToolList(
    (sb, id) => staffToolsApi.docRequests(sb, id),
    selectedClientId,
  );
  const openDocRequests = docRequestsList.rows.filter((r) => r.status === "open");
  // Next year's budget waiting on the client's approval (Pro budget tools).
  const [budgetAwaiting, setBudgetAwaiting] = useState(null);
  useEffect(() => {
    const sb = window.mgbSupabase;
    if (!sb || !selectedClientId) return setBudgetAwaiting(null);
    let alive = true;
    const load = () =>
      sb
        .from("client_budget_drafts")
        .select("fiscal_year, version, submitted_by, submitted_at")
        .eq("client_id", selectedClientId)
        .eq("status", "submitted")
        .order("fiscal_year", { ascending: false })
        .limit(1)
        .then(({ data, error }) => alive && setBudgetAwaiting(error ? null : (data || [])[0] || null));
    load();
    window.addEventListener(STAFF_TOOLS_EVENT, load);
    return () => {
      alive = false;
      window.removeEventListener(STAFF_TOOLS_EVENT, load);
    };
  }, [selectedClientId]);
  // Read state and live threads are both keyed "<clientId>::<userId>", since
  // every person at an organization has their own private thread.
  const [readMessageClients, setReadMessageClients] = useState({});
  const [viewAsUserId, setViewAsUserId] = useState(BOOKKEEPER_VIEW);
  const [userAccess, setUserAccess] = useState({});
  const [referralPromo, setReferralPromo] = useState(loadReferralPromo);
  // null until the header toggle is used, at which point it pins the choice
  // (see the effects below). Null means dark — the product default.
  const [theme, setTheme] = useState(loadTheme);

  // §149/§161: automatic light/dark default, following the OS setting.
  // Seeds synchronously from the same reader index.html's pre-hydration
  // script uses, so the first paint already agrees and there is nothing to
  // refine afterward. Never runs at all once `theme` holds an explicit
  // choice — that always wins, this only ever supplies the default.
  const [autoTheme, setAutoTheme] = useState(systemOrClockTheme);
  useEffect(() => {
    if (theme) return;
    setAutoTheme(systemOrClockTheme());

    // The OS preference is authoritative and changes live (macOS/Windows/iOS
    // all flip it on their own schedules), so listen rather than poll.
    const mq =
      typeof window.matchMedia === "function"
        ? window.matchMedia("(prefers-color-scheme: dark)")
        : null;
    const onSchemeChange = () => setAutoTheme(systemOrClockTheme());
    if (mq && mq.addEventListener)
      mq.addEventListener("change", onSchemeChange);

    // Only matters on the clock fallback — a machine that states a preference
    // never reaches the branch this refreshes. Cheap enough to leave running.
    const interval = setInterval(
      () => setAutoTheme(systemOrClockTheme()),
      900000,
    );
    return () => {
      clearInterval(interval);
      if (mq && mq.removeEventListener)
        mq.removeEventListener("change", onSchemeChange);
    };
  }, [theme]);

  const [sidebarCollapsed, setSidebarCollapsed] = useState(() =>
    loadSidebarCollapsed(!!clientPortalUser),
  );
  const toggleSidebarCollapsed = () => {
    setSidebarCollapsed((prev) => {
      const next = !prev;
      try {
        localStorage.setItem(SIDEBAR_COLLAPSED_STORAGE_KEY, next ? "1" : "0");
      } catch (e) {}
      return next;
    });
  };
  const [mobileNavOpen, setMobileNavOpen] = useState(false);
  // A desktop window at half the screen's width or less auto-collapses the
  // sidebar to its icon rail (phones get the hamburger drawer below 760px
  // via CSS instead). Measured against the screen the window is on, so it
  // works the same on a laptop and a big external monitor. The expand
  // button still works there, for that stretch only; it doesn't change the
  // saved full-width preference.
  // Mouse/trackpad only: touch devices (phones) keep the hamburger drawer.
  const isHalfScreenWindow = () => {
    const screenW = (window.screen && (window.screen.availWidth || window.screen.width)) || 0;
    const finePointer =
      !window.matchMedia || window.matchMedia("(hover: hover) and (pointer: fine)").matches;
    return finePointer && screenW > 0 && window.innerWidth <= screenW / 2 + 1;
  };
  const [halfScreen, setHalfScreen] = useState(isHalfScreenWindow);
  const [halfScreenExpanded, setHalfScreenExpanded] = useState(false);
  useEffect(() => {
    const onResize = () => {
      const next = isHalfScreenWindow();
      setHalfScreen((prev) => {
        if (prev !== next) setHalfScreenExpanded(false);
        return next;
      });
    };
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
  }, []);
  const [messagesByClient, setMessagesByClient] = useState({});
  // Purely client-side "is typing" flag for the simulated bookkeeper reply
  // below — there's no real backend for this thread (see MockBanner on
  // MessagesPage), so this just mirrors the same 900ms window the reply
  // already waits, rather than faking a live Realtime channel.
  const [bookkeeperTyping, setBookkeeperTyping] = useState(false);
  const [chatWidgetOpen, setChatWidgetOpen] = useState(false);
  // Staff chat drawer (components/inbox/StaffInbox.jsx): null when closed,
  // else {clientId} — the client whose threads it opens on, if any.
  const [siDrawer, setSiDrawer] = useState(null);
  // The person "Open client" in the inbox asked for, opened on that client's
  // Messages tab.
  const [inboxFocusEmail, setInboxFocusEmail] = useState(null);
  // Which person's thread the bookkeeper is reading (clients only ever see
  // their own, so this is unused while previewing as someone).
  const [bookkeeperThreadUserId, setBookkeeperThreadUserId] = useState(null);

  // Which clients THIS staffer may see. null means "unrestricted", and is now
  // set ONLY for an admin, for whom assignment genuinely never applies.
  //
  // This used to fail OPEN: a non-admin started at null and stayed there if
  // the staff_client_access fetch errored or was simply slow, and null reads
  // downstream as "see every client". A bookkeeper only had to make that one
  // request fail — devtools request blocking, an offline blip, a migration
  // not yet run — to get the entire firm's client roster in their switcher.
  // A non-admin now starts at an empty Set and is widened only by a
  // successful fetch, so a broken query shows nothing rather than everything.
  const [assignedClientIds, setAssignedClientIds] = useState(null);
  // Distinguishes "an admin assigned you no clients" (fine, expected) from
  // "we couldn't find out what you're assigned to" (not fine, say so).
  const [clientAccessError, setClientAccessError] = useState(false);

  // Lets an admin see the app exactly as one specific bookkeeper would —
  // their assigned clients, their Home rollups, their own private reminders
  // — without needing that person's Google login. Set from the roster's
  // "View as" button (StaffAccessPage) and cleared from the banner below.
  // Only ever holds a {email, name, role} row from the staff table, never
  // the real admin's own — nothing here touches Supabase auth, so writes
  // made while impersonating (a note, a reminder) still carry the real
  // signed-in admin's session for RLS purposes; only what's DISPLAYED and
  // which rows get READ (assigned clients, that person's own reminders)
  // change.
  const [impersonating, setImpersonating] = useState(null);
  const effectiveStaffUser = impersonating || staffUser;

  const startImpersonating = (row) => {
    if (typeof AL_logEvent === "function") AL_logEvent("view_as.start", null, { target: row.email, name: row.name });
    setImpersonating({ email: row.email, name: row.name, role: row.role });
    setPage("today");
  };
  const stopImpersonating = () => {
    if (impersonating && typeof AL_logEvent === "function")
      AL_logEvent("view_as.stop", null, { target: impersonating.email, name: impersonating.name });
    setImpersonating(null);
    setPage("today");
  };

  useEffect(() => {
    setClientAccessError(false);
    // Nothing to scope for a signed-in client — they only ever have their
    // own one client_id, not a list to filter. An admin is genuinely
    // unrestricted, so null is correct for them and only for them.
    if (!effectiveStaffUser || effectiveStaffUser.role === "admin") {
      setAssignedClientIds(null);
      return;
    }
    // Fail closed: a non-admin sees nothing until a successful fetch says
    // otherwise. This covers the in-flight window as well as the error path.
    setAssignedClientIds(new Set());
    const supabase = window.mgbSupabase;
    if (!supabase) {
      setClientAccessError(true);
      return;
    }
    supabase
      .from("staff_client_access")
      .select("client_id")
      .eq("staff_email", effectiveStaffUser.email)
      .then(({ data, error }) => {
        if (error) {
          console.warn(
            "Couldn't load client access (staff-client-access.sql may not be run yet):",
            error.message,
          );
          setClientAccessError(true);
          return;
        }
        setAssignedClientIds(new Set(data.map((r) => r.client_id)));
      })
      .catch((err) => {
        // A network-level rejection (as opposed to a query error, which
        // arrives in the {data, error} tuple above) left this as an
        // unhandled rejection before. assignedClientIds stays the empty Set
        // set above either way, so the failure is closed, not open.
        console.warn("Couldn't load client access:", err);
        setClientAccessError(true);
      });
  }, [
    effectiveStaffUser && effectiveStaffUser.email,
    effectiveStaffUser && effectiveStaffUser.role,
  ]);

  // An admin can grant a non-admin bookkeeper temporary, time-limited
  // visibility into the three admin-only pages (Staff Access, Client
  // Roster, Developer Tools) — see supabase/staff-temp-admin-access.sql and
  // StaffAccessPage's "Temp admin access" column. This is READ against the
  // real signed-in staffUser, not effectiveStaffUser/impersonation — an
  // admin previewing "as" a bookkeeper already sees every page as
  // themselves, and impersonation is explicitly excluded from the admin
  // pages below regardless (see effectivePage).
  const [tempAdminAccessExpiresAt, setTempAdminAccessExpiresAt] =
    useState(null);

  useEffect(() => {
    setTempAdminAccessExpiresAt(null);
    if (!staffUser || staffUser.role === "admin") return;
    const supabase = window.mgbSupabase;
    if (!supabase) return;
    supabase
      .from("staff_temp_admin_access")
      .select("expires_at")
      .eq("staff_email", staffUser.email)
      .maybeSingle()
      .then(({ data, error }) => {
        if (error) {
          console.warn(
            "Couldn't load temp admin access (staff-temp-admin-access.sql may not be run yet):",
            error.message,
          );
          return;
        }
        setTempAdminAccessExpiresAt(data ? data.expires_at : null);
      });
  }, [staffUser && staffUser.email, staffUser && staffUser.role]);

  // Forces a re-render once a minute so a live temp-access grant actually
  // stops working (and the expiry banner counts down) close to the moment
  // it expires, rather than only on the next unrelated state change.
  const [, retickTempAccess] = useState(0);
  useEffect(() => {
    if (!tempAdminAccessExpiresAt) return;
    const id = setInterval(() => retickTempAccess((v) => v + 1), 60000);
    return () => clearInterval(id);
  }, [tempAdminAccessExpiresAt]);

  const hasTempAdminAccess = Boolean(
    tempAdminAccessExpiresAt &&
    new Date(tempAdminAccessExpiresAt).getTime() > Date.now(),
  );

  // Clients flagged `testOnly` in data.js (currently just the Grace
  // Community sample/test profile) are hidden from regular bookkeeper
  // logins — sample data shouldn't show up on their roster once real
  // clients are assigned. Any admin can still see it (admins already skip
  // the staff_client_access filter below and see every real client too).
  // This is separate from (and applies on top of) that assignment filter.
  // Bumped by the header's Sync now button after it re-maps window.CLIENTS
  // (index.html's loadQboData), so visibleClients — and baseClient under it —
  // pick up the fresh QuickBooks numbers without a page reload.
  const [qboDataRev, setQboDataRev] = useState(0);
  // Something outside App re-read QuickBooks data into window.CLIENTS (the
  // Giving accounts picker in Client details): pick it up.
  useEffect(() => {
    const onReloaded = () => setQboDataRev((r) => r + 1);
    window.addEventListener("mgb-qbo-reloaded", onReloaded);
    return () => window.removeEventListener("mgb-qbo-reloaded", onReloaded);
  }, []);
  // Clients reachable through a live temporary grant (ClientSwitcher.jsx),
  // so an approval shows up without a reload and an expiry drops out.
  const liveGrantClientIds = CS_useLiveGrantClientIds(staffUser, effectiveStaffUser);
  const visibleClients = useMemo(() => {
    const base = assignedClientIds
      ? CLIENTS.filter(
          (c) => assignedClientIds.has(c.id) || liveGrantClientIds.has(c.id),
        )
      : CLIENTS;
    // An explicit assignment overrides testOnly: an admin who checks a
    // test client off for someone means for them to see it.
    return base.filter(
      (c) =>
        !c.testOnly ||
        (effectiveStaffUser && effectiveStaffUser.role === "admin") ||
        (assignedClientIds && assignedClientIds.has(c.id)),
    );
  }, [assignedClientIds, liveGrantClientIds, effectiveStaffUser && effectiveStaffUser.role, qboDataRev]);

  // §140: in-app-only substitute for the "email me on every access request"
  // idea from HANDOFF7.md's smaller-open-items list — no inbox noise, just
  // a dot on "Manage access" (Sidebar) that lights up when any client this
  // staffer can see has an unreviewed access_requests row. Re-checked on
  // every page change, same trigger as checkStaffMessagesUnread above, so
  // triaging a request in a client's "Manage access" > Requests tab and
  // navigating away clears it without a manual refresh. Declared after
  // visibleClients (not up near checkStaffMessagesUnread) since it reads
  // that value directly.
  // §169: this used to be a single firm-wide boolean, which made the
  // "Manage access" button's glow lie. The glow counted unreviewed requests
  // across EVERY visible client, but the modal it opens is scoped to the
  // selected one — so a request belonging to another client pulsed the
  // button, showed an empty Requests tab when clicked, and kept pulsing.
  //
  // Now it is a per-client count. The button glows only when the CURRENT
  // client has something, so clicking it always shows what the glow promised;
  // the other clients' requests surface in the client picker instead, which
  // is the control you would use to get to them. Keeping only the per-client
  // glow would have hidden them entirely — this is the only place in the app
  // that surfaces access requests at all (Bookkeeper Home does not).
  const [pendingRequestsByClient, setPendingRequestsByClient] = useState({});
  const checkPendingAccessRequests = useCallback(() => {
    const supabase = window.mgbSupabase;
    if (!supabase || !staffUser) {
      setPendingRequestsByClient({});
      return;
    }
    const ids = visibleClients.map((c) => c.id);
    if (ids.length === 0) {
      setPendingRequestsByClient({});
      return;
    }
    // Rows rather than a head-only count, since the counts are now per
    // client. Access requests are low-volume by nature — one row per
    // submitted form, cleared as they are reviewed — so this stays small.
    supabase
      .from("access_requests")
      .select("client_id")
      .eq("reviewed", false)
      .in("client_id", ids)
      .then(({ data, error }) => {
        if (error || !data) {
          setPendingRequestsByClient({});
          return;
        }
        const counts = {};
        data.forEach((row) => {
          counts[row.client_id] = (counts[row.client_id] || 0) + 1;
        });
        setPendingRequestsByClient(counts);
      });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [staffUser, visibleClients.map((c) => c.id).join(",")]);

  // What the glowing button promises: something to see for THIS client.
  const hasPendingAccessRequests =
    (pendingRequestsByClient[selectedClientId] || 0) > 0;
  useEffect(() => {
    checkPendingAccessRequests();
  }, [checkPendingAccessRequests, page]);

  // Manual client health overrides (client_status_overrides), keyed by
  // client_id — fetched once for any signed-in staff member so both the
  // sidebar client picker and Bookkeeper Home's "Your clients" card can show
  // the same status dot without each fetching it separately. Refetched via
  // loadStatusOverrides after a save so a change shows up immediately.
  const [statusOverrides, setStatusOverrides] = useState({});
  const loadStatusOverrides = useCallback(() => {
    const supabase = window.mgbSupabase;
    if (!supabase || !effectiveStaffUser) return;
    supabase
      .from("client_status_overrides")
      .select("client_id, status, note, set_by, updated_at")
      .then(({ data, error }) => {
        if (error || !data) return;
        const map = {};
        data.forEach((row) => {
          map[row.client_id] = row;
        });
        setStatusOverrides(map);
      });
  }, [effectiveStaffUser]);
  useEffect(() => {
    loadStatusOverrides();
  }, [loadStatusOverrides]);

  const saveReferralPromo = (text) => {
    setReferralPromo(text);
    try {
      localStorage.setItem(REFERRAL_PROMO_STORAGE_KEY, text);
    } catch (e) {}
  };

  // Sending a message updates one person's thread, so the full Messages page
  // and the floating chat widget always agree on what's there.
  const sendMessage = (clientId, userId, text, attachment) => {
    const today = todayLocal();
    const key = threadKeyFor(clientId, userId);
    const seedFor = () => seedThread(clientId, userId);
    // The thread belongs to one person, but the bookkeeper can also write into
    // it while previewing, so record who actually composed the message.
    const author = (access.user && access.user.name) || "You";
    setMessagesByClient((prev) => ({
      ...prev,
      [key]: [
        ...(prev[key] || seedFor()),
        { from: "client", author, date: today, text, attachment },
      ],
    }));
    setBookkeeperTyping(true);
    setTimeout(() => {
      setBookkeeperTyping(false);
      setMessagesByClient((prev) => ({
        ...prev,
        [key]: [
          ...(prev[key] || seedFor()),
          {
            from: "bookkeeper",
            author: "MyGoodBooks",
            date: today,
            text: "Thanks for the note — this is a sample thread, so replies here are simulated. In the real product, your bookkeeper will respond here directly.",
          },
        ],
      }));
    }, 900);
  };

  // The inbox's sample fallback writes into the same threads, so a staff
  // reply shows up when previewing as that person.
  const sampleInboxSend = (clientId, userId, msg) => {
    const key = threadKeyFor(clientId, userId);
    setMessagesByClient((prev) => ({
      ...prev,
      [key]: [...(prev[key] || seedThread(clientId, userId)), msg],
    }));
  };
  // Inbox "Open client": that client's Messages tab, on that person.
  const openClientMessages = (clientId, email) => {
    setSiDrawer(null);
    setInboxFocusEmail(email || null);
    if (clientId !== selectedClientId) pageAfterClientSwitch.current = "messages";
    setSelectedClientId(clientId);
    setPage("messages");
  };

  // Remember the tab across refreshes. Stores the raw `page` rather than
  // `effectivePage`: if a bookkeeper is previewing as someone without access to
  // the current tab, the render falls back to the dashboard, but their own
  // choice should survive exiting the preview.
  useEffect(() => {
    try {
      localStorage.setItem(PAGE_STORAGE_KEY, page);
    } catch (e) {}
  }, [page]);

  useEffect(() => {
    try {
      localStorage.setItem(SELECTED_CLIENT_STORAGE_KEY, selectedClientId);
    } catch (e) {}
  }, [selectedClientId]);

  useEffect(() => {
    try {
      localStorage.setItem(TAB_CONFIG_STORAGE_KEY, JSON.stringify(tabConfig));
    } catch (e) {}
  }, [tabConfig]);

  useEffect(() => {
    try {
      localStorage.setItem(TAB_ORDER_STORAGE_KEY, JSON.stringify(tabOrder));
    } catch (e) {}
  }, [tabOrder]);

  // §149 hotfix: this effect is what actually syncs data-theme onto <html> —
  // every CSS rule in styles.css keys off that attribute, not off React
  // state directly. It was left depending on `theme` alone (falling back to
  // a hardcoded "dark") when autoTheme/effectiveTheme were introduced,
  // which made the whole sunrise/sunset feature a no-op: the instant React
  // mounted, this effect re-ran with theme still null and stomped
  // index.html's correct clock-heuristic first paint back to dark, then
  // stayed dark all day regardless of autoTheme — while the toggle
  // button's icon (driven by effectiveTheme) visibly disagreed with the
  // actual theme on screen. Depends on effectiveTheme now, computed above
  // it instead of below.
  const effectiveTheme = theme || autoTheme;

  // Settings (components/settings/Settings.jsx): personal settings load for
  // whoever is signed in. The theme picked there (or with a theme toggle)
  // is saved to the account; the saved one is adopted once it loads.
  const settingsEmail = clientPortalUser ? clientPortalUser.email : staffUser && staffUser.email;
  useEffect(() => {
    ST_store.init(settingsEmail, clientPortalUser ? "client" : "staff");
  }, [settingsEmail, clientPortalUser]);
  const stSnap = ST_useSettings();
  const adoptedThemeGen = useRef(null);
  useEffect(() => {
    if (stSnap.status !== "ready" || adoptedThemeGen.current === stSnap.generation) return;
    adoptedThemeGen.current = stSnap.generation;
    const saved = stSnap.settings.theme;
    if (saved === "light" || saved === "dark" || saved === null) setTheme(saved);
  }, [stSnap.status, stSnap.generation]);
  const chooseTheme = (t) => {
    setTheme(t);
    ST_store.update({ theme: t });
  };

  useEffect(() => {
    document.documentElement.setAttribute("data-theme", effectiveTheme);
    try {
      if (theme) localStorage.setItem(THEME_STORAGE_KEY, theme);
      else localStorage.removeItem(THEME_STORAGE_KEY);
    } catch (e) {}
  }, [theme, effectiveTheme]);

  const baseClient = useMemo(
    () =>
      visibleClients.find((c) => c.id === selectedClientId) ||
      visibleClients[0] ||
      CLIENTS[0],
    [selectedClientId, visibleClients],
  );

  // A restricted bookkeeper's selectedClientId can point at a client that
  // isn't (or is no longer) assigned to them — the very first render before
  // assignedClientIds loads, or an admin having just unchecked one out from
  // under them. baseClient above already falls back safely so nothing
  // crashes, but this brings the URL/localStorage-persisted selection back
  // in sync once we know the real list.
  useEffect(() => {
    if (visibleClients.length === 0) return;
    if (!visibleClients.find((c) => c.id === selectedClientId)) {
      setSelectedClientId(visibleClients[0].id);
    }
  }, [visibleClients]);

  // Apply any access edits the bookkeeper made in this session on top of the
  // access records that ship with the data.
  const client = useMemo(() => {
    if (!baseClient.users) return baseClient;
    return {
      ...baseClient,
      users: baseClient.users.map((u) =>
        userAccess[u.id] ? { ...u, ...userAccess[u.id] } : u,
      ),
    };
  }, [baseClient, userAccess]);

  // The server syncs QuickBooks on each plan's schedule (qbo-sync's
  // isDueForPlan: Pro every 15 minutes, Basic on the 15th; see
  // PLAN_SYNC), and a staffer or another tab can Sync now at any time, but
  // the page only loaded the numbers once. Once a minute: re-render so the
  // "synced x ago" label ticks. Separately, spaced by plan, ask
  // qbo_connections for this client's last_synced_at (one tiny row) and only
  // when it has moved past what's on screen re-read all the numbers (the
  // same reload Sync now uses; no QuickBooks call). Pro checks every 2
  // minutes, Basic every 15. Also on returning to the tab.
  const [, setClockTick] = useState(0);
  const qboAutoReloadRef = useRef(0);
  useEffect(() => {
    const spacing = client.plan === "premium" ? 2 * 60 * 1000 : 15 * 60 * 1000;
    const check = async () => {
      setClockTick((t) => t + 1);
      if (document.hidden) return;
      const sb = window.mgbSupabase;
      if (client.dataSource !== "quickbooks" || !window.mgbReloadQboData || !sb) return;
      if (Date.now() - qboAutoReloadRef.current < spacing) return;
      qboAutoReloadRef.current = Date.now();
      const { data, error } = await sb
        .from("qbo_connections")
        .select("last_synced_at")
        .eq("client_id", client.id)
        .maybeSingle();
      if (error || !data || !data.last_synced_at) return;
      const onScreen = client.lastSyncedAt ? new Date(client.lastSyncedAt).getTime() : 0;
      if (new Date(data.last_synced_at).getTime() <= onScreen) return;
      await window.mgbReloadQboData([client.id]);
      setQboDataRev((r) => r + 1);
      notifyMilestonesChanged();
    };
    const id = setInterval(check, 60 * 1000);
    const onVisible = () => {
      if (!document.hidden) check();
    };
    document.addEventListener("visibilitychange", onVisible);
    return () => {
      clearInterval(id);
      document.removeEventListener("visibilitychange", onVisible);
    };
  }, [client.id, client.dataSource, client.lastSyncedAt, client.plan]);

  // Switching client resets the preview — a person at one org is meaningless at another.
  // Also lands on Dashboard for the newly-selected client (Live Report for a
  // premium, full-access client; the plain Dashboard otherwise) rather than
  // keeping whatever tab happened to be open for the PREVIOUS client — e.g.
  // staying on Report Builder after switching to a standard-plan client that
  // doesn't even have that tab. Skips its own first run so a page refresh
  // still restores the last-viewed tab as before; this only fires on an
  // actual client switch, after mount.
  const skipFirstClientSwitch = useRef(true);
  // Set when something switches client AND asks for a specific page (Home's
  // Milestones to review), so the reset below doesn't bounce it to Dashboard.
  const pageAfterClientSwitch = useRef(null);
  useEffect(() => {
    setViewAsUserId(BOOKKEEPER_VIEW);
    setBookkeeperThreadUserId(null);
    if (skipFirstClientSwitch.current) {
      skipFirstClientSwitch.current = false;
    } else {
      setPage(
        pageAfterClientSwitch.current ||
          (!clientPortalUser ? "client-overview" : "dashboard"),
      );
    }
    pageAfterClientSwitch.current = null;
  }, [selectedClientId]);

  // Client picker "Onboarding 3/5" badge (Onboarding.jsx OB_requestFocus):
  // always land on that client's overview, where the Onboarding card
  // scrolls itself into view.
  useEffect(() => {
    const onFocusOnboarding = (e) => {
      const id = e && e.detail && e.detail.clientId;
      if (!id) return;
      if (id !== selectedClientId) {
        pageAfterClientSwitch.current = "client-overview";
        setSelectedClientId(id);
      }
      setPage("client-overview");
    };
    window.addEventListener("mgb:focus-onboarding", onFocusOnboarding);
    return () => window.removeEventListener("mgb:focus-onboarding", onFocusOnboarding);
  }, [selectedClientId]);

  // Only counts as "visiting" a client while actually looking at one of its
  // pages, not while browsing Home/Staff Access (which don't belong to any
  // client, and would otherwise stamp whatever client was last selected
  // every time someone just checks their reminders).
  useEffect(() => {
    if (NON_CLIENT_PAGES.has(page)) return;
    recordClientVisit(selectedClientId);
  }, [selectedClientId, page]);

  // tabConfig stores HIDDEN keys per client (not visible ones) so that any
  // tab added later in the app defaults to visible for every client, rather
  // than silently staying hidden because it's missing from an old snapshot.
  const visibleKeys = useMemo(() => {
    const hidden = new Set(tabConfig[selectedClientId] || []);
    return new Set(
      ALL_TAB_KEYS.filter((k) => k === ALWAYS_VISIBLE_KEY || !hidden.has(k)),
    );
  }, [tabConfig, selectedClientId]);

  const toggleTab = (key) => {
    if (key === ALWAYS_VISIBLE_KEY) return;
    setTabConfig((prev) => {
      const hidden = new Set(prev[selectedClientId] || []);
      if (hidden.has(key)) hidden.delete(key);
      else hidden.add(key);
      return { ...prev, [selectedClientId]: Array.from(hidden) };
    });
  };

  const reorderTab = (sectionLabel, fromKey, toKey) => {
    setTabOrder((prev) => {
      const section = NAV_SECTIONS.find((s) => s.label === sectionLabel);
      const currentOrder =
        (prev[selectedClientId] && prev[selectedClientId][sectionLabel]) ||
        section.items.map((i) => i.key);
      const withoutFrom = currentOrder.filter((k) => k !== fromKey);
      const toIndex = withoutFrom.indexOf(toKey);
      withoutFrom.splice(toIndex, 0, fromKey);
      return {
        ...prev,
        [selectedClientId]: {
          ...(prev[selectedClientId] || {}),
          [sectionLabel]: withoutFrom,
        },
      };
    });
  };

  const toggleUserPremium = (userId) => {
    const user = client.users.find((u) => u.id === userId);
    setUserAccess((prev) => {
      const current =
        prev[userId] && "premiumThrottled" in prev[userId]
          ? prev[userId].premiumThrottled
          : Boolean(user.premiumThrottled);
      return {
        ...prev,
        [userId]: { ...(prev[userId] || {}), premiumThrottled: !current },
      };
    });
  };

  const setAccessLevel = (userId, level) => {
    setUserAccess((prev) => ({
      ...prev,
      [userId]: {
        ...(prev[userId] || {}),
        access: level,
        ...(level === "full" ? { categories: null, tabs: null } : {}),
      },
    }));
  };

  const toggleUserTab = (userId, key) => {
    if (key === ALWAYS_VISIBLE_KEY) return;
    const user = client.users.find((u) => u.id === userId);
    setUserAccess((prev) => {
      const current = new Set(
        (prev[userId] && prev[userId].tabs) || user.tabs || ALL_TAB_KEYS,
      );
      if (current.has(key)) current.delete(key);
      else current.add(key);
      return {
        ...prev,
        [userId]: {
          ...(prev[userId] || {}),
          tabs: ALL_TAB_KEYS.filter((k) => current.has(k)),
        },
      };
    });
  };

  const toggleUserCategory = (userId, category) => {
    const user = client.users.find((u) => u.id === userId);
    setUserAccess((prev) => {
      const current = new Set(
        (prev[userId] && prev[userId].categories) || user.categories || [],
      );
      if (current.has(category)) current.delete(category);
      else current.add(category);
      const next = Array.from(current);
      return {
        ...prev,
        [userId]: {
          ...(prev[userId] || {}),
          categories: next.length ? next : null,
        },
      };
    });
  };

  // Unlike categories, an empty fund list stays an empty list (stored as
  // null, same "nothing set" representation) rather than falling back to
  // every fund — see the comment on resolveAccess's funds line.
  const toggleUserFund = (userId, fundName) => {
    const user = client.users.find((u) => u.id === userId);
    setUserAccess((prev) => {
      const current = new Set(
        (prev[userId] && prev[userId].funds) || user.funds || [],
      );
      if (current.has(fundName)) current.delete(fundName);
      else current.add(fundName);
      const next = Array.from(current);
      return {
        ...prev,
        [userId]: { ...(prev[userId] || {}), funds: next.length ? next : null },
      };
    });
  };

  // Normalized to the same shape a client.users mock entry has — see
  // resolveAccess's overrideUser param.
  const portalOverrideUser = useMemo(
    () =>
      clientPortalUser
        ? {
            id: clientPortalUser.email,
            name: clientPortalUser.name,
            role: clientPortalUser.role,
            access: clientPortalUser.access || "full",
            tabs: clientPortalUser.tabs,
            categories: clientPortalUser.categories,
            funds: clientPortalUser.funds,
            premiumThrottled: clientPortalUser.premium_throttled,
          }
        : null,
    [clientPortalUser],
  );

  const access = useMemo(
    () =>
      resolveAccess(
        client,
        viewAsUserId,
        new Set(tabConfig[selectedClientId] || []),
        portalOverrideUser,
      ),
    // previewPlanRev: staff "Preview plan" is read inside resolveAccess.
    [client, viewAsUserId, tabConfig, selectedClientId, portalOverrideUser, previewPlanRev],
  );

  const scopedClient = useMemo(
    () => scopeClientData(client, access),
    [client, access],
  );

  // The staff places (today, inbox, work, clients, team), "help",
  // "enterprise-upgrade", "client-access"/"developer-tools"/... and the
  // staff-only "sop" tab are synthetic pages, not real client tabs — none
  // is in ALL_TAB_KEYS/access.tabs, so each needs its own bypass here or
  // the normal fallback would bounce it straight back to the dashboard.
  // The admin pages additionally require the role, matching the links that
  // are the only way to reach them — Postgres RLS is the real enforcement
  // for Team > Members (see supabase/staff-admin-policies.sql) and
  // developer-tools only ever touches this browser's own localStorage, but
  // the page-level gate still keeps a demoted admin's stale stored page
  // from rendering either. Inbox, Work, Team and Help are open to any staff
  // role (a bookkeeper has their own thread, tasks and reviews too) but,
  // like the admin pages, unreachable while impersonating — "view as" is
  // about seeing a bookkeeper's CLIENT-facing view, and whose Team Chat
  // thread or task list should show during that (the real admin's, or the
  // impersonated bookkeeper's) has no clean answer, so it's simplest to
  // just not offer them mid-impersonation. Today and Clients stay, so the
  // admin can still get around while viewing as someone.
  // A staff session asking for a key this build doesn't know (a stale
  // stored page from before the 2026-10-08 nav redesign) lands on Today,
  // never on a client's Dashboard.
  // Where a client lands: Home ("dashboard"), on every plan.
  const homeTab = access.tabs.has(ALWAYS_VISIBLE_KEY)
    ? ALWAYS_VISIBLE_KEY
    : access.tabs.has("reports")
      ? "reports"
      : [...access.tabs][0] || ALWAYS_VISIBLE_KEY;
  // Settings (components/settings/Settings.jsx): "settings" is the staff
  // page; "client-settings" is the client's (and, in the bookkeeper view,
  // staff get its Client settings + Plan tabs). The old Plans, Manage access
  // and Client details page ids are aliases for a tab of it.
  const effectivePage =
    page === "settings" && staffUser && !clientPortalUser
      ? page
      : page === "client-settings" ||
          page === "enterprise-upgrade" ||
          page === "manage-access" ||
          page === "client-details"
        ? "client-settings"
      : (page === "client-access" ||
            page === "developer-tools" ||
            page === "usage-stats" ||
            page === "task-templates") &&
          staffUser &&
          (staffUser.role === "admin" || hasTempAdminAccess) &&
          !impersonating
        ? page
        : (page === "audit-log" || page === "emails") && staffUser && staffUser.role === "admin" && !impersonating
          ? page
        : (page === "inbox" || page === "work" || page === "team" || page === "help") && staffUser && !impersonating
          ? page
        : (page === "today" || page === "clients") && staffUser
          ? page
        : page === "client-overview" &&
            !clientPortalUser &&
            viewAsUserId === BOOKKEEPER_VIEW
          ? page
        : page === "sop" &&
            !clientPortalUser &&
            staffUser &&
            !(viewAsUserId !== BOOKKEEPER_VIEW && access.user) &&
            client
          ? page
        : page === "milestone" && !access.isCategoryScoped
          ? page
        : access.tabs.has(page)
          ? page
        : staffUser && !clientPortalUser && !isKnownAppPage(page)
          ? "today"
          : homeTab;

  // §135: one row per page view, staff and client alike, so Usage Stats
  // (admin-only) can rank pages most-to-least used. Fires on effectivePage
  // rather than page so it reflects what actually rendered, not a page key
  // that got bounced by the access checks above. Impersonation logs under
  // the real staffUser doing the impersonating (not the impersonated
  // bookkeeper) since that's whose browser/session generated the view.
  // Fire-and-forget: a logging failure should never surface to the viewer.
  // A tab switch inside a hub (#/work/tasks → #/work/close) counts as its
  // own view, so Usage Stats can tell the tabs apart.
  const [usageTab, setUsageTab] = useState(() => MGB_currentTab(effectivePage));
  useEffect(() => {
    const onHash = () => setUsageTab(MGB_currentTab(effectivePage));
    window.addEventListener("hashchange", onHash);
    window.addEventListener("mgb-tabchange", onHash); // NAV_useHashSub.setSub
    return () => {
      window.removeEventListener("hashchange", onHash);
      window.removeEventListener("mgb-tabchange", onHash);
    };
  }, [effectivePage]);
  useEffect(() => {
    const supabase = window.mgbSupabase;
    const actorEmail = clientPortalUser
      ? clientPortalUser.email
      : staffUser && staffUser.email;
    const role = clientPortalUser ? "client" : "staff";
    // Shared with MGB_track / MGB_reportError, which fire outside React.
    window.__mgbActor = actorEmail
      ? { email: actorEmail, role, page: effectivePage }
      : null;
    if (!supabase || effectivePage === "usage-stats") return;
    if (!actorEmail) return;
    const usagePlaceAll = CLIENT_placeOf(effectivePage);
    const usagePlace = usagePlaceAll && usagePlaceAll.tabs ? usagePlaceAll : null;
    CLIENT_rememberTab(effectivePage);
    supabase
      .from("usage_events")
      .insert({
        actor_email: actorEmail,
        actor_role: role,
        client_id: NON_CLIENT_PAGES.has(effectivePage)
          ? null
          : selectedClientId,
        // A tabbed client place logs as place › tab (finances › bank).
        page: usagePlace ? usagePlace.key : effectivePage,
        tab: usagePlace ? effectivePage : MGB_currentTab(effectivePage),
        device: MGB_deviceKind(),
      })
      .then(({ error }) => {
        if (error) console.warn("Couldn't log usage event:", error.message);
      });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [effectivePage, usageTab]);

  // Keep the URL hash in step with what's actually on screen (effectivePage,
  // so a bounced deep link shows where the viewer really landed). pushState /
  // replaceState rather than assigning location.hash: no hashchange event
  // back into the listener below.
  const [hashRewriteTick, setHashRewriteTick] = useState(0);
  // Set by the hashchange listener so the rewrite it triggers replaces
  // rather than pushes.
  const hashFromHistory = useRef(false);
  useEffect(() => {
    try {
      if (isAuthHash(window.location.hash)) return;
      const next = buildHashRoute(effectivePage, selectedClientId);
      const fromHistory = hashFromHistory.current;
      hashFromHistory.current = false;
      if (next && window.location.hash !== next) {
        const url = window.location.pathname + window.location.search + next;
        // One history entry per page, in the browser and the installed app
        // alike (staff nav redesign 2026-10-08): Back from a client's pages
        // returns to the Clients list, and AN_AppNav's Back has something
        // to walk. Not for the first route on load, or when Back/Forward
        // itself changed the hash (that would bury the entry it went back
        // to). Tab changes inside a place (#/work/close) don't come through
        // here — NAV_useHashSub replaces in place.
        if (!fromHistory && parseHashRoute(window.location.hash)) {
          window.history.pushState({ mgbNav: AN_navIndex() + 1 }, "", url);
          window.dispatchEvent(new Event("mgb-nav"));
        } else {
          window.history.replaceState(window.history.state, "", url);
        }
      }
    } catch (e) {}
    // `page` too: a bounced request (page changes, effectivePage doesn't)
    // must still rewrite the hash back to what's shown.
  }, [effectivePage, selectedClientId, page, hashRewriteTick]);

  // A hash typed or pasted into the address bar of an already-open tab.
  useEffect(() => {
    const onHashChange = () => {
      const route = parseHashRoute(window.location.hash);
      if (!route) return;
      hashFromHistory.current = true;
      if (
        route.clientId &&
        !clientPortalUser &&
        route.clientId !== selectedClientId &&
        visibleClients.some((c) => c.id === route.clientId)
      ) {
        pageAfterClientSwitch.current = route.page || "client-overview";
        setSelectedClientId(route.clientId);
      } else if (clientPortalUser && route.page === "settings") {
        setPage("client-settings");
      } else if (route.page && !(clientPortalUser && NON_CLIENT_PAGES.has(route.page))) {
        setPage(route.page);
      }
      if (route.settingsTab) setSettingsTab(route.settingsTab);
      // Re-sync even when nothing changed (a refused page that was already
      // the stored request would otherwise leave its hash in the bar).
      setHashRewriteTick((t) => t + 1);
    };
    window.addEventListener("hashchange", onHashChange);
    return () => window.removeEventListener("hashchange", onHashChange);
  }, [selectedClientId, visibleClients, clientPortalUser]);

  // The manual "My Time" page was retired 2026-09-29 (QuickBooks Time is the
  // hours source). Anyone still holding that page id goes to Today.
  useEffect(() => {
    if (page === "my-time") setPage(staffUser && !clientPortalUser ? "today" : homeTab);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [page]);

  // Automatic in-app time per staff member per client
  // (components/staff/AppTimeTracker.js, supabase/app-time-tracking.sql).
  // Counts only for a real staffer (not a portal client, not an admin in
  // "View as", not previewing the portal as a client user) with a client
  // page open; the tracker itself adds the visible-tab, 2-minute-input and
  // one-tab-per-person checks.
  const appTimeEnabled =
    !!staffUser &&
    !clientPortalUser &&
    !impersonating &&
    viewAsUserId === BOOKKEEPER_VIEW &&
    !NON_CLIENT_PAGES.has(effectivePage);
  const appTimeClientId = client ? client.id : null;
  useEffect(() => {
    if (typeof AT_setTrackingContext === "function") {
      AT_setTrackingContext({ enabled: appTimeEnabled, clientId: appTimeClientId });
    }
  }, [appTimeEnabled, appTimeClientId]);

  // §136: periodic feedback survey (FeedbackSurveyModal) — shown at most
  // once every FEEDBACK_PROMPT_INTERVAL_DAYS per browser. A short delay
  // after mount rather than firing immediately, so it never competes with
  // the boot splash or a fresh login for attention. Skipped entirely while
  // impersonating (same reasoning as Inbox above: unclear whose
  // feedback it would even be) and for a demoted/logged-out viewer with
  // neither staffUser nor clientPortalUser.
  const [feedbackOpen, setFeedbackOpen] = useState(false);
  useEffect(() => {
    if (impersonating) return;
    if (!staffUser && !clientPortalUser) return;
    if (!shouldPromptForFeedback()) return;
    const timer = setTimeout(() => setFeedbackOpen(true), 15000);
    return () => clearTimeout(timer);
  }, [staffUser, clientPortalUser, impersonating]);

  const feedbackFeatureOptions = useMemo(
    () =>
      NAV_SECTIONS.flatMap((section) => section.items).filter((item) =>
        access.tabs.has(item.key),
      ),
    [access.tabs],
  );

  // Each of these six tabs IS its upgraded page for a full-access premium
  // viewer — same pattern for all six now (see PREMIUM_UPGRADE_TAB_KEYS):
  // one nav item, content swapped by plan, rather than a second
  // separately-named tab. "daily-close"/"report-builder"/"budgeting-tool"/
  // "ap-command-center"/"bank-reconciliation"/"fund-accounting-pro" survive
  // as PAGE_META keys purely to supply the header title/subtitle for the
  // upgraded state below — they're no longer reachable page keys of their
  // own (no nav item points at them, and the render switch no longer
  // branches on them directly). Category-scoped premium users still get
  // every plain tab (ORG_WIDE_TABS-equivalent: a live org-wide
  // snapshot/report has no "their" slice to show).
  const showsLiveReport =
    effectivePage === "dashboard" &&
    access.premiumForUser &&
    !access.isCategoryScoped;
  const showsBudgetingTool =
    effectivePage === "budget" &&
    access.premiumForUser &&
    // Ministry-scoped people get the Pro budget page too; it shows them only
    // their own lines (ministry owners). The old page stays org-wide only.
    (!access.isCategoryScoped || typeof ProBudgetWorkspace === "function");
  const showsCashFlowPro =
    effectivePage === "receivables" &&
    access.premiumForUser &&
    !access.isCategoryScoped;
  const showsReportBuilder =
    effectivePage === "reports" &&
    access.premiumForUser &&
    !access.isCategoryScoped;
  const showsReconciliationPro =
    effectivePage === "bank" &&
    access.premiumForUser &&
    !access.isCategoryScoped;
  const showsFundAccountingPro =
    effectivePage === "giving" &&
    access.premiumForUser &&
    !access.isCategoryScoped;
  const meta = showsLiveReport
    ? PAGE_META["daily-close"]
    : showsBudgetingTool
      ? PAGE_META["budgeting-tool"]
      : showsCashFlowPro
        ? PAGE_META["ap-command-center"]
        : showsReportBuilder
          ? PAGE_META["report-builder"]
          : showsReconciliationPro
            ? PAGE_META["bank-reconciliation"]
            : showsFundAccountingPro
              ? PAGE_META["fund-accounting-pro"]
              : PAGE_META[effectivePage];
  // §162: `headerIsPremium` lived here and drove a gold shimmer treatment on
  // the page header and subtitle. Removed — premium pages now use the same
  // dark ink heading as the standard pages. The sidebar's PRO pill is still
  // the plan cue. If a premium header treatment is ever wanted again, the
  // condition was `!NON_CLIENT_PAGES.has(effectivePage) &&
  // access.premiumForUser`.
  const isPreviewingUser = viewAsUserId !== BOOKKEEPER_VIEW && access.user;
  // §166: the single source of truth for "is a staff member driving this
  // session". A client-portal session is never the bookkeeper, whatever the
  // view-as state happens to say.
  const isStaffSession = !clientPortalUser;

  // Customizable boards save to the signed-in account
  // (components/dashboard/WidgetDrawer.jsx). Staff "View as" and client-user
  // preview keep changes on this device only, so they never overwrite the
  // staff member's own saved layouts. Set during render, not in an effect:
  // the boards' own sync effects (children) run before this component's.
  WD_sync.setPaused("view-as", Boolean(impersonating));
  WD_sync.setPaused("preview", Boolean(isStaffSession && isPreviewingUser));
  // Same rule for personal settings (components/settings/Settings.jsx).
  ST_store.setPaused("view-as", Boolean(impersonating));
  ST_store.setPaused("preview", Boolean(isStaffSession && isPreviewingUser));

  // Old entry points for what is now a tab of client Settings.
  useEffect(() => {
    if (page === "enterprise-upgrade") {
      setSettingsTab("plan");
      setPage("client-settings");
    } else if (page === "manage-access" || page === "client-details") {
      setSettingsTab("client");
      setPage("client-settings");
      if (isStaffSession && !isPreviewingUser) {
        if (page === "manage-access") setSettingsOpen(true);
        else {
          setDetailsTab(null);
          setDetailsOpen(true);
        }
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [page]);
  const openClientSettings = (tab) => {
    setSettingsTab(tab || null);
    setPage("client-settings");
  };

  const clientUsers = client.users || [];
  // Audit log: staff previewing the portal as a client user (AuditLog.jsx).
  if (typeof AL_usePortalPreviewLog === "function")
    AL_usePortalPreviewLog(
      isStaffSession && staffUser && isPreviewingUser ? client.id : null,
      isStaffSession && isPreviewingUser ? access.user.email || String(viewAsUserId) : null,
      isStaffSession && isPreviewingUser ? access.user.name : null,
    );

  // Real client messaging (SI_useClientMessaging, components/inbox/). Only
  // "real" once supabase/client-messages.sql answers; until then, and for
  // staff previewing a sample person, the sample threads below carry on.
  // Staff in the bookkeeper view get just the waiting count, for the badge.
  const siRole = clientPortalUser ? "client" : isPreviewingUser ? "preview" : "staff";
  const siMsg =
    typeof SI_useClientMessaging === "function"
      ? SI_useClientMessaging({
          enabled: siRole === "client" || !NON_CLIENT_PAGES.has(effectivePage),
          role: siRole,
          clientId: selectedClientId,
          email: clientPortalUser
            ? clientPortalUser.email
            : isPreviewingUser
              ? access.user.email
              : null,
          name: clientPortalUser ? clientPortalUser.name : null,
          active: effectivePage === "messages",
          refreshKey: effectivePage,
        })
      : MSG_OFF;
  // A signed-in client only ever sees their real thread: while it loads or
  // after an error they get that state (with a retry), and with messaging
  // off a plain "isn't available" note. Never the sample thread, its banner
  // or its simulated bookkeeper replies; those are for the prototype only.
  const siClientReal = siRole === "client";
  const siLive = siMsg.status === "real" || siClientReal;
  const siLiveThread = (siLive && siRole !== "staff") || siClientReal;
  // One chat bubble for staff: the drawer launcher replaces ChatFab.
  const siStaffChat =
    typeof SI_ChatDrawer === "function" &&
    isStaffSession &&
    !!staffUser &&
    !impersonating &&
    !isPreviewingUser;
  useEffect(() => {
    if (!siStaffChat || effectivePage === "inbox") setSiDrawer(null);
  }, [siStaffChat, effectivePage]);
  const siInboxClients = useMemo(() => [client], [client]);

  const threadFor = (userId) =>
    messagesByClient[threadKeyFor(selectedClientId, userId)] ||
    seedThread(selectedClientId, userId);

  // Tracks how many messages were already seen per thread, rather than a plain
  // "read" flag — a flag latches on first visit and would stop every later
  // reply from ever raising the badge or the chat widget again.
  const threadHasUnread = (userId) => {
    const msgs = threadFor(userId);
    return (
      lastMessageFromBookkeeper({ messages: msgs }) &&
      msgs.length >
        (readMessageClients[threadKeyFor(selectedClientId, userId)] || 0)
    );
  };

  const unreadThreadUserIds = siLiveThread
    ? siMsg.unread && access.user
      ? [access.user.id]
      : []
    : clientUsers.filter((u) => threadHasUnread(u.id)).map((u) => u.id);
  // A client sees a badge only for their own thread; the bookkeeper sees one
  // if anybody at the organization is waiting on a reply.
  const hasUnreadMessages = siLive
    ? access.user
      ? siMsg.unread
      : siMsg.waitingCount > 0
    : access.user
      ? unreadThreadUserIds.includes(access.user.id)
      : unreadThreadUserIds.length > 0;

  // A person always reads their own thread. In bookkeeper view there's no
  // signed-in person, so MyGoodBooks picks whose thread to open — and it opens
  // one that's actually waiting. Defaulting to clientUsers[0] meant landing on a
  // thread that was never flagged, marking *that* read while the badge (raised
  // by a different person's thread) stayed lit no matter how often you looked.
  // An explicit pick from the thread picker always wins.
  const activeThreadUserId = access.user
    ? access.user.id
    : bookkeeperThreadUserId ||
      unreadThreadUserIds[0] ||
      (clientUsers[0] && clientUsers[0].id) ||
      null;

  // Internal notes can sit in a sample thread (the inbox's Note mode); they
  // never reach the client view.
  const liveMessages = siLiveThread
    ? siMsg.messages
    : activeThreadUserId
      ? threadFor(activeThreadUserId).filter((m) => !m.internal)
      : [];

  useEffect(() => {
    // effectivePage, not page: when the current tab isn't visible to this viewer
    // the app falls back to the dashboard, and a thread nobody is looking at
    // must not be marked read.
    if (effectivePage === "messages" && activeThreadUserId) {
      const key = threadKeyFor(selectedClientId, activeThreadUserId);
      setReadMessageClients((prev) =>
        prev[key] === liveMessages.length
          ? prev
          : { ...prev, [key]: liveMessages.length },
      );
    }
  }, [
    effectivePage,
    selectedClientId,
    activeThreadUserId,
    liveMessages.length,
  ]);

  // Switching tabs (or clients) should land at the top of the new page, not
  // wherever the previous page happened to be scrolled to — the sidebar is
  // sticky, so it's the window/body that actually scrolls.
  useEffect(() => {
    window.scrollTo({ top: 0, left: 0, behavior: "auto" });
  }, [effectivePage, selectedClientId]);

  useEffect(() => {
    if (isFlagOn(FEATURE_FLAGS[1].key)) {
      console.log("[MyGoodBooks debug]", {
        page: effectivePage,
        clientId: selectedClientId,
      });
    }
  }, [effectivePage, selectedClientId]);

  // The Live Report's data, derived once per client/plan rather than on
  // every App render. Its "As of" label comes from client.lastSyncedAt (the
  // real last QuickBooks sync), not the clock, so nothing needs a timer: the
  // app-wide 30-second re-render that used to live here re-rendered every
  // page just to refresh a relative time. A reload of QuickBooks data swaps
  // the client object, which recomputes this.
  const dailyCloseData = useMemo(
    () =>
      showsLiveReport && client && typeof dailyCloseFromClient === "function"
        ? dailyCloseFromClient(client, access.plan)
        : null,
    [showsLiveReport, client, access.plan],
  );

  // Chart/graph entrance animations (bar fills, the income/expense wipe-in,
  // the account donut, DailyClose's sparklines and anomaly rows) only play
  // once a card actually scrolls into view, rather than the instant a page
  // mounts — and each card gets its own randomized pace, via --reveal-dur,
  // so nothing on the page animates in perfect lockstep. The CSS side (see
  // "Chart entrance animations" in styles.css and DailyClose.css) keeps
  // every animated element in its pre-animation state until an ancestor
  // .card/.dc-kpiTile/.dc-panel carries .in-view. A single observer here
  // covers every page: cards mount and unmount as React swaps pages, so a
  // MutationObserver re-scans for newly-added ones instead of wiring this
  // up per page component.
  useEffect(() => {
    if (typeof IntersectionObserver === "undefined") return;
    const seen = new WeakSet();
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;
          const el = entry.target;
          el.style.setProperty(
            "--reveal-dur",
            Math.round(2550 + Math.random() * 1950) + "ms",
          );
          // A data attribute, not a class: React re-renders these cards often
          // (drag state, widget-layout state, the 30s Live Report tick), and
          // every render recomputes className from scratch, silently wiping
          // an imperatively-added class the next time React commits. React
          // never touches attributes it wasn't told about, so this survives.
          el.setAttribute("data-in-view", "true");
          io.unobserve(el);
        });
      },
      // Reveal as soon as any part of a card enters the viewport (minus a
      // small strip at the bottom, so the cascade still trails the scroll).
      // A ratio threshold like 0.2 can never be met by a card taller than
      // ~5 viewports (a 50-row Bank Accounts transaction list), which left
      // it at opacity 0 until the user scrolled well past it. Cards already
      // on screen at mount get the initial callback and reveal at once.
      { threshold: 0, rootMargin: "0px 0px -8% 0px" },
    );
    const scan = () => {
      // .compare-row: the Enterprise upgrade page's tool-by-tool accordion
      // rows aren't .card elements, so they need their own entry here to
      // pick up data-in-view for the same scroll-reveal treatment.
      document
        .querySelectorAll(".card, .dc-kpiTile, .dc-panel, .compare-row")
        .forEach((el) => {
          if (seen.has(el)) return;
          seen.add(el);
          io.observe(el);
        });
    };
    scan();
    const mo = new MutationObserver(scan);
    mo.observe(document.body, { childList: true, subtree: true });
    return () => {
      io.disconnect();
      mo.disconnect();
    };
  }, []);

  // Masonry spans. .content-masonry is a grid of 4px rows (see styles.css);
  // each card gets grid-row-end: span N covering its measured height plus
  // the 20px gap, and grid auto-placement drops it into the first column
  // where it fits. Re-measured whenever a card's size changes (charts
  // loading, a section expanding) or cards are added, removed or reordered.
  useEffect(() => {
    const ROW = 4;
    const GAP = 20;
    const sizeCard = (card) => {
      if (card.offsetParent === null) return;
      const h = card.getBoundingClientRect().height;
      const span = `span ${Math.max(1, Math.ceil((h + GAP) / ROW))}`;
      if (card.style.gridRowEnd !== span) card.style.gridRowEnd = span;
    };
    const ro =
      typeof ResizeObserver === "undefined"
        ? null
        : new ResizeObserver((entries) => entries.forEach((e) => sizeCard(e.target)));
    const watched = new WeakSet();
    const scan = () => {
      document.querySelectorAll(".content-masonry").forEach((grid) => {
        Array.from(grid.children).forEach((card) => {
          if (!watched.has(card)) {
            watched.add(card);
            if (ro) ro.observe(card);
          }
          sizeCard(card);
        });
      });
    };
    scan();
    const mo = new MutationObserver(scan);
    mo.observe(document.body, { childList: true, subtree: true });
    window.addEventListener("resize", scan);
    return () => {
      if (ro) ro.disconnect();
      mo.disconnect();
      window.removeEventListener("resize", scan);
    };
  }, []);

  // Every prominent stat (KPI tiles, Report Builder's big numbers, fund
  // balances, Live Report's own KPI row) counts up from zero as the page
  // first loads. This works on the already-rendered text rather than routing
  // every number through a component: find the first real text node inside
  // the target, pull the numeric run out of it with a regex, and animate that
  // node's data from 0 up to it, leaving any prefix ("$", "-"), suffix
  // (" mo", "%"), and sibling markup (Live Report's cents <small>)
  // untouched. A value with no number in it (e.g. a runway ring reading
  // "Healthy") is simply left alone.
  //
  // Runs for the life of the whole session, not just the opening moments —
  // every page swap mounts fresh KPI/stat DOM nodes (each page component is
  // conditionally rendered, not kept alive off-screen), so the same
  // MutationObserver-driven scan that catches the first page's numbers
  // catches every later page's too, with no separate re-arming needed.
  // Durations are uniform (not randomised per number) so figures in the same
  // KPI row don't land at visibly different times and read as jitter.
  useEffect(() => {
    const seen = new WeakSet();
    const animate = (textNode, prefix, suffix, target, decimals) => {
      const duration = 650;
      const start = performance.now();
      const fmt = (n) =>
        n.toLocaleString("en-US", {
          minimumFractionDigits: decimals,
          maximumFractionDigits: decimals,
        });
      const frame = (now) => {
        const p = Math.min(1, (now - start) / duration);
        const eased = 1 - Math.pow(1 - p, 3);
        textNode.data = prefix + fmt(target * eased) + suffix;
        if (p < 1) requestAnimationFrame(frame);
      };
      requestAnimationFrame(frame);
    };
    const trigger = (el) => {
      const candidates = Array.from(el.childNodes).filter(
        (n) => n.nodeType === Node.TEXT_NODE && n.data.trim(),
      );
      const textNode =
        candidates.find((n) => /\d/.test(n.data)) || candidates[0];
      if (!textNode) return;
      const match = textNode.data.match(/-?[\d,]+(?:\.\d+)?/);
      if (!match) return;
      const target = parseFloat(match[0].replace(/,/g, ""));
      if (Number.isNaN(target)) return;
      const decimals = (match[0].split(".")[1] || "").length;
      animate(
        textNode,
        textNode.data.slice(0, match.index),
        textNode.data.slice(match.index + match[0].length),
        target,
        decimals,
      );
    };
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return;
          io.unobserve(entry.target);
          trigger(entry.target);
        });
      },
      { threshold: 0.2 },
    );
    const scan = () => {
      document
        .querySelectorAll(
          ".kpi-value, .rb-big, .rb-preview-stat-value, .fund-balance, .dc-kpiValue, .runway-ring-value, .count-up",
        )
        .forEach((el) => {
          if (seen.has(el)) return;
          seen.add(el);
          io.observe(el);
        });
    };
    scan();
    const mo = new MutationObserver(scan);
    mo.observe(document.body, { childList: true, subtree: true });
    return () => {
      io.disconnect();
      mo.disconnect();
    };
  }, []);

  // Pop the floating chat widget open when an unread reply arrives — but only
  // once per unread reply. The previous version re-ran on every page change and
  // unconditionally re-set the flag, so dismissing the widget only lasted until
  // the next tab click. Tracking what we've already offered lets a dismissal
  // stick until something actually new shows up.
  // Every unread state we've already popped the widget for. A set, not a single
  // value, so switching to another client and back doesn't re-offer a reply the
  // user already dismissed.
  const offeredChatFor = useRef(new Set());

  // Signature of the current unread state: which threads are waiting, plus the
  // message count, so a *new* reply in an already-unread thread re-opens the
  // widget. A string, not the array, so the effect doesn't re-run every render.
  const unreadSignature = hasUnreadMessages
    ? selectedClientId +
      "|" +
      unreadThreadUserIds.join(",") +
      "|" +
      liveMessages.length
    : null;

  useEffect(() => {
    // Home already has its own cross-client "Unread messages" card, and the
    // other synthetic staff-only pages (Staff Access, Client Roster,
    // Developer Tools) aren't about any client at all — the floating widget
    // popping up over any of them is redundant at best (Home) and outright
    // confusing at worst (it's scoped to whatever client happened to be
    // last selected, which has nothing to do with that page).
    const canShow =
      access.tabs.has("messages") &&
      effectivePage !== "messages" &&
      !NON_CLIENT_PAGES.has(effectivePage);
    const signature = unreadSignature;

    if (!signature || !canShow) {
      setChatWidgetOpen(false);
      return;
    }

    // Already offered this exact unread state: respect the user's dismissal
    // instead of reopening on navigation or on returning to this client.
    if (offeredChatFor.current.has(signature)) return;

    offeredChatFor.current.add(signature);
    setChatWidgetOpen(true);
  }, [unreadSignature, effectivePage]);

  const closeChatWidget = () => {
    setChatWidgetOpen(false);
    if (siLiveThread) siMsg.markRead();
    if (!activeThreadUserId) return;
    setReadMessageClients((prev) => ({
      ...prev,
      [threadKeyFor(selectedClientId, activeThreadUserId)]: liveMessages.length,
    }));
  };

  // Staff sidebar (desktop; see StaffRail): the same five places on staff
  // pages and on a client's pages alike — a client's own tabs run across
  // the top of its pages (CL_ClientTabs, components/staff/ClientsPage.jsx)
  // instead of down a second sidebar. Hidden while previewing as one of
  // the client's people, so the preview shows only what that person sees.
  const onStaffPage = NON_CLIENT_PAGES.has(effectivePage);
  // Client-side places (CLIENT_PLACES): which place the page belongs to,
  // and the sub-tab for Reports / Messages.
  const clientPlace = CLIENT_placeOf(effectivePage);
  // Finances tab order follows Manage access › Organization tabs (drag ⠿).
  const financeTabKeys = orderedSectionItems(
    NAV_SECTIONS.find((sec) => sec.label === "Finances"),
    tabOrder,
    selectedClientId,
  ).map((i) => i.key);
  const clientReportsSub =
    clientSub.page === "reports" && clientSub.sub === "packet" ? "packet" : "downloads";
  const clientMessagesSub =
    clientSub.page === "messages" && clientSub.sub === "requests" ? "requests" : "conversation";
  const setClientSubFor = (sub) => {
    setClientSub({ page: effectivePage, sub });
    try {
      const base = buildHashRoute(effectivePage, selectedClientId);
      if (base)
        window.history.replaceState(
          window.history.state,
          "",
          window.location.pathname + window.location.search + base + "/" + sub,
        );
    } catch (e) {}
  };
  // Home's "Needs you" list (CLIENT_HomeTop), most urgent first.
  const clientNeeds = (() => {
    const out = [];
    const today = todayLocal();
    const reqs = openDocRequests || [];
    const overdueReqs = reqs.filter((r) => r.due_date && r.due_date < today).length;
    if (reqs.length && access.tabs.has("documents"))
      out.push({
        key: "docs",
        text: `Your bookkeeper needs ${reqs.length} document${reqs.length === 1 ? "" : "s"}`,
        sub: reqs[0].title + (reqs.length > 1 ? ` and ${reqs.length - 1} more` : "") + (overdueReqs ? ` · ${overdueReqs} overdue` : ""),
        action: "See requests",
        tone: overdueReqs ? "urgent" : null,
        onClick: () => {
          setClientSub({ page: "messages", sub: "requests" });
          setPage("messages");
        },
      });
    if (hasUnreadMessages && access.tabs.has("messages"))
      out.push({ key: "msg", text: "New message from your bookkeeper", action: "Read it", onClick: () => setPage("messages") });
    if (budgetAwaiting && access.tabs.has("budget"))
      out.push({ key: "budget", text: "A budget is waiting for your approval", action: "Review", onClick: () => setPage("budget") });
    return out;
  })();
  const showStaffRail = !!(
    isStaffSession &&
    effectiveStaffUser &&
    (onStaffPage || !isPreviewingUser)
  );
  // `html.staff-client-tabs` while a staff member has a client's pages open
  // (not previewing as a client user): clients-page.css hides the client
  // sidebar and lays the tab row across the top. A class on <html> rather
  // than on .app-shell so the sidebar's own media queries can key off it.
  const staffClientTabs = showStaffRail && !isPreviewingUser && !onStaffPage;
  // Admin or temporary admin, and not "viewing as" someone — the one
  // definition the rail, Today, Clients and Team all share.
  const staffIsAdmin =
    !!staffUser && (staffUser.role === "admin" || hasTempAdminAccess) && !impersonating;
  useEffect(() => {
    try {
      document.documentElement.classList.toggle("staff-client-tabs", staffClientTabs);
    } catch (e) {}
    return () => {
      try {
        document.documentElement.classList.remove("staff-client-tabs");
      } catch (e) {}
    };
  }, [staffClientTabs]);
  // Browser tab title: "Today · MyGoodBooks" on a staff page, "Grace
  // Community · Overview · MyGoodBooks" on a client's — so a row of open
  // tabs reads at a glance and history entries have names.
  useEffect(() => {
    try {
      const pageTitle = (PAGE_META[effectivePage] && PAGE_META[effectivePage].title) || "";
      document.title = onStaffPage
        ? [pageTitle, "MyGoodBooks"].filter(Boolean).join(" · ")
        : [client && client.name, pageTitle, "MyGoodBooks"].filter(Boolean).join(" · ");
    } catch (e) {}
  }, [effectivePage, onStaffPage, client && client.name]);
  // A bookkeeper with a real (successful, non-null) assignment fetch but
  // zero checked clients — the opt-in default from staff-client-access.sql.
  // Nothing below this point has a sensible client to show, so stop here
  // rather than let baseClient's CLIENTS[0] fallback silently show data
  // nobody granted them.
  if (assignedClientIds && visibleClients.length === 0) {
    return (
      <div className="boot-splash" role="main">
        <div className="boot-splash-mark">MyGoodBooks</div>
        <div className="boot-splash-sub">
          {clientAccessError
            ? `${effectiveStaffUser.name}, we couldn't check which clients you're assigned to, so nothing is being shown. Reload to try again — if it keeps happening, tell an admin.`
            : `${effectiveStaffUser.name}, you're signed in but no clients are assigned to you yet. Ask an admin to check off at least one client for you under Team → Members.`}
        </div>
        {/* Temporary access is the other way in; an approval widens
            visibleClients and this screen gives way on its own. */}
        {!clientAccessError && !impersonating && (
          <CS_SplashRequestAccess staffUser={effectiveStaffUser} />
        )}
        {impersonating && (
          <button
            onClick={stopImpersonating}
            style={{
              marginTop: 16,
              background: "none",
              border: "none",
              color: "inherit",
              textDecoration: "underline",
              cursor: "pointer",
              font: "inherit",
            }}
          >
            Exit "View as {impersonating.name}"
          </button>
        )}
        <button
          onClick={onSignOut}
          style={{
            marginTop: 16,
            background: "none",
            border: "none",
            color: "inherit",
            textDecoration: "underline",
            cursor: "pointer",
            font: "inherit",
          }}
        >
          Sign out
        </button>
      </div>
    );
  }

  // While the staff top bar is up, its search also covers the open client's
  // data (TB_Search's "In <client>" group), so the page-header GlobalSearch
  // icon steps aside. Clients and client-user previews keep the header one.
  const showStaffTopBar = showStaffRail && typeof TB_StaffTopBar === "function";

  return (
    <ToastProvider>
      <StaffToolsContext.Provider
        value={{
          staff: isStaffSession && viewAsUserId === BOOKKEEPER_VIEW,
          staffUser: effectiveStaffUser,
          // Name of the staffer an admin is viewing as ("View as"), else null.
          viewingAsName: impersonating ? impersonating.name || impersonating.email : null,
        }}
      >
      <div className="mesh-bg" aria-hidden="true">
        <span></span>
        <span></span>
        <span></span>
      </div>
      {typeof PD_PageDrop === "function" && (
        <PD_PageDrop
          // Off on Team > Feedback, which has its own drop zone.
          enabled={
            isStaffSession &&
            !isPreviewingUser &&
            !(effectivePage === "team" && typeof NAV_subFromHash === "function" && NAV_subFromHash("team") === "feedback")
          }
          clients={visibleClients}
          currentClient={onStaffPage ? null : client}
        />
      )}
      <div
        className={
          "app-shell" +
          (isPreviewingUser ? " previewing" : "") +
          (showStaffRail ? " has-staff-rail" : "") +
          (showStaffRail && onStaffPage ? " on-staff-page" : "") +
          (!showStaffRail && !NON_CLIENT_PAGES.has(effectivePage) ? " has-client-tabbar" : "")
        }
      >
        <div className="mobile-topbar">
          <button
            className="hamburger-btn"
            onClick={() => setMobileNavOpen(true)}
            aria-label="Open menu"
          >
            <span></span>
            <span></span>
            <span></span>
          </button>
          <span className="mobile-topbar-title">
            {NON_CLIENT_PAGES.has(effectivePage) ? "MyGoodBooks" : client.name}
          </span>
        </div>
        <div
          className={"sidebar-scrim" + (mobileNavOpen ? " visible" : "")}
          onClick={() => setMobileNavOpen(false)}
        ></div>
        {showStaffRail && (
          <StaffRail
            staffUser={effectiveStaffUser}
            page={effectivePage}
            onSelectPage={setPage}
            // The same rail, expanded or collapsed per the saved preference,
            // on staff pages and client pages alike (no client sidebar to
            // make room for any more).
            expanded={!(halfScreen ? !halfScreenExpanded : sidebarCollapsed)}
            onToggleCollapse={
              halfScreen ? () => setHalfScreenExpanded((v) => !v) : toggleSidebarCollapsed
            }
            staffMessagesUnread={staffMessagesUnread}
            myTasksDue={myTasksDue}
            impersonating={impersonating}
            showsAdminPages={
              (effectiveStaffUser.role === "admin" || hasTempAdminAccess) && !impersonating
            }
            onSignOut={onSignOut}
            hideMark={false}
          />
        )}
        <Sidebar
          clients={visibleClients}
          selectedClientId={selectedClientId}
          onSelectClient={setSelectedClientId}
          client={client}
          viewAsUserId={viewAsUserId}
          onSelectViewAs={setViewAsUserId}
          access={access}
          page={effectivePage}
          onSelectPage={setPage}
          visibleKeys={access.tabs}
          tabOrder={tabOrder}
          onOpenSettingsPage={() => openClientSettings(null)}
          collapsed={halfScreen ? !halfScreenExpanded : sidebarCollapsed}
          onToggleCollapse={
            halfScreen ? () => setHalfScreenExpanded((v) => !v) : toggleSidebarCollapsed
          }
          isStaffSession={isStaffSession}
          previewPlan={isStaffSession ? getPreviewPlan(client.id) : null}
          onPreviewPlan={(plan) => {
            setPreviewPlan(client.id, plan);
            setPreviewPlanRev((n) => n + 1);
          }}
          badges={{
            messages: hasUnreadMessages,
            documents: openDocRequests.length > 0,
          }}
          mobileOpen={mobileNavOpen}
          onCloseMobile={() => setMobileNavOpen(false)}
          staffUser={effectiveStaffUser}
          onSignOut={onSignOut}
          staffMessagesUnread={staffMessagesUnread}
          myTasksDue={myTasksDue}
          hasPendingAccessRequests={hasPendingAccessRequests}
          pendingRequestsByClient={pendingRequestsByClient}
          impersonating={impersonating}
          hasTempAdminAccess={hasTempAdminAccess}
          tempAdminAccessExpiresAt={tempAdminAccessExpiresAt}
          statusOverrides={statusOverrides}
        />
        <main className="main">
          {/* Staff top bar (components/staff/TopBar.jsx): shown wherever the
              staff sidebar is, so clients and client-user previews never see it. */}
          {showStaffTopBar && (
            <TB_StaffTopBar
              staffUser={effectiveStaffUser}
              realStaffUser={staffUser}
              impersonating={impersonating}
              onStopImpersonating={stopImpersonating}
              clients={visibleClients}
              client={onStaffPage ? null : client}
              page={effectivePage}
              plan={access.plan}
              onSynced={() => setQboDataRev((r) => r + 1)}
              statusOverrides={statusOverrides}
              pendingRequestsByClient={pendingRequestsByClient}
              effectiveTheme={effectiveTheme}
              onToggleTheme={() => chooseTheme(effectiveTheme === "dark" ? "light" : "dark")}
              onSignOut={onSignOut}
              onPreviewAs={setViewAsUserId}
              onOpenSettings={() => setPage("settings")}
              previewPlan={!onStaffPage && !impersonating ? getPreviewPlan(client.id) : undefined}
              actualPlan={planShownKey(client.plan)}
              onPreviewPlan={
                !onStaffPage && !impersonating
                  ? (plan) => {
                      setPreviewPlan(client.id, plan);
                      setPreviewPlanRev((n) => n + 1);
                    }
                  : null
              }
              hasTempAdminAccess={hasTempAdminAccess}
              tempAdminAccessExpiresAt={tempAdminAccessExpiresAt}
              clientSearch={
                onStaffPage
                  ? null
                  : {
                      client: scopedClient,
                      messages: liveMessages,
                      visibleKeys: access.tabs,
                      onNavigate: setPage,
                      onHighlight: (r) =>
                        setSearchTarget({ ...r, nonce: Date.now() }),
                    }
              }
            />
          )}
          {!impersonating && !NON_CLIENT_PAGES.has(effectivePage) && (
            <CS_TempAccessNote clientId={client.id} clientName={client.name} />
          )}
          {impersonating && (
            <div className="preview-bar">
              <span>
                Viewing as <strong>{impersonating.name}</strong> —{" "}
                {impersonating.role}. This is exactly what they see when they
                sign in, including their assigned clients and their own
                reminders.
              </span>
              <button className="preview-exit" onClick={stopImpersonating}>
                Exit "View as"
              </button>
            </div>
          )}
          {isPreviewingUser && (
            <div className="preview-bar">
              <span>
                Previewing as <strong>{access.user.name}</strong> —{" "}
                {access.user.role}. This is exactly what they see when they sign
                in.
              </span>
              <button
                className="preview-exit"
                onClick={() => setViewAsUserId(BOOKKEEPER_VIEW)}
              >
                Exit preview
              </button>
            </div>
          )}

          {/* §144-§147: which tab this is, in words — with the sidebar
              collapsible to icons (§142), there was no page name visible
              anywhere once collapsed. The header IS the tab name now
              (was a personal greeting, with the tab name in a small pill
              underneath it — collapsed into one line per feedback: every
              page's header should read exactly like its sidebar entry).
              Gold shimmer follows the client's actual plan
              (access.premiumForUser) for every page uniformly, not the
              narrower "is this one of the six specially-upgraded pages"
              isPremiumPage check subtitles used to use — that left
              Payroll and Documents (neither of which has an upgraded
              variant at all) looking inconsistently un-gold next to
              every other tab on a premium client, even though the
              client itself is still premium on those two pages too.
              Never applied on staff-only pages (Staff Access, Developer
              Tools, …) — those aren't about any one client's plan, so
              shimmering them off whichever client happens to be selected
              in the sidebar would be a non sequitur. */}
          {!NON_CLIENT_PAGES.has(effectivePage) && (
            <StaffQuickActions
              headless
              client={client}
              onNavigate={setPage}
              onMessage={siStaffChat ? () => setSiDrawer({ clientId: client.id }) : undefined}
            />
          )}
          {/* 2026-10-08: one top bar. The page header and the current page's
              tab row share a single surface (styles.css .app-topbar): white
              over the cream page in light, the sidebar colour in dark so rail,
              tool bar and header read as one frame. NAV_TabRow
              (components/staff/StaffNav.jsx) portals a page's tabs into
              #app-topbar-tabs below. */}
          <div className="app-topbar">
          <div className="page-header app-header">
            <div>
              {/* Staff on a client's pages get "Clients › Grace Community ›
                  Overview" (CL_Breadcrumb, components/staff/ClientsPage.jsx)
                  so there's always a way back to the list; a client sees
                  their own name. */}
              <div className="portal-greeting">
                {NON_CLIENT_PAGES.has(effectivePage)
                  ? "MyGoodBooks"
                  : staffClientTabs && typeof CL_Breadcrumb === "function"
                    ? (
                        <CL_Breadcrumb
                          client={client}
                          page={effectivePage}
                          onOpenClients={() => setPage("clients")}
                          onOpenOverview={() => setPage("client-overview")}
                        />
                      )
                    : client.name}
              </div>
              <h1 className={"page-title"}>
                {(!staffClientTabs && clientPlace && clientPlace.tabs && clientPlace.label) ||
                  NAV_LABEL_BY_KEY[effectivePage] ||
                  (meta && meta.title) ||
                  (NON_CLIENT_PAGES.has(effectivePage)
                    ? "MyGoodBooks"
                    : client.name)}
              </h1>
              <div className={"page-subtitle"}>
                {showsLiveReport && client.dataSource === "quickbooks"
                  ? `Your financial snapshot. ${syncCadenceLabel(access.plan)}.`
                  : effectivePage === "client-settings" && isStaffSession && !isPreviewingUser
                    ? "Staff: this client's access, details and plan"
                    : meta.subtitle}
              </div>
            </div>
            <div className="page-header-actions-stack">
            {/* The milestone badge moved to the client sidebar, under the
                tagline (Sidebar, .sidebar-ms-row). */}
            <div className="page-header-actions">
              {!showStaffTopBar && <AN_AppNav />}
              {/* "View as client" (CL_ViewAsButton): staff preview the
                  portal as one of this client's people, right from the
                  page they're on. Exits via the preview bar above. */}
              {staffClientTabs && typeof CL_ViewAsButton === "function" && (
                <CL_ViewAsButton client={client} onPreviewAs={(uid) => setViewAsUserId(uid)} />
              )}
              {!NON_CLIENT_PAGES.has(effectivePage) &&
                (!isStaffSession || isPreviewingUser) && (
                  <ClientNotifications
                    clientId={client.id}
                    items={[
                      ...(access.tabs.has("documents")
                        ? openDocRequests.map((r) => ({
                            id: "req:" + r.id,
                            title: `Please upload: ${r.title}`,
                            sub: r.due_date ? `Due ${fmtDate(r.due_date)}` : "Requested " + (relTime(r.created_at) || ""),
                            cta: "Upload now",
                            onOpen: () => setPage("documents"),
                          }))
                        : []),
                      ...(siLiveThread && siMsg.unread && access.tabs.has("messages") && effectivePage !== "messages"
                        ? [
                            {
                              id: "msg:" + siMsg.lastId,
                              title: "New message from your bookkeeper",
                              sub: siMsg.lastText ? siMsg.lastText.slice(0, 90) : null,
                              cta: "Open messages",
                              onOpen: () => setPage("messages"),
                            },
                          ]
                        : []),
                      ...(budgetAwaiting && access.isFullAccess
                        ? [
                            {
                              id: `budget:${budgetAwaiting.fiscal_year}:${budgetAwaiting.version}`,
                              title: `Your ${budgetAwaiting.fiscal_year} budget is ready for approval`,
                              sub: budgetAwaiting.submitted_at ? `Sent ${fmtDate(budgetAwaiting.submitted_at)}` : null,
                              cta: "Review budget",
                              onOpen: () => setPage("budget"),
                            },
                          ]
                        : []),
                    ]}
                  />
                )}
              {/* §170: the honest version of this badge. A client whose
                  numbers came out of a real QuickBooks sync gets told when
                  they were last pulled; everyone else still gets the
                  prototype warning, which is still true for them. */}
              {client.dataSource === "quickbooks" ? (
                <QboSyncNowButton
                  clientId={client.id}
                  onSynced={() => setQboDataRev((r) => r + 1)}
                  // Sync now is a Pro feature; staff can always sync.
                  canSyncNow={
                    planSyncInfo(access.plan).syncNow ||
                    (isStaffSession && !isPreviewingUser)
                  }
                  // Every plan says how often it refreshes (PLAN_SYNC).
                  plan={access.plan}
                  lastSyncedAt={client.lastSyncedAt}
                />
              ) : (
                <span className="badge-live badge-live--sample">
                  <span className="badge-dot"></span>
                  {unsyncedPillLabel(client)}
                </span>
              )}
              {!showStaffTopBar && (
                <GlobalSearch
                  client={scopedClient}
                  messages={liveMessages}
                  visibleKeys={access.tabs}
                  onNavigate={setPage}
                  onHighlightResult={(r) =>
                    setSearchTarget({ ...r, nonce: Date.now() })
                  }
                  key={"search-" + client.id}
                />
              )}
            </div>
            </div>
          </div>
          {/* A client's tabs across the top of its pages for staff
              (CL_ClientTabs, components/staff/ClientsPage.jsx): Overview,
              the client's own tabs, SOP, Milestone and a Settings gear.
              Replaces the client sidebar on desktop (html.staff-client-tabs). */}
          {staffClientTabs && typeof CL_ClientTabs === "function" && (
            <CL_ClientTabs
              client={client}
              page={effectivePage}
              access={access}
              isCategoryScoped={access.isCategoryScoped}
              onSelectPage={setPage}
              hasPendingAccessRequests={hasPendingAccessRequests}
              onOpenClientSettings={openClientSettings}
            />
          )}
          {/* Client view: the tabs of the current place (CLIENT_PLACES). */}
          {!staffClientTabs && clientPlace && clientPlace.tabs && (
            <NAV_TabRow
              label="Finances"
              tabs={financeTabKeys
                .filter((k) => access.tabs.has(k))
                .map((k) => ({ key: k, label: NAV_LABEL_BY_KEY[k] || k }))}
              current={effectivePage}
              onSelect={setPage}
              idPrefix="cf"
            />
          )}
          {!staffClientTabs && effectivePage === "reports" && (
            <NAV_TabRow
              label="Reports"
              tabs={[
                { key: "downloads", label: "Downloads" },
                { key: "packet", label: "Board packet" },
              ]}
              current={clientReportsSub}
              onSelect={setClientSubFor}
              idPrefix="cr"
            />
          )}
          {!staffClientTabs && effectivePage === "messages" && (
            <NAV_TabRow
              label="Messages"
              tabs={[
                { key: "conversation", label: "Conversation" },
                { key: "requests", label: "Requests" },
              ]}
              current={clientMessagesSub}
              onSelect={setClientSubFor}
              idPrefix="cm"
            />
          )}
          {/* Slot for the current page's NAV_TabRow (Work, Team, a client's
              tabs). Empty on pages without tabs; CSS hides it then. */}
          <div id="app-topbar-tabs" className="app-topbar-tabs" />
          </div>
          {/* What the client (or staff previewing as them) sees on every
              page while their bookkeeper is waiting on a document. */}
          {!NON_CLIENT_PAGES.has(effectivePage) &&
            effectivePage !== "documents" &&
            // Home's "Needs you" and Messages › Requests already list them.
            effectivePage !== "dashboard" &&
            effectivePage !== "messages" &&
            (!isStaffSession || isPreviewingUser) &&
            access.tabs.has("documents") && (
              <DocRequestBanner
                requests={openDocRequests}
                onOpen={() => setPage("documents")}
              />
            )}

          {/* Client guided tour + Dashboard setup checklist (components/tour/Tour.jsx). */}
          {typeof TOUR_Root === "function" && !NON_CLIENT_PAGES.has(effectivePage) && (
            <TOUR_Root client={client} access={access} page={effectivePage} onSelectPage={setPage} onOpenSettings={openClientSettings} setMobileNavOpen={setMobileNavOpen} clientPortalUser={clientPortalUser} isStaffSession={isStaffSession} isPreviewingUser={Boolean(isPreviewingUser)} impersonating={Boolean(impersonating)} />
          )}
          {/* Staff tour: the five places, Today's list, search and the "?"
              menu (TOUR_StaffRoot, same file). Runs once on a staff member's
              first sign-in; "?" > Take the tour restarts it. */}
          {typeof TOUR_StaffRoot === "function" && showStaffRail && !isPreviewingUser && (
            <TOUR_StaffRoot
              staffUser={staffUser}
              impersonating={Boolean(impersonating)}
              isPreviewingUser={Boolean(isPreviewingUser)}
              page={effectivePage}
              onSelectPage={setPage}
              setMobileNavOpen={setMobileNavOpen}
            />
          )}
          {effectivePage === "dashboard" && !staffClientTabs && (
            <CLIENT_HomeTop
              client={client}
              access={access}
              needs={clientNeeds}
              onOpenMilestone={() => setPage("milestone")}
              onSeePlans={() => setPage("enterprise-upgrade")}
            />
          )}
          {effectivePage === "dashboard" &&
            (access.plan === "basic" ? (
              <CLIENT_LockedCard
                title="Your financial snapshot is part of Pro"
                text="Pro adds cash, income, spending and runway at a glance, plus Budget, Bank accounts and Cash flow. Your statements are always on Reports."
                onSeePlans={() => setPage("enterprise-upgrade")}
              />
            ) : showsLiveReport ? (
              // A premium, full-access client's "Dashboard" IS the Live
              // Report — one cohesive page instead of two separate tabs
              // both claiming to be "the overview." theme is null until the
              // header toggle is used, in which case DailyClose follows the
              // OS setting via its own dark block — identical to the
              // shell's default. Once toggled, the explicit choice is
              // passed through so both sides stay in step. Data is derived
              // from the selected client rather than the shipped Bramblewood
              // sample, so the panel and the rest of the app agree.
              <DailyClose
                data={dailyCloseData || dailyCloseFromClient(client, access.plan)}
                theme={effectiveTheme}
                onNavigate={setPage}
                key={"daily-close-" + client.id}
              />
            ) : access.isCategoryScoped ? (
              <ScopedDashboardPage
                client={scopedClient}
                access={access}
                isBookkeeper={isStaffSession && !isPreviewingUser}
                promoText={referralPromo}
                onSaveReferralPromo={saveReferralPromo}
              />
            ) : (
              <DashboardPage
                client={scopedClient}
                access={access}
                isBookkeeper={isStaffSession && !isPreviewingUser}
                promoText={referralPromo}
                onSaveReferralPromo={saveReferralPromo}
              />
            ))}
          {effectivePage === "budget" &&
            (showsBudgetingTool ? (
              // Pro budget tools (components/pro/ProBudget.jsx); the older
              // BudgetingToolPage stays as a fallback if that file is absent.
              typeof ProBudgetWorkspace === "function" ? (
                <ProBudgetWorkspace
                  client={scopedClient}
                  access={access}
                  clientPortalUser={clientPortalUser}
                  key={"pro-budget-" + client.id}
                />
              ) : (
                <BudgetingToolPage
                  client={scopedClient}
                  key={"budgeting-tool-" + client.id}
                />
              )
            ) : (
              <BudgetPage
                client={scopedClient}
                searchTarget={
                  searchTarget && searchTarget.page === "budget"
                    ? searchTarget
                    : null
                }
              />
            ))}
          {effectivePage === "giving" &&
            // Giving comes from QuickBooks (components/client/QboGiving.jsx).
            // A real (not test-only) client without QuickBooks gets a calm
            // empty state, never sample numbers; only test-only clients
            // without QuickBooks keep the sample Giving pages.
            (scopedClient.dataSource === "quickbooks" ? (
              // Pro: the full Giving & Funds page, fed from QuickBooks.
              showsFundAccountingPro && !scopedClient.givingQboHidden ? (
                <FundAccountingProPage
                  client={scopedClient}
                  qbo
                  plan={access.plan}
                  isStaff={isStaffSession && !isPreviewingUser}
                  key={"fund-accounting-pro-qbo-" + client.id}
                />
              ) : typeof QG_QboGivingPage === "function" ? (
                <QG_QboGivingPage
                  client={scopedClient}
                  plan={access.plan}
                  isStaff={isStaffSession && !isPreviewingUser}
                />
              ) : (
                <GivingNotConnected client={scopedClient} />
              )
            ) : isRealClientWithoutQbo(scopedClient) ? (
              typeof QG_GivingEmptyState === "function" ? (
                <QG_GivingEmptyState client={scopedClient} />
              ) : (
                <GivingNotConnected client={scopedClient} />
              )
            ) : showsFundAccountingPro ? (
              <FundAccountingProPage
                client={scopedClient}
                key={"fund-accounting-pro-" + client.id}
              />
            ) : (
              <GivingFundsPage client={scopedClient} />
            ))}
          {effectivePage === "receivables" &&
            (showsCashFlowPro ? (
              <APCommandCenterPage
                client={scopedClient}
                key={"ap-command-center-" + client.id}
              />
            ) : (
              <ReceivablesPayablesPage client={scopedClient} />
            ))}
          {effectivePage === "bank" &&
            (showsReconciliationPro ? (
              <BankReconciliationPage
                client={scopedClient}
                searchTarget={
                  searchTarget && searchTarget.page === "bank"
                    ? searchTarget
                    : null
                }
                isClientUser={!!clientPortalUser}
                key={"bank-reconciliation-" + client.id}
              />
            ) : (
              <BankPage
                client={scopedClient}
                searchTarget={
                  searchTarget && searchTarget.page === "bank"
                    ? searchTarget
                    : null
                }
                isClientUser={!!clientPortalUser}
                key={"bank-" + client.id}
              />
            ))}
          {effectivePage === "payroll" && (
            <PayrollPage
              client={scopedClient}
              clientPortalUser={clientPortalUser}
              key={"payroll-" + client.id}
            />
          )}
          {/* Reports: Downloads (every plan) and Board packet (Pro; Basic
              sees the locked card). Staff keep the old single view. */}
          {effectivePage === "reports" &&
            ((staffClientTabs ? showsReportBuilder : clientReportsSub === "packet") ? (
              showsReportBuilder ? (
                <>
                  <ReportBuilderPage
                    client={scopedClient}
                    key={"report-builder-" + client.id}
                  />
                  {/* Pro report tools (components/pro/ProReports.jsx). */}
                  {typeof ProReportsSuite === "function" && (
                    <ProReportsSuite
                      client={scopedClient}
                      access={access}
                      clientPortalUser={clientPortalUser}
                      key={"pro-reports-" + client.id}
                    />
                  )}
                </>
              ) : (
                <CLIENT_LockedCard
                  title="Board packet is part of Pro"
                  text="Assemble a formatted packet for your board in three steps: pick the reports, add a note, download one PDF. Downloads of your statements stay on the Downloads tab."
                  onSeePlans={() => setPage("enterprise-upgrade")}
                />
              )
            ) : (
              <ReportsPage client={scopedClient} />
            ))}
          {/* Settings (components/settings/Settings.jsx). The Plans page
              ("enterprise-upgrade") is client Settings' Plan tab now. */}
          {effectivePage === "settings" && (
            <ST_StaffSettingsPage
              staffUser={staffUser}
              readOnlyReason={
                impersonating
                  ? `You're viewing as ${impersonating.name}. Settings here are yours, not theirs, so they can't be changed until you stop viewing as.`
                  : null
              }
              isAdmin={!!staffUser && staffUser.role === "admin" && !impersonating}
              hasTempAdminAccess={hasTempAdminAccess && !impersonating}
              clients={visibleClients}
              theme={theme}
              onChooseTheme={chooseTheme}
              onSignOut={onSignOut}
              onSelectPage={setPage}
            />
          )}
          {effectivePage === "client-settings" && (
            <ST_ClientSettingsPage
              key={"client-settings-" + client.id}
              client={client}
              access={access}
              mode={clientPortalUser ? "client" : isPreviewingUser ? "preview" : "staff"}
              signedInEmail={clientPortalUser ? clientPortalUser.email : null}
              tab={settingsTab}
              onTab={setSettingsTab}
              theme={theme}
              onChooseTheme={chooseTheme}
              onSignOut={onSignOut}
              onSelectPage={setPage}
              renderPlan={() => (
                <EnterpriseUpgradePage
                  client={scopedClient}
                  clientPortalUser={clientPortalUser}
                  key={"enterprise-upgrade-" + client.id}
                />
              )}
              onOpenAccess={() => setSettingsOpen(true)}
              onOpenDetails={() => {
                setDetailsTab(null);
                setDetailsOpen(true);
              }}
              hasPendingAccessRequests={hasPendingAccessRequests}
            />
          )}
          {/* The five staff places (components/staff/StaffNav.jsx). Each
              hub owns its own tab row and reads the tab from the hash
              (#/work/close, #/team/reviews), so App only mounts the hub.
              Today, Clients, Work and the client tab row are separate
              files (Today.jsx, ClientsPage.jsx, WorkPage.jsx) that may
              still be loading in a partial build — hence the typeof
              guards. Same gating as the pages they replaced. */}
          {/* Team (components/staff/TeamPage.jsx, TP_TeamHub): People,
              Reviews, Onboarding and, for admins, Hours, Reply times,
              Feedback and Members (the old Staff Access page). */}
          {effectivePage === "team" && typeof TP_TeamHub === "function" && (
            <TP_TeamHub
              staffUser={effectiveStaffUser}
              isAdmin={staffIsAdmin}
              isRealAdmin={staffUser.role === "admin" && !impersonating}
              clients={visibleClients}
              renderMembers={() => (
                <StaffAccessPage
                  staffUser={staffUser}
                  onImpersonate={startImpersonating}
                  readOnly={staffUser.role !== "admin"}
                />
              )}
            />
          )}
          {effectivePage === "client-access" && (
            <ClientAccessPage readOnly={staffUser.role !== "admin"} />
          )}
          {effectivePage === "inbox" && (
            <StaffMessagesPage
              staffUser={staffUser}
              onActivity={checkStaffMessagesUnread}
              clients={visibleClients}
              sampleThreads={messagesByClient}
              onSampleSend={sampleInboxSend}
              onOpenClient={openClientMessages}
            />
          )}
          {/* Work (components/staff/WorkPage.jsx): Tasks, Close, Deadlines. */}
          {effectivePage === "work" && typeof WK_WorkPage === "function" && (
            <WK_WorkPage
              clients={visibleClients}
              staffUser={effectiveStaffUser}
              statusOverrides={statusOverrides}
              canManageTemplates={staffIsAdmin}
              canCreateTemplates={staffUser.role === "admin" && !impersonating}
              onOpenTemplates={() => setPage("task-templates")}
            />
          )}
          {/* Clients (components/staff/ClientsPage.jsx): every client this
              person can see, with health, close status and who's on it.
              A row opens that client's Overview (or the page it asks for)
              — the requested page must be parked in pageAfterClientSwitch
              before the client changes, or the switch reset would bounce
              it to Overview. */}
          {effectivePage === "clients" && typeof CL_ClientsPage === "function" && (
            <CL_ClientsPage
              clients={visibleClients}
              staffUser={effectiveStaffUser}
              isAdmin={staffIsAdmin}
              statusOverrides={statusOverrides}
              pendingRequestsByClient={pendingRequestsByClient}
              onOpenClient={(id, p) => {
                if (id === selectedClientId) setPage(p || "client-overview");
                else {
                  pageAfterClientSwitch.current = p || "client-overview";
                  setSelectedClientId(id);
                }
              }}
            />
          )}
          {/* A client's SOP as a tab of its pages (staff only; the client
              Settings modal keeps its read-only copy). */}
          {effectivePage === "sop" && (
            <ClientSopView client={client} readOnly={false} key={"sop-" + client.id} />
          )}
          {effectivePage === "client-overview" && (
            <ClientOverviewPage
              client={client}
              messagesByClient={messagesByClient}
              onNavigate={setPage}
              onOpenDetails={(tab) => {
                setDetailsTab(tab || null);
                setDetailsOpen(true);
              }}
              key={"overview-" + client.id}
            />
          )}
          {effectivePage === "milestone" && (
            <MilestonePage
              client={client}
              isStaff={isStaffSession && !isPreviewingUser}
              key={"milestone-" + client.id}
            />
          )}
          {effectivePage === "developer-tools" && (
            <DeveloperToolsPage
              staffUser={staffUser}
              readOnly={staffUser.role !== "admin"}
            />
          )}
          {effectivePage === "usage-stats" && <UsageStatsPage />}
          {effectivePage === "audit-log" && typeof AL_AuditLogPage === "function" && (
            <AL_AuditLogPage clients={visibleClients} />
          )}
          {effectivePage === "emails" && typeof EM_EmailsPage === "function" && <EM_EmailsPage />}
          {effectivePage === "task-templates" && <TT_TaskTemplatesPage clients={visibleClients} />}
          {effectivePage === "help" && typeof HLP_StaffGuidePage === "function" && <HLP_StaffGuidePage />}
          {/* Today (components/staff/Today.jsx): what needs this person, in
              order, across every client they can see. */}
          {effectivePage === "today" && typeof TD_TodayPage === "function" && (
            <TD_TodayPage
              staffUser={effectiveStaffUser}
              clients={visibleClients}
              messagesByClient={messagesByClient}
              readMessageClients={readMessageClients}
              isAdmin={staffIsAdmin}
              onNavigateToClient={(clientId, targetPage, opts) => {
                // Keep the requested page through the client-switch reset.
                if (clientId !== selectedClientId) pageAfterClientSwitch.current = targetPage;
                setSelectedClientId(clientId);
                setPage(targetPage);
                // §169: the Access requests card sends the staffer straight
                // to the panel that actions the thing they just clicked,
                // rather than dropping them on the dashboard to find it.
                if (opts && opts.openAccessManager) setSettingsOpen(true);
              }}
              onOpenClientMilestone={(clientId) => {
                if (clientId !== selectedClientId) pageAfterClientSwitch.current = "milestone";
                setSelectedClientId(clientId);
                setPage("milestone");
              }}
              statusOverrides={statusOverrides}
              onStatusOverridesChanged={loadStatusOverrides}
            />
          )}
          {effectivePage === "documents" && (
            <DocumentsPage
              client={scopedClient}
              isBookkeeper={isStaffSession && !isPreviewingUser}
              searchTarget={
                searchTarget && searchTarget.page === "documents"
                  ? searchTarget
                  : null
              }
              key={"docs-" + client.id}
            />
          )}
          {effectivePage === "messages" &&
            // Staff in the bookkeeper view get the inbox, limited to this
            // client's people; clients (and previews) the plain thread.
            (isStaffSession && !isPreviewingUser && typeof StaffInbox === "function" ? (
              <StaffInbox
                staffUser={staffUser}
                clients={siInboxClients}
                lockClientId={client.id}
                initialEmail={inboxFocusEmail}
                sampleThreads={messagesByClient}
                onSampleSend={sampleInboxSend}
                key={"inbox-" + client.id + "-" + (inboxFocusEmail || "")}
              />
            ) : clientMessagesSub === "requests" ? (
              <CLIENT_RequestsPanel
                requests={docRequestsList.rows}
                canUpload={access.tabs.has("documents")}
                onOpenDocuments={() => setPage("documents")}
              />
            ) : (
            <MessagesPage
              client={scopedClient}
              messages={liveMessages}
              live={siLiveThread}
              loadStatus={
                !siLiveThread
                  ? "real"
                  : siMsg.status === "off" || (siMsg.status === "error" && siMsg.reason === "missing")
                    ? "unavailable"
                    : siMsg.status
              }
              onRetry={siLiveThread ? siMsg.retry : undefined}
              hasEarlier={siLiveThread && !!siMsg.hasMore}
              onLoadEarlier={siLiveThread ? siMsg.loadEarlier : undefined}
              loadingEarlier={siLiveThread && siMsg.loadingEarlier}
              readAt={siLiveThread ? siMsg.readAt : null}
              staffReadAt={siLiveThread ? siMsg.staffReadAt : null}
              onRetrySend={siLiveThread ? siMsg.retrySend : undefined}
              onDiscardSend={siLiveThread ? siMsg.discardSend : undefined}
              onDeleteMessage={siLiveThread && !siMsg.readOnly ? siMsg.deleteMessage : undefined}
              onAttachmentUrl={siLiveThread ? siMsg.attachmentUrl : undefined}
              validateAttachment={siLiveThread ? siMsg.checkFile : undefined}
              readOnlyNote={
                siLiveThread && siMsg.readOnly
                  ? "You're previewing this person's real conversation. Reply to them from the Inbox."
                  : undefined
              }
              onSend={(text, attachment) =>
                siLiveThread
                  ? siMsg.send(text, attachment)
                  : sendMessage(
                      selectedClientId,
                      activeThreadUserId,
                      text,
                      attachment,
                    )
              }
              users={clientUsers}
              activeUserId={activeThreadUserId}
              onSelectUser={setBookkeeperThreadUserId}
              unreadUserIds={unreadThreadUserIds}
              isBookkeeper={isStaffSession && !isPreviewingUser}
              bookkeeperTyping={bookkeeperTyping}
              searchTarget={
                searchTarget && searchTarget.page === "messages"
                  ? searchTarget
                  : null
              }
              key={"msgs-" + client.id + "-" + activeThreadUserId}
            />
            ))}

          <div className="main-footer">
            {isStaffSession && !isPreviewingUser
              ? "Client and preview switchers are bookkeeper-side tools. Clients never see them."
              : `Signed in to ${client.name || "your organization"}. Access is managed by MyGoodBooks.`}
            <div className="main-footer-links">
              <a href="/privacy" target="_blank" rel="noopener noreferrer">
                Privacy Policy
              </a>
              <span aria-hidden="true"> · </span>
              <a href="/terms" target="_blank" rel="noopener noreferrer">
                Terms of Service
              </a>
              <span aria-hidden="true"> · </span>
              <a href="mailto:admin@mygoodbooks.org?subject=MyGoodBooks%20Support">
                Contact support
              </a>
            </div>
          </div>
        </main>
        {!showStaffRail && !NON_CLIENT_PAGES.has(effectivePage) && (
          <CLIENT_TabBar
            page={effectivePage}
            visibleKeys={access.tabs}
            badges={{ messages: hasUnreadMessages, documents: openDocRequests.length > 0 }}
            onSelect={setPage}
            onOpenSettings={() => openClientSettings()}
          />
        )}
      </div>

      {siStaffChat && effectivePage !== "inbox" && !siDrawer && (
        <SI_ChatLauncher
          unread={staffMessagesUnread}
          onOpen={() =>
            setSiDrawer({ clientId: NON_CLIENT_PAGES.has(effectivePage) ? null : client.id })
          }
        />
      )}
      {siStaffChat && siDrawer && (
        <SI_ChatDrawer
          staffUser={staffUser}
          onActivity={checkStaffMessagesUnread}
          clients={visibleClients}
          defaultClientId={siDrawer.clientId}
          sampleThreads={messagesByClient}
          onSampleSend={sampleInboxSend}
          onOpenClient={openClientMessages}
          onClose={() => setSiDrawer(null)}
        />
      )}

      {chatWidgetOpen && !siStaffChat && (
        // Same tap-to-open button on every screen size now — see ChatFab's
        // own comment for why the floating mini-thread this replaced isn't
        // worth keeping even on desktop.
        <ChatFab
          unreadCount={unreadThreadUserIds.length}
          onOpen={() => {
            setPage("messages");
            closeChatWidget();
          }}
          onDismiss={closeChatWidget}
        />
      )}

      {settingsOpen && (
        <TabSettingsModal
          scope="access"
          client={client}
          visibleKeys={visibleKeys}
          tabOrder={tabOrder}
          userAccess={userAccess}
          onToggle={toggleTab}
          onReorder={reorderTab}
          onToggleUserTab={toggleUserTab}
          onToggleUserCategory={toggleUserCategory}
          onToggleUserFund={toggleUserFund}
          onSetAccessLevel={setAccessLevel}
          onToggleUserPremium={toggleUserPremium}
          staffUser={staffUser}
          onClose={() => {
            setSettingsOpen(false);
            checkPendingAccessRequests();
          }}
        />
      )}

      {detailsOpen && (
        <TabSettingsModal
          scope="details"
          client={client}
          visibleKeys={visibleKeys}
          tabOrder={tabOrder}
          userAccess={userAccess}
          onToggle={toggleTab}
          onReorder={reorderTab}
          onToggleUserTab={toggleUserTab}
          onToggleUserCategory={toggleUserCategory}
          onToggleUserFund={toggleUserFund}
          onSetAccessLevel={setAccessLevel}
          onToggleUserPremium={toggleUserPremium}
          staffUser={staffUser}
          // "Edit the SOP" opens the client's own SOP tab (#/client/<id>/sop)
          // rather than the read-only copy in this modal.
          onOpenSop={(clientId) => {
            setDetailsOpen(false);
            if (clientId && clientId !== selectedClientId) {
              pageAfterClientSwitch.current = "sop";
              setSelectedClientId(clientId);
            } else setPage("sop");
          }}
          initialTab={detailsTab}
          onClose={() => {
            setDetailsOpen(false);
            setDetailsTab(null);
          }}
        />
      )}

      {feedbackOpen && (
        <FeedbackSurveyModal
          actorEmail={
            clientPortalUser ? clientPortalUser.email : staffUser.email
          }
          actorRole={clientPortalUser ? "client" : "staff"}
          clientId={
            NON_CLIENT_PAGES.has(effectivePage) ? null : selectedClientId
          }
          featureOptions={feedbackFeatureOptions}
          onClose={() => setFeedbackOpen(false)}
        />
      )}
      </StaffToolsContext.Provider>
    </ToastProvider>
  );
}

// A client's access-request form (see AccessRequestForm above) is reached by
// its own link — ?access-form=<token> — and has to render before AuthGate
// even mounts: the person filling it out has no MyGoodBooks account and
// never will, so gating it behind staff login would make the link useless.
const accessFormToken = new URLSearchParams(window.location.search).get(
  "access-form",
);
// Read-only report share link (?share=<token>): a public page, no sign-in.
const reportShareToken = new URLSearchParams(window.location.search).get("share");

// Phase 2 (real client login) entry point — see components/auth/ClientAuthGate.jsx
// and supabase/client-auth-phase2.sql. Reached the same way as the access
// form: its own query param, checked before AuthGate, since a client signing
// in for real is never a staff member. Renders the same <App> staff use, just
// with clientPortalUser set instead of staffUser — see the comment on App's
// definition for how that pins it to one client with no staff chrome.
// /login is the friendly path (vercel.json rewrites it to index.html, since
// this is otherwise a static single-page app with no server-side router);
// ?client-login=1 stays supported for any link already sent out before
// this existed.
const clientLoginMode =
  window.location.pathname === "/login" ||
  new URLSearchParams(window.location.search).get("client-login") === "1";

// The bare site URL is the client front door: signed out, it shows the
// client login (whose "Staff? Sign in with Google" button starts the staff
// flow). A session whose email is on the staff Workspace domain goes to the
// staff AuthGate instead, so staff bookmarks and the Google return trip to
// "/" still land in the staff app. This only picks which gate renders; each
// gate still verifies its own table (staff / client_users), so the domain
// check grants nothing by itself.
function RootGate() {
  const [mode, setMode] = React.useState(clientLoginMode ? "client" : null);
  React.useEffect(() => {
    if (mode) return;
    const supabase = window.mgbSupabase;
    if (!supabase) {
      setMode("staff"); // AuthGate renders its "not configured" screen
      return;
    }
    supabase.auth.getSession().then(({ data }) => {
      const email = (data.session && data.session.user.email) || "";
      setMode(
        email.toLowerCase().endsWith("@mygoodbooks.org") ? "staff" : "client",
      );
    });
  }, []);

  if (!mode) {
    return (
      <div className="boot-splash" role="status" aria-live="polite">
        <div className="boot-splash-mark">MyGoodBooks</div>
        <div className="boot-splash-sub">Checking sign-in…</div>
      </div>
    );
  }
  if (mode === "client") {
    return (
      <ClientAuthGate>
        {(clientUser, onSignOut) => (
          <ClientPortalGuard clientUser={clientUser} onSignOut={onSignOut} />
        )}
      </ClientAuthGate>
    );
  }
  return (
    <AuthGate>
      {(staffUser, onSignOut) => (
        <App staffUser={staffUser} onSignOut={onSignOut} />
      )}
    </AuthGate>
  );
}

function ClientPortalGuard({ clientUser, onSignOut }) {
  // Client data (bank accounts, budget, transactions...) is still mock
  // data.js, not real tables (Phase 3) — a real client_users row whose
  // client_id has no matching CLIENTS entry has nothing to actually show.
  if (!CLIENTS.some((c) => c.id === clientUser.client_id)) {
    return (
      <div className="boot-splash" role="alert">
        <div className="boot-splash-mark">MyGoodBooks</div>
        <div className="boot-splash-sub">
          {clientUser.name}'s account isn't linked to a client MyGoodBooks has
          set up yet.
        </div>
        <button
          className="btn-secondary"
          style={{ marginTop: 16 }}
          onClick={onSignOut}
        >
          Sign out
        </button>
      </div>
    );
  }
  return <App clientPortalUser={clientUser} onSignOut={onSignOut} />;
}

// AuthGate (components/auth/AuthGate.jsx) is the Phase-1 login gate: it only
// calls this render prop once a Supabase session exists AND that email is an
// active row in the `staff` table. Until auth-config.js has real Supabase
// credentials, AuthGate shows a "not configured" screen instead — the rest of
// the app is unreachable either way, by design.
ReactDOM.createRoot(document.getElementById("root")).render(
  <ErrorBoundary>
    {reportShareToken && typeof ReportShareView === "function" ? (
      <ReportShareView token={reportShareToken} />
    ) : accessFormToken ? (
      <AccessRequestForm token={accessFormToken} />
    ) : (
      <RootGate />
    )}
  </ErrorBoundary>,
);
